-- Texte der Ortsseiten (Plan docs/plan-locations-2026-11-18.md, 3.14, Schritt 4)
-- Erzeugt am 2026-11-20 von `python -m scraper.orte.spielstaetten_texte --sql` aus data/spielstaetten/texte.csv
-- (nur Zeilen mit freigabe = ja und ohne Prüffehler). Jeder Satz hat eine Quelle (extras.spielstaette.
-- text_freigegeben.quellen). Absätze per Leerzeile, **fett** zeigt die Ortsseite. Wiederholbar.

BEGIN;

UPDATE public.orte SET beschreibung = $txt$**4PADEL Düsseldorf** ist eine Anlage für **Padel** an der Straße Am Gatherhof. Sie gehört zur Padel-Kette **4PADEL**, die in Deutschland außerdem Clubs in Berlin, Essen, Mülheim an der Ruhr und Münster betreibt.$txt$, webseite = COALESCE(webseite, 'https://www.4padel.de/dusseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.4padel.de/nos-centres", "https://www.4padel.de/nos-centres"]}}'::jsonb)
WHERE slug = '4padel' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Alte Bahnhof** am Belsenplatz in Düsseldorf-Oberkassel ist eine Hausbrauerei mit Restaurant im denkmalgeschützten früheren Bahnhofsgebäude. Der Bahnhof wurde im Januar 1853 an der Strecke von Mönchengladbach nach Düsseldorf eröffnet, das heutige Empfangsgebäude stammt von 1896. Wegen der Konkurrenz der Straßenbahn wurde der Personenverkehr 1902 eingestellt, der Güterverkehr endete 1972.

Schon 1902 wurden die Warteräume zu einem **Restaurant** umgebaut. Nach einer Sanierung in den 1990er-Jahren eröffnete dort das Brauhaus Belsenbräu, das später mehrfach umbenannt wurde. Seit 2008 braut das Haus wieder eigenes Bier. Zum Brauhaus gehören Schwemme, Restaurant, **Biergarten** und Festräume, die Küche ist rheinisch-gutbürgerlich.$txt$, webseite = COALESCE(webseite, 'https://www.brauhaus-alterbahnhof.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.brauhaus-alterbahnhof.de/", "https://de.wikipedia.org/wiki/Alter_Bahnhof_Oberkassel", "https://de.wikipedia.org/wiki/Alter_Bahnhof_Oberkassel", "https://de.wikipedia.org/wiki/Alter_Bahnhof_Oberkassel", "https://de.wikipedia.org/wiki/Alter_Bahnhof_Oberkassel", "https://de.wikipedia.org/wiki/Alter_Bahnhof_Oberkassel", "https://www.brauhaus-alterbahnhof.de/"]}}'::jsonb)
WHERE slug = 'alter-bahnhof-oberkassel' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Another Cotton Lab Store** in der **Carlstadt** ist der erste Flagship-Store der in Düsseldorf verwurzelten Modemarke Another Cotton Lab. Der Laden wurde im April 2025 eröffnet. Präsentiert wird die Ware auf dunklen Holzmöbeln über einem Fischgrätparkett.

Zu den bekanntesten Stücken der Marke gehören Shirts und Hoodies mit dem Aufdruck „Sunday Running Club“. Der gleichnamige **Sunday Running Club** ist ein Lauftreff der Marke, der sonntags morgens vor dem Laden startet. Nach dem Lauf gibt es Kaffee im Store, einmal im Monat finden zudem größere Sonderläufe statt.$txt$, webseite = COALESCE(webseite, 'https://anothercotton.com'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/12/16/another-cotton-lab-carlstadt-duesseldorf/"]}}'::jsonb)
WHERE slug = 'another-cotton-lab-store' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Aquazoo Löbbecke Museum** ist eine Einrichtung der Stadt Düsseldorf, die Zoo, Aquarium und Naturkundemuseum unter einem Dach verbindet. Seine Wurzeln liegen in der Sammlung des Apothekers **Theodor Löbbecke**, die nach seinem Tod 1901 an die Stadt fiel. Als Löbbecke-Museum wurde die Sammlung 1904 in der Altstadt eröffnet und 1930 in den damaligen Düsseldorfer Zoo eingegliedert.

Nach schweren Kriegsschäden im Jahr 1944 war die Einrichtung zunächst provisorisch in einem Hochbunker untergebracht. 1987 zog sie in einen Neubau im **Nordpark**, wo sie bis heute ihren Sitz hat. Nach einer umfassenden Sanierung ab 2013 wurde das Haus im September 2017 wiedereröffnet.

Der Rundgang führt durch Themenräume mit Aquarien, Terrarien und einer **Tropenhalle** und folgt der Entwicklung des Lebens vom Meer über das Süßwasser bis an Land. Ergänzt werden die lebenden Tiere durch Skelette, Präparate und Minerale. Die nächste Haltestelle ist **Nordpark/Aquazoo**, angefahren von den U-Bahn-Linien U78 und U79.$txt$, webseite = COALESCE(webseite, 'https://aquazoo-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/aquazoo", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://de.wikipedia.org/wiki/Aquazoo_–_Löbbecke_Museum", "https://aquazoo-duesseldorf.de/", "https://aquazoo-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'aquazoo-loebbecke-museum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Areal Böhler** ist ein früheres Stahlwerksgelände an der Grenze zwischen Düsseldorf und Meerbusch, dessen denkmalgeschützte **Industriearchitektur** heute für Messen, Events und Kongresse genutzt wird. Das österreichische Unternehmen Böhler kaufte das Grundstück in Büderich 1914 und nahm 1915 die Stahlproduktion auf. Das Pförtnerhaus entstand auf Düsseldorfer Gebiet, wodurch das Werk eine Düsseldorfer Adresse erhielt. Die Produktion in Schmiede und Stahlwerk endete 1993.

Das Gelände umfasst rund 230.000 Quadratmeter, davon dienen etwa 18.000 Quadratmeter in Hallen und 10.000 Quadratmeter im Freien als **Eventflächen**. Zu den Veranstaltungen gehört etwa die Kunstmesse **Art Düsseldorf**. Außerdem gibt es Gastronomie und Freizeitangebote wie Padel, Wellenreiten und Beachvolleyball.$txt$, webseite = COALESCE(webseite, 'https://areal-boehler.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://areal-boehler.de/", "https://de.wikipedia.org/wiki/Datei:Areal_B%C3%B6hler,_November_2016.jpg", "https://de.wikipedia.org/wiki/Datei:Areal_B%C3%B6hler,_November_2016.jpg", "https://de.wikipedia.org/wiki/Datei:Areal_B%C3%B6hler,_November_2016.jpg", "https://areal-boehler.de/", "https://areal-boehler.de/", "https://areal-boehler.de/"]}}'::jsonb)
WHERE slug = 'areal-boehler' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **ASG-Bildungsforum** ist eine gemeinnützige Bildungseinrichtung, die seit 1954 besteht und sich auf ein christliches Menschenbild beruft. Träger ist die Arbeitsgemeinschaft Sozialpädagogik und Gesellschaftsbildung, ein gemeinnütziger Verein, der vom Land NRW als Weiterbildungsanbieter und Träger der freien Jugendhilfe anerkannt ist.

An der Gerresheimer Straße 90 in **Flingern** befinden sich die Zentrale und ein **Familientreff**. Das Programm reicht von Angeboten für Schwangere, Eltern und Familien über Sprach- und Deutschkurse bis zu Fitness, Kochkursen, Kunst, Politik und Glaubensthemen.$txt$, webseite = COALESCE(webseite, 'https://www.asg-bildungsforum.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.asg-bildungsforum.de/", "https://www.ddorf-aktuell.de/?p=89405", "https://www.ddorf-aktuell.de/?p=89405", "https://www.asg-bildungsforum.de/"]}}'::jsonb)
WHERE slug = 'asg-bildungsforum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Ashtanga Yoga Schule Düsseldorf** liegt in einem Hinterhof an der Grafenberger Allee, in der Nähe des Stauffenplatzes. Unterrichtet wird **Ashtanga Vinyasa Yoga**, unter anderem im Mysore Style, als Led Class und als Selfpractice. Der **Mysore Style** ist auch für Anfänger geeignet, daneben gibt es Anfängerkurse, Pranayama-Workshops und Einzelstunden.$txt$, webseite = COALESCE(webseite, 'https://astanga-yoga.net/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://astanga-yoga.net/kurse/", "https://astanga-yoga.net/kurse/", "https://astanga-yoga.net/kurse/"]}}'::jsonb)
WHERE slug = 'ashtanga-yoga-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**ausARTen** ist ein Anbieter von **Malworkshops** und Kreativ-Events in Düsseldorf. Das Programm reicht von offenen **Action-Painting**-Kursen bis zu privaten Formaten wie Brunch & Paint, Dance and Paint oder Familien-Workshops. Auch Teambuilding-Events und Junggesellenabschiede werden angeboten.$txt$, webseite = COALESCE(webseite, 'https://ausarten-workshop.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://ausarten-workshop.de/", "https://ausarten-workshop.de/", "https://ausarten-workshop.de/"]}}'::jsonb)
WHERE slug = 'ausarten' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **b41** an der Brehmstraße ist der Düsseldorfer Ausstellungsraum von **Baustelle Schaustelle**, einem nicht-kommerziellen Projektraum für junge Kunst mit einem weiteren Standort in Essen. Der gemeinnützige Verein Baustelle Schaustelle wurde 2007 gegründet und fördert den künstlerischen Nachwuchs aus der Region.

Gezeigt werden vor allem **Einzel- und Gruppenausstellungen** junger Künstlerinnen und Künstler, für viele ist es die erste Ausstellung außerhalb der Hochschule. Der Verein vergibt zudem einen bundesweit ausgeschriebenen **Kunstpreis** für junge Künstlerinnen und Künstler, verbunden mit einer Ausstellung der prämierten Arbeiten. Seit September 2017 ergänzt die Reihe **ZU GAST** in Düsseldorf das Programm um Performances, Vorträge und Talks. Verkauft werden die ausgestellten Arbeiten vom Verein nicht.$txt$, webseite = COALESCE(webseite, 'https://www.baustelle-schaustelle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.baustelle-schaustelle.de/about/kontakt/", "https://www.baustelle-schaustelle.de/about/ueber-uns/", "https://www.baustelle-schaustelle.de/about/ueber-uns/", "https://www.baustelle-schaustelle.de/about/ueber-uns/", "https://www.baustelle-schaustelle.de/about/ueber-uns/", "https://www.baustelle-schaustelle.de/about/ueber-uns/"]}}'::jsonb)
WHERE slug = 'b41' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Badminton-Center Mörsenbroich** ist eine Badmintonhalle am Vogelsanger Weg im Düsseldorfer Stadtteil **Mörsenbroich**. Die Halle bietet 18 Felder mit gelenkschonendem **Schwingboden** und LED-Beleuchtung. Zur Anlage gehört ein Badminton-Fachgeschäft mit Besaitungsservice. Direkt an der Halle stehen Parkplätze zur Verfügung.$txt$, webseite = COALESCE(webseite, 'https://www.badminton-center.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.badminton-center.com/", "https://www.badminton-center.com/", "https://www.badminton-center.com/", "https://www.badminton-center.com/"]}}'::jsonb)
WHERE slug = 'badminton-center-moersenbroich' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**BallaBalla** ist eine Bar an der Derendorfer Straße, in der Gäste **Tischtennis** spielen können. Neben Platten für zwei bis sechs Personen gibt es eine Rundlauf-Suite für bis zu acht Personen. Zum Programm gehören Rundlauf-Partys, Community-Treffen und Disco-Abende.

Gegründet wurde BallaBalla von **Alain Bieber**, zuvor künstlerischer Leiter des NRW-Forums. Der Ort startete 2025 als Pop-up im **Düwell**, einer Galerie-Mall an der Grünstraße nahe der Kö. Die Tischtennisplatten stammen vom schwedischen Hersteller Stiga.$txt$, webseite = COALESCE(webseite, 'https://www.ballaballa.fun/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ballaballa.fun/", "https://www.ballaballa.fun/", "https://www.ballaballa.fun/", "https://www.visitduesseldorf.de/attraktionen/ballaballa-357617eba7", "https://www.visitduesseldorf.de/storys/2025/12/05/balla-balla-mit-alain-bieber/", "https://www.visitduesseldorf.de/storys/2025/12/05/balla-balla-mit-alain-bieber/"]}}'::jsonb)
WHERE slug = 'ballaballa' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das Balletthaus in **Düsseldorf-Bilk** ist das Probenhaus des **Ballett am Rhein** und wurde eigens für die Compagnie gebaut. Seit Beginn der Spielzeit 2015/16 trainiert und probt das Ensemble dort. Entworfen hat den Bau das Architekturbüro von Gerkan, Marg und Partner. Errichtet wurde er als öffentlich-private Partnerschaft der Stadt Düsseldorf mit Hochtief in nur zehn Monaten.

Auf rund 3.000 Quadratmetern Fläche gibt es fünf **Ballettsäle**, dazu Garderoben, Büros, Aufenthaltsräume und einen Bereich für Reha und Therapie. Studio 1 bietet 112 Plätze und lässt sich mit Verdunklung und Theaterlicht in eine **Blackbox-Bühne** verwandeln. Das Haus liegt nahe dem historischen Rheinbahn-Depot „Am Steinberg“. Die nächsten Haltestellen sind „Merowingerstraße“ (Busse 835 und 836) und „Am Steinberg“ (Straßenbahnen 701 und 706).$txt$, webseite = COALESCE(webseite, 'https://www.operamrhein.de/en/your-visit/balletthaus/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/", "https://www.operamrhein.de/en/your-visit/balletthaus/"]}}'::jsonb)
WHERE slug = 'balletthaus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Bambi Filmstudio** an der Klosterstraße ist ein Kino in der Düsseldorfer Innenstadt und gehört zusammen mit Atelier, Cinema und Metropol zu den Düsseldorfer Filmkunstkinos. Eröffnet wurde es im November 1963 von einem Filmverleiher. Nach einer Phase als Erstaufführungskino wird es seit 1965 als **Programmkino** betrieben und zählt damit zu den ältesten Häusern dieser Art in der Stadt.

Der **große Saal** mit 133 Plätzen ist seit der Eröffnung weitgehend unverändert, seine Decke mit rundem Sternenhimmel soll an ein Zirkuszelt erinnern. Ein zweiter, kleinerer Saal hat 66 Plätze, beide Säle sind mit digitaler Projektion und 5.1-Ton ausgestattet. Im Foyer gibt es ein **Kino-Café**, im Sommer wird auch das Außenfoyer genutzt.

Zum Programm gehören Filmkunst-Erstaufführungen, Kinderkino, Anime-Reihen und Sneak Previews. Die nächste Haltestelle ist **Klosterstraße** (Straßenbahn 707), etwa eine Gehminute entfernt.$txt$, webseite = COALESCE(webseite, 'https://filmkunstkinos.de/kinos/bambi/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://filmkunstkinos.de/kinos/bambi/", "https://www.visitduesseldorf.de/attraktionen/bambi-f9bd17d329", "https://filmkunstkinos.de/kinos/bambi/", "https://filmkunstkinos.de/kinos/bambi/", "https://filmkunstkinos.de/kinos/bambi/", "https://filmkunstkinos.de/kinos/bambi/", "https://filmkunstkinos.de/kinos/bambi/", "https://filmkunstkinos.de/kinos/bambi/"]}}'::jsonb)
WHERE slug = 'bambi' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**BASH ROOMS** an der Theodorstraße in Düsseldorf-Rath bietet eine live moderierte **Spielshow für Gruppen**, die etwa zweieinhalb Stunden dauert. Die Teilnehmenden treten in Teams in Spielen aus den Bereichen Wissen, Taktik, Geschick und Sport gegeneinander an, etwa beim Leitergolf, Speed-Stacking oder Domino. Der Standort hat drei Räume für jeweils bis zu 25 Personen, sodass bis zu 75 Gäste parallel spielen können.

Düsseldorf war der erste Standort des Anbieters und öffnete im Februar 2020, inzwischen gibt es Ableger in neun Städten. Gebucht wird die Show unter anderem für **Firmenevents**, Geburtstage und Junggesellenabschiede. Direkt vor dem Gebäude liegt die Haltestelle Wahlerstraße/JVA der Straßenbahnlinie 701, nebenan der **PSD Bank Dome**.$txt$, webseite = COALESCE(webseite, 'https://www.bash-rooms.de/duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.bash-rooms.de/duesseldorf", "https://www.bash-rooms.de/duesseldorf", "https://www.bash-rooms.de/duesseldorf", "https://www.bash-rooms.de/duesseldorf", "https://www.bash-rooms.de/duesseldorf", "https://www.bash-rooms.de/duesseldorf"]}}'::jsonb)
WHERE slug = 'bash-rooms-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das BBK Kunstforum ist der **Ausstellungs- und Veranstaltungsraum** des BBK Düsseldorf, der Berufsvertretung bildender Künstlerinnen und Künstler in der Stadt. Der Verband ist eine regionale Gliederung des Bundesverbands Bildender Künstlerinnen und Künstler und setzt sich für die **kulturpolitischen und sozialen Interessen** von Kunstschaffenden ein. Gezeigt werden Arbeiten von Mitgliedern, Gästen und befreundeten Kulturvereinen. Daneben finden Workshops, Vorträge sowie Musik- und Literaturprojekte statt.$txt$, webseite = COALESCE(webseite, 'https://www.bbk-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.bbk-duesseldorf.de/", "https://www.bbk-duesseldorf.de/", "https://www.bbk-duesseldorf.de/", "https://www.bbk-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'bbk-kunstforum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Beerpongbar Düsseldorf** an der Bolkerstraße liegt mitten in der **Altstadt**. Sie versteht sich als Erlebnisbar, in der neben **Beer Pong** auch Karaoke, Darts und weitere Spiele angeboten werden. Zum Haus gehören ein Private Room, ein Neon-Karaokeraum und mehrere Séparées, darunter eines im Stil „Old Düsseldorf“. Gebucht wird die Bar unter anderem für Firmenfeiern, Junggesellenabschiede, Geburtstage und Teamevents, außerdem finden dort Beerpong-Turniere statt.$txt$, webseite = COALESCE(webseite, 'https://beerpongbar-duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://beerpongbar-duesseldorf.de/", "https://beerpongbar-duesseldorf.de/", "https://beerpongbar-duesseldorf.de/", "https://beerpongbar-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'beerpongbar-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Berger Kirche** ist eine evangelische Kirche aus dem 17. Jahrhundert in der Düsseldorfer Altstadt. Sie war die erste Kirche, die die lutherische Gemeinde in Düsseldorf errichtete, und wurde nach Baubeginn 1683 im August 1687 eingeweiht. Weil Lutheraner im katholisch geprägten Düsseldorf damals nur geduldet waren, entstand sie als **Hofkirche** in einem Hinterhof, seitlich grenzt sie an die Wallstraße.

Die schlichte **Saalkirche** aus rotem Backstein zeigt späte Formen der deutschen Renaissance, die Ausstattung wurde im Barock überformt. 1943 wurde sie im Krieg weitgehend zerstört und nach dem Wiederaufbau 1966 neu eingeweiht.

Seit 2003 steht die Kirche der **Diakonie Düsseldorf** zur Verfügung. Der Künstler Tobias Rehberger gestaltete den Innenraum neu, unter anderem mit einem Acrylglas-Altar, der elektronisch mit der Johanneskirche und St. Lambertus verbunden ist und bei Geräuschen in diesen Kirchen heller leuchtet. Auf dem Außengelände wurde 2011 ein **Trauerort** für Menschen eingerichtet, die die Gräber ihrer Angehörigen nicht besuchen können.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Berger_Kirche_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'berger-kirche' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Bilker Bunker** an der Aachener Straße in Bilk ist ein früherer ziviler Schutzraum, der heute als gemeinnützige **Kulturinstitution** genutzt wird. Betrieben wird das Haus von der Bilker Bunker gGmbH. Auf den Bunker wurden fünf Kuben mit privaten Wohnungen aufgesetzt.

Erdgeschoss und erstes Obergeschoss dienen als **Ausstellungsräume** für wechselnde zeitgenössische Kunst. Im ersten Untergeschoss liegt die Musikbar **Schleuse Zwei** mit DJ-Abenden, Live-Auftritten und Konzerten. Weitere Etagen nehmen Showrooms, eine Fahrradgarage und Büros auf, im zweiten Untergeschoss gibt es mietbare Multiräume etwa für Bandproben oder Yoga. Vor dem Eingang liegt eine Terrasse mit Außengastronomie.$txt$, webseite = COALESCE(webseite, 'https://bilkerbunker.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/attraktionen/bilker-bunker-5e636cae0b", "https://bilkerbunker.de/", "https://bilkerbunker.de/bilker-bunker", "https://bilkerbunker.de/", "https://bilkerbunker.de/", "https://bilkerbunker.de/", "https://bilkerbunker.de/"]}}'::jsonb)
WHERE slug = 'bilker-bunker' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Bilker Häzz** ist eine Kneipe an der Bilker Allee in Düsseldorf, die 2016 eröffnet wurde. Im Mittelpunkt steht der **Fußball**, übertragen werden unter anderem die großen internationalen Turniere. Außerdem gibt es Veranstaltungen wie **Pub-Quiz** und Kneipenbingo. Die Bar kann auch für private Feiern wie Geburtstage, Firmenevents und Hochzeiten gemietet werden.$txt$, webseite = COALESCE(webseite, 'https://www.bilker-haezz.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/poi/detail/bilker-haezz-977261cd41", "https://www.visitduesseldorf.de/en/poi/detail/bilker-haezz-977261cd41", "https://www.bilker-haezz.de/", "https://www.bilker-haezz.de/"]}}'::jsonb)
WHERE slug = 'bilker-haezz' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das Billardzentrum Düsseldorf ist ein Billard- und Snookercenter im Stadtteil **Heerdt**. Neben **Poolbillard** und Snooker gibt es dort auch Dart und Kicker.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://freizeitinsider.de/lotse/billard/duesseldorf/", "https://freizeitinsider.de/lotse/billard/duesseldorf/"]}}'::jsonb)
WHERE slug = 'billardzentrum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Blumengroßmarkt Düsseldorf** an der Ulmenstraße ist ein Großmarkt für Schnittblumen und Zierpflanzen, betrieben von der Genossenschaft Blumengroßmarkt Düsseldorf eG. Im regulären Marktbetrieb verkauft er ausschließlich an gewerbliche Kunden wie Floristen, Einzelhandel und gärtnerischen Fachhandel, nicht an Privatpersonen. Die Anbieter stammen überwiegend aus der Region und sind größtenteils selbst Erzeuger der Ware.

Zum **Sortiment** gehören Schnittblumen, Beet-, Balkon- und Topfpflanzen, Baumschulware sowie Floristenbedarf. Seit 2024 nutzt der Markt eine neue Verkaufshalle auf dem Gelände an der Ulmenstraße.

Außerhalb des Großhandels finden auf dem Markt auch Veranstaltungen für Publikum statt, etwa **Flohmärkte** wie der Nachtflohmarkt Moonlight Market.$txt$, webseite = COALESCE(webseite, 'https://bgm-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://bgm-duesseldorf.de/", "https://bgm-duesseldorf.de/", "https://bgm-duesseldorf.de/UEBER_UNS.html", "https://bgm-duesseldorf.de/", "https://bgm-duesseldorf.de/", "https://bgm-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'blumengrossmarkt' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Boston-Club Düsseldorf** ist ein Tanzsportverein, der 1912 aus einem Tanzkreis im Breidenbacher Hof hervorging. Nach dem Zweiten Weltkrieg nahm er den Tanzbetrieb im Oktober 1948 wieder auf. Angeboten werden unter anderem **Standard** und Latein, Formationstanz, Jazz und Modern Dance, Hip-Hop, Breaking sowie Gesellschafts- und Kindertanz.

Die 2002 gegründete **Standardformation** tanzte zeitweise in der 1. Bundesliga. Der Verein hatte 2021 rund 540 Mitglieder und gehört dem Deutschen Tanzsportverband an. Sein Sitz ist an der Vennhauser Allee.$txt$, webseite = COALESCE(webseite, 'https://www.boston-club.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Boston-Club_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'boston-club' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**BrauArt** ist ein Fachgeschäft für Bier an der Emmastraße in Düsseldorf-**Oberbilk**, das zugleich als Treffpunkt und Veranstaltungsort dient. Das Sortiment umfasst nach eigenen Angaben mehr als 400 Biere, Cider und Spezialitäten aus Deutschland und dem Ausland. Dazu gehören etwa britische Ales, Porter und Stouts, belgische Trappistenbiere und amerikanische IPAs. Bereits seit 2006 importiert das Unternehmen handwerklich gebraute Biere aus Großbritannien.

Im Laden finden **Bierverkostungen** statt, auch für Firmen und Teams. Außerdem stehen Pub-Quiz-Abende, Livemusik, Comedy und Spieleabende auf dem Programm.$txt$, webseite = COALESCE(webseite, 'https://brauart-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://brauart-duesseldorf.de/ueber-brauart-duesseldorf", "https://brauart-duesseldorf.de/", "https://brauart-duesseldorf.de/ueber-brauart-duesseldorf", "https://brauart-duesseldorf.de/ueber-brauart-duesseldorf", "https://brauart-duesseldorf.de/", "https://brauart-duesseldorf.de/ueber-brauart-duesseldorf"]}}'::jsonb)
WHERE slug = 'brauart' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Bürgerhaus Bilk** an der Bachstraße ist ein Treffpunkt für Kultur und Nachbarschaft im Stadtteilzentrum Bilk. Es bietet Veranstaltungen für alle Altersgruppen, **interkulturellen Austausch** für Menschen mit Migrationsgeschichte sowie Projekte, die verschiedene Generationen im Alltag unterstützen. Für größere Termine steht der **Bürgersaal** zur Verfügung, in dem etwa städtische Bürgerwerkstätten stattfinden. Unter derselben Adresse befindet sich auch die Stadtteilbibliothek Bilk.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/attractions/community-centre-in-the-bilk-district-dd0b48b3da", "https://www.visitduesseldorf.de/en/attractions/community-centre-in-the-bilk-district-dd0b48b3da", "https://www.duesseldorf.de/medienportal/pressedienst-einzelansicht/pld/buergerwerkstatt-zur-zukuenftigen-nutzung-des-grundstuecks-ecke-elisabethstrassebachstrasse", "https://www.duesseldorf.de/medienportal/pressedienst-einzelansicht/pld/buergerwerkstatt-zur-zukuenftigen-nutzung-des-grundstuecks-ecke-elisabethstrassebachstrasse"]}}'::jsonb)
WHERE slug = 'buergerhaus-bilk' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Bürgerhaus Reisholz** ist ein Stadtteilzentrum an der Kappeler Straße im Düsseldorfer Industriestadtteil Reisholz. Seit 1982 ist es in einem ehemaligen **Kinosaal** aus der Zeit um die Jahrhundertwende untergebracht, der baulich erweitert wurde. Träger ist die Abteilung Jugendförderung im Amt für Jugend und Soziales der Stadt Düsseldorf.

Das Programm umfasst Kultur und Begegnung, Bildung und Soziales sowie Freizeitangebote, mit Schwerpunkten auf **Kinderkultur** und Abendveranstaltungen mit Musik und Tanz. Einmal im Monat gastiert ein **Kindertheater** mit Stücken für Kinder. Die Räume des Hauses können auch gemietet werden.

Die S-Bahn-Station **Reisholz** liegt etwa fünf Gehminuten entfernt.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/buergerhaeuser/reisholz'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/buergerhaeuser/reisholz", "https://www.duesseldorf.de/buergerhaeuser/reisholz", "https://www.fruehehilfen-online.nrw.de/fhiangebot/exportpdf/id/51815", "https://www.duesseldorf.de/buergerhaeuser/reisholz", "https://www.fruehehilfen-online.nrw.de/fhiangebot/exportpdf/id/51815", "https://www.duesseldorf.de/buergerhaeuser/reisholz", "https://www.duesseldorf.de/buergerhaeuser/reisholz"]}}'::jsonb)
WHERE slug = 'buergerhaus-reisholz' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Bürgerhaus Salzmannbau** ist ein städtisches Bürgerhaus im Düsseldorfer Stadtteil **Bilk**. Es liegt im Salzmannbau, dem denkmalgeschützten früheren Hauptgebäude der Jagenberg-Fabrik, das der Architekt Heinrich Salzmann plante und das von 1904 bis 1906 entstand. 1984 wurde das Gebäude unter Denkmalschutz gestellt und von der Stadt erworben, nach einer Kernsanierung wurde es im September 1994 neu eröffnet.

Neben dem Bürgerhaus sind im Salzmannbau Vereine, Initiativen, **Künstlerateliers** und Wohnungen untergebracht. Das Bürgerhaus fördert vor allem Kinder und Familien sowie die interkulturelle Begegnung, besonders im Wohnquartier auf dem Jagenberggelände. Zum Programm gehören Veranstaltungen, Tanzevents sowie Kurse und Workshops, außerdem können Räume gemietet werden.

Die nächsten Haltestellen sind **Am Steinberg** und Moorenstraße, die von Straßenbahnen und Bussen angefahren werden.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/buergerhaeuser/salzmannbau'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/buergerhaeuser/salzmannbau", "https://de.wikipedia.org/wiki/Salzmannbau", "https://de.wikipedia.org/wiki/Salzmannbau", "https://de.wikipedia.org/wiki/Salzmannbau", "https://www.duesseldorf.de/buergerhaeuser/salzmannbau", "https://www.duesseldorf.de/buergerhaeuser/salzmannbau", "https://www.duesseldorf.de/buergerhaeuser/salzmannbau"]}}'::jsonb)
WHERE slug = 'buergerhaus-salzmannbau' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Cageball Düsseldorf** ist eine Sporthalle für Cageball an der Ulenbergstraße. Gespielt wird auf **Kunstrasenfeldern**, die von einer etwa einen Meter hohen Bande und einem rund vier Meter hohen Netz umschlossen sind. Die Halle hat **sieben Courts**: vier kleinere mit rund 350 Quadratmetern für acht bis zehn Spieler und drei größere mit 450 Quadratmetern für zehn bis zwölf Spieler.

Auf den kleineren Feldern lassen sich die Tore verkleinern, sodass auch ohne Torwart gespielt werden kann. Zur Anlage gehören eine **Sportsbar** mit etwa 50 Plätzen und ein Tischtennisangebot, außerdem gibt es Angebote für Kindergeburtstage, Bubble Ball und Fußballschulen. Einen zweiten Standort betreibt das Unternehmen in **Meerbusch-Lank**.$txt$, webseite = COALESCE(webseite, 'https://www.cageball-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.cageball-duesseldorf.de/", "https://www.cageball-duesseldorf.de/", "https://www.cageball-duesseldorf.de/", "https://www.cageball-duesseldorf.de/", "https://www.cageball-duesseldorf.de/", "https://www.cageball-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'cageball-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Capitol Theater** an der Erkrather Straße ist eine Bühne für Musicals, Shows, Comedy und Veranstaltungen. Es wurde Anfang der 1990er-Jahre in einem über 100 Jahre alten ehemaligen **Straßenbahndepot** der Rheinbahn eingerichtet. Nach Angaben des Hauses eröffnete es **1996** mit dem Musical „Grease“.

Bei einer Renovierung im Jahr 1999 blieben die **Backsteinarchitektur** und der Charakter des Depots erhalten. Der große **Theatersaal** hat 1.250 Plätze und eine 25 mal 13 Meter große Bühne. Als zweiter Saal fasst der **Club** bis zu 475 Gäste in Theaterbestuhlung. Hinzu kommt ein über 1.000 Quadratmeter großes Foyer mit Wintergarten.

Im Jahr 2011 zog der **Quatsch Comedy Club** dauerhaft ins Capitol ein. Betreiberin des Hauses ist die **ATG Entertainment GmbH**.$txt$, webseite = COALESCE(webseite, 'https://www.capitol-theater.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.capitol-theater.de/", "https://en.wikipedia.org/wiki/Capitol_Theater_(Düsseldorf)", "https://www.capitol-theater.de/", "https://de.wikipedia.org/wiki/Capitol_Theater_(Düsseldorf)", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/", "https://www.capitol-theater.de/"]}}'::jsonb)
WHERE slug = 'capitol-theater' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das CASTELLO ist eine **Mehrzweckhalle** an der Karl-Hohmann-Straße im Düsseldorfer Stadtteil **Reisholz**. Der Bau begann 2004 nach Plänen des Büros Guida & Mischok, ursprünglich war an dieser Stelle nur eine Turnhalle für ein benachbartes Gymnasium vorgesehen. Bis 2011 hieß die Halle Burg-Wächter Castello, seit August 2010 gehört sie der Stadt Düsseldorf.

Bei Konzerten fasst die Halle bis zu 4.850 Menschen, bei Basketballspielen 3.700. Der rund 1.600 Quadratmeter große **Innenraum** mit Vorhangsystem und Sportschwingboden wird für Sport-Events, TV-Produktionen und gesellschaftliche Veranstaltungen genutzt. Früher trugen hier unter anderem die Handballer der HSG Düsseldorf und die Basketballer der Giants ihre Heimspiele aus. Der **Bahnhof Düsseldorf-Reisholz** liegt in unmittelbarer Nähe.$txt$, webseite = COALESCE(webseite, 'https://www.castello-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf", "https://www.castello-duesseldorf.de/veranstalter/raumuebersicht", "https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Castello_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'castello-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Cinema** in der Schneider-Wibbel-Gasse in der Düsseldorfer Altstadt gehört zu den Düsseldorfer Filmkunstkinos. Eröffnet wurde das Haus 1957 als **Bali-Kino**, ein Non-Stop-Kino mit täglich wechselndem Programm. Nach der Schließung des früheren Cinemas an der Kasernenstraße übernahm Heinz Holzapfel das Bali und führte es als „Neues Cinema“ weiter.

Das Kino hat einen Saal mit 192 Plätzen und ein **Kinocafé** für rund 30 Personen. Das Foyer wurde im Sommer 2018 renoviert. Gezeigt werden vor allem **Erstaufführungen** aus dem Bereich Filmkunst, oft mit Premierenfeiern, dazu Aufzeichnungen aus Theater, Ballett und Kunstausstellungen sowie Filme in Originalfassung mit Untertiteln. Die nächste Haltestelle ist Heinrich-Heine-Allee, etwa fünf Gehminuten entfernt.$txt$, webseite = COALESCE(webseite, 'https://filmkunstkinos.de/kinos/cinema/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/", "https://filmkunstkinos.de/kinos/cinema/"]}}'::jsonb)
WHERE slug = 'cinema' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **CineStar Düsseldorf** ist ein Multiplex-Kino an der Hansaallee beim Forum Oberkassel. Es öffnete 1998 als Ufa-Palast Forum Oberkassel und wird seit April 2003 von der Kette CineStar betrieben.

Das Haus ist ein **Glasbau** mit neun Sälen. Auf dem Programm stehen **Blockbuster** ebenso wie Arthouse-Filme. Die nächste Haltestelle ist Löricker Straße, angefahren von den Stadtbahnlinien U74 und U76 sowie vom Bus 828.$txt$, webseite = COALESCE(webseite, 'https://www.cinestar.de/kino-duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.cinestar.de/kino-duesseldorf/info/anfahrt", "https://cinematreasures.org/theaters/62080", "https://www.visitduesseldorf.de/en/attractions/cinestar-duesseldorf-5b186ff662", "https://www.visitduesseldorf.de/en/attractions/cinestar-duesseldorf-5b186ff662", "https://www.cinestar.de/kino-duesseldorf/info/anfahrt"]}}'::jsonb)
WHERE slug = 'cinestar' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Classic Remise Düsseldorf ist ein Zentrum für **Oldtimer** in einem denkmalgeschützten **Ringlokschuppen** an der Harffstraße. Der Lokschuppen wurde 1929 bis 1931 errichtet, sein halbkreisförmiger Grundriss misst fast 150 Meter im Durchmesser. Eröffnet wurde die Anlage im September 2006, zunächst unter dem Namen Meilenwerk.

Auf mehr als 19.000 Quadratmetern arbeiten Händler, Restauratoren und **Werkstätten** sowie Geschäfte für Zubehör, Automobilliteratur und Bekleidung. In gläsernen Einstellboxen sind zudem Oldtimer ausgestellt. Gastronomie und **Veranstaltungsflächen** ergänzen das Angebot, genutzt etwa für Präsentationen, Tagungen und Oldtimer-Treffen.$txt$, webseite = COALESCE(webseite, 'https://remise.de/duesseldorf/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://remise.de/duesseldorf/", "https://de.wikipedia.org/wiki/Classic_Remise", "https://de.wikipedia.org/wiki/Classic_Remise", "https://de.wikipedia.org/wiki/Classic_Remise", "https://remise.de/duesseldorf/", "https://de.wikipedia.org/wiki/Classic_Remise"]}}'::jsonb)
WHERE slug = 'classic-remise-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Coffee Brew** ist ein Café mit Bar am Stresemannplatz in der Nähe des Düsseldorfer Hauptbahnhofs. Auf der Karte stehen ganztägiges **Frühstück**, Mittagsgerichte, Specialty Coffee, Tees und frische Säfte. Am Wochenende wird das Café abends zur Bar mit Cocktails und lokalen Bieren. Am selben Standort betreibt The Code Agency **Escape Rooms** und eine Axtwurf-Anlage, die Lounge des Cafés dient auch als Arbeitsplatz.$txt$, webseite = COALESCE(webseite, 'https://www.thecodeagency.de/en/duesseldorf/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://lifeinduesseldorf.com/coffeebrew-dusseldorf-krefeld/", "https://lifeinduesseldorf.com/coffeebrew-dusseldorf-krefeld/", "https://lifeinduesseldorf.com/coffeebrew-dusseldorf-krefeld/", "https://www.thecodeagency.de/en/duesseldorf/"]}}'::jsonb)
WHERE slug = 'coffee-brew-duesseldorf-cafe-bar' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der Comedy Club Düsseldorf an der Oststraße ist eine Bühne für **Live-Comedy** mit eigener Bar. An allen Abenden der Woche finden dort professionelle, überwiegend deutschsprachige Shows statt. Zum Programm gehören **Stand-up-Shows**, Open-Mic-Abende und Soloprogramme.$txt$, webseite = COALESCE(webseite, 'https://comedyclubduesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.comedyinyoureye.com/comedy-in-your-eye-dusseldorf-english-speaking-stand-up-comedy-club", "https://www.comedyinyoureye.com/comedy-in-your-eye-dusseldorf-english-speaking-stand-up-comedy-club", "https://comedyclubduesseldorf.de/"]}}'::jsonb)
WHERE slug = 'comedy-club-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Comedy für Freunde Club Düsseldorf** ist die Düsseldorfer Spielstätte der Stand-up-Reihe Comedy für Freunde an der Ackerstraße 109. Die Shows finden in der **Lupin Gin Bar** statt. Bei der **Profi-Testbühne** probieren sechs bis acht Profi-Comedians und Newcomer in rund 90 Minuten neue Geschichten und Witze aus. Comedy für Freunde veranstaltet Shows auch in weiteren Städten, darunter München, Köln, Frankfurt und Innsbruck.$txt$, webseite = COALESCE(webseite, 'https://comedy-fuer-freunde.com/duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://comedy-fuer-freunde.com/duesseldorf", "https://comedy-fuer-freunde.com/duesseldorf", "https://comedy-fuer-freunde.com/duesseldorf", "https://comedy-fuer-freunde.com/duesseldorf"]}}'::jsonb)
WHERE slug = 'comedy-fuer-freunde-club-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Cuvée** ist eine Weinbar mit Restaurant an der Hermannstraße in Düsseldorf-Flingern. Es hat im März 2023 eröffnet und tritt unter dem Zusatz „by **Naturburschen** Flingern“ auf. Die Weinkarte umfasst rund 100 Weine, überwiegend von kleinen Weingütern aus Deutschland und Europa. Im Lokal gibt es mehr als 60 Plätze.

Die Küche bringt **portugiesisch-brasilianische** Einflüsse auf den Teller. Gemeinsam mit den Naturburschen hat das Cuvée eigene Weine herausgebracht, darunter den „No Cuvée“. Zum Programm gehören regelmäßige **Bingo- und Quizabende**, und im Sommer finden im Innenhof kleine Konzerte statt.$txt$, webseite = COALESCE(webseite, 'https://cuvee-flingern.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://cuvee-flingern.de/kontakt/", "https://cuvee-flingern.de/", "https://www.visitduesseldorf.de/storys/2025/11/19/6-spots-genuss-weinbar-in-duesseldorf/", "https://cuvee-flingern.de/", "https://www.visitduesseldorf.de/storys/2025/11/19/6-spots-genuss-weinbar-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/11/19/6-spots-genuss-weinbar-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2025/11/19/6-spots-genuss-weinbar-in-duesseldorf/"]}}'::jsonb)
WHERE slug = 'cuvee' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Rheinische Landestheater** ist ein Schauspielhaus in der Neusser Innenstadt an der Oberstraße. Als Landesbühne spielt es nicht nur in Neuss, sondern gastiert auch in Städten und Gemeinden ohne eigenes Ensemble, vor allem in Nordrhein-Westfalen. Einen Schwerpunkt bilden **Kinder- und Jugendtheater** sowie Theaterpädagogik.

Gegründet wurde das Theater im August 1925 in Neuss als **Rheinisches Städtebundtheater**, 1937 erhielt es seinen heutigen Namen. 1981 schloss es sich mit dem Theater am Niederrhein in Kleve zusammen.

Seit Dezember 2000 spielt das Ensemble im umgebauten früheren **Horten-Kaufhaus** an der Oberstraße, das der Architekt Oliver Ingenhoven gestaltet hat. Das Schauspielhaus im ersten Obergeschoss hat einen steil ansteigenden Zuschauerraum mit 443 Plätzen. Im Untergeschoss liegt eine **Studiobühne** für kleinere und zeitgenössische Stücke sowie für Kinder- und Jugendtheater. Vom Foyer aus reicht der Blick über die Stadt bis zur Kirche St. Quirin.$txt$, webseite = COALESCE(webseite, 'https://www.rheinisches-landestheater.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss", "https://de.wikipedia.org/wiki/Rheinisches_Landestheater_Neuss"]}}'::jsonb)
WHERE slug = 'das-rheinische-landestheater' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Hinter **Dein Ursprunghaus** an der Oberkasseler Straße in Düsseldorf steht eine gemeinnützige GmbH. Angeboten werden ganzheitliche **Psychotherapie**, Paartherapie, Somatic Soul Experiencing, traumasensibles Yoga, Meditation und Elementelehre. Dazu kommen Massagen und Energiearbeit, auch Massagen für Pferde. Bei **Veranstaltungen** gibt es außerdem Gruppenangebote, darunter kostenlose wie eine Beratung für Angehörige von Menschen mit Demenz.$txt$, webseite = COALESCE(webseite, 'https://dein-ursprunghaus.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://dein-ursprunghaus.de/impressum/", "https://dein-ursprunghaus.de/", "https://dein-ursprunghaus.de/", "https://dein-ursprunghaus.de/"]}}'::jsonb)
WHERE slug = 'dein-ursprunghaus-dein-ort-fuer-bewusstwerdung' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Central** an der Worringer Straße 140 ist eine Spielstätte des Düsseldorfer Schauspielhauses in der Nähe des Hauptbahnhofs. Das Schauspielhaus nutzt die Räume im Gebäude der früheren **Paketpost** seit Juni 2008. Außer Bühnen sind dort Werkstätten wie Schreinerei, Schlosserei und Malersaal sowie Kulissenlager und Kostümfundus untergebracht.

Im Central spielen das **Junge Schauspiel** und das **Stadt:Kollektiv**, außerdem liegt hier das Proben- und Produktionszentrum des Hauses. In den Spielzeiten 2016/17 bis 2018/19, während der Sanierung des Schauspielhauses am Gustaf-Gründgens-Platz, zeigte das Ensemble sein Repertoire im Central. Gespielt wird in den Räumen Central 1 und Central 2 sowie auf der **Central-Brücke**, wo sich auch die Theaterbar befindet.$txt$, webseite = COALESCE(webseite, 'https://www.dhaus.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/"]}}'::jsonb)
WHERE slug = 'dhaus-central' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **DJK TuSA 06 Düsseldorf** ist ein Sportverein im Stadtteil **Flehe**, der seit 1906 besteht. Der Verein zählt rund 2.300 Mitglieder, fast die Hälfte davon Kinder und Jugendliche.

Das Angebot reicht von **Fußball** sowie Frauen- und Mädchenfußball über Basketball, 3x3-Basketball, Leichtathletik, Tischtennis und Volleyball bis zu Fitness und Inklusionssport. Auf der **Sportanlage an der Fleher Straße** gibt es einen Naturrasenplatz mit Laufbahn, zwei Kunstrasenplätze sowie Flächen für Beachvolleyball, Basketball und Outdoor-Fitness. Zum Gelände gehört außerdem ein Vereinsheim mit Gastronomie. Seit 2018 unterhält der Verein ein Leistungszentrum für Frauen- und Mädchenfußball.$txt$, webseite = COALESCE(webseite, 'https://www.tusa06.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.tusa06.de/", "https://www.tusa06.de/", "https://www.tusa06.de/", "https://www.tusa06.de/", "https://www.tusa06.de/", "https://www.tusa06.de/"]}}'::jsonb)
WHERE slug = 'djk-tusa-06-e-v' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Drachental ist ein Laden für **Brett- und Tabletopspiele**, an den sich großzügige Spielräume anschließen. Die Spielfläche ist groß genug für Turniere und andere Spielveranstaltungen, außerdem ist der Laden seit jeher Treffpunkt des Vereins **Games 'n Dice Düsseldorf**.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://chaosbunker.de/en/2024/07/24/a-visit-to-games-n-dice-dusseldorf-e-v", "https://chaosbunker.de/en/2024/07/24/a-visit-to-games-n-dice-dusseldorf-e-v"]}}'::jsonb)
WHERE slug = 'drachental-games' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das Düsseldorfer Marionetten-Theater ist eine **Marionettenbühne** im Palais Wittgenstein an der Bilker Straße. Seine Wurzeln reichen bis 1925 zurück, als die Brüder Emanuel und Franz Zangerle in Köln das „Theater Rheinischer Marionetten“ gründeten. Nach Stationen in einem Torturm der Kölner Hohenzollernbrücke und nach dem Zweiten Weltkrieg in Steinau kam die Bühne 1956 nach Düsseldorf, zunächst an die Wallstraße. Seit 1966 spielt sie im **Palais Wittgenstein**. Unter dem heutigen Namen wurde sie im Januar 1986 neu eröffnet.

Der Theatersaal hat 90 Plätze. Das Repertoire umfasst Märchen, Dramen, Fabeln sowie klassisches und modernes **Musiktheater** und richtet sich an Erwachsene und Kinder ab acht Jahren. Zu den Inszenierungen gehören Mozarts „Zauberflöte“ und „Die Entführung aus dem Serail“, Michael Endes „Wunschpunsch“ erlebte mehr als 1.000 Vorstellungen.$txt$, webseite = COALESCE(webseite, 'https://www.marionettentheater-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Marionetten-Theater"]}}'::jsonb)
WHERE slug = 'duesseldorfer-marionetten-theater' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Düsseldorfer Schauspielhaus**, kurz D’haus, ist ein Ensembletheater mit Hauptspielstätte am **Gustaf-Gründgens-Platz**. Louise Dumont und Gustav Lindemann eröffneten **1905** an der Karl-Theodor-Straße das Schauspielhaus Düsseldorf als Privattheater. Dem Haus war eine Theaterakademie angeschlossen, zu deren Schülern Gustaf Gründgens gehörte. Von 1951 bis 1970 spielte das Schauspielhaus an der Jahnstraße.

Das heutige Gebäude entwarf der Düsseldorfer Architekt **Bernhard Pfau**, es entstand von 1965 bis 1969 und wurde im Januar 1970 mit Büchners „Dantons Tod“ eröffnet. Die skulpturale Großform steht in deutlichem Kontrast zum benachbarten **Dreischeibenhaus**. In den Spielzeiten 2016/17 bis 2018/19 wurde das Haus umfassend saniert.

Im Gebäude liegen das Große Haus mit rund 730 Plätzen, das Kleine Haus mit bis zu 300 Plätzen und das **Unterhaus**, eine experimentelle Spielstätte im Keller. Junges Schauspiel und Stadt:Kollektiv spielen im **Central** an der Worringer Straße am Hauptbahnhof, das zugleich Proben- und Produktionszentrum ist. Nahe Haltestellen sind Schadowstraße, Heinrich-Heine-Allee und Jacobistraße.$txt$, webseite = COALESCE(webseite, 'https://www.dhaus.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://de.wikipedia.org/wiki/D%C3%BCsseldorfer_Schauspielhaus", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/das-dhaus/ueber-das-haus/", "https://www.dhaus.de/besuch/anreise/"]}}'::jsonb)
WHERE slug = 'duesseldorfer-schauspielhaus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Eigenlob ist ein **Keramik-Malstudio** in Düsseldorf, in dem Gäste Rohlinge aus Keramik selbst bemalen. Die bemalten Stücke werden anschließend im Studio **glasiert und gebrannt** und später abgeholt. Neben dem freien Malen gibt es feste Formate wie Mal-Abende, Junggesellinnenabschiede und **Kindergeburtstage**.$txt$, webseite = COALESCE(webseite, 'https://www.eigenlob-keramik.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.eigenlob-keramik.de/", "https://www.eigenlob-keramik.de/", "https://www.eigenlob-keramik.de/"]}}'::jsonb)
WHERE slug = 'eigenlob-keramik-malstudio' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Einstein Boulderhalle** ist eine Kletterhalle zum Bouldern an der Lierenfelder Straße im Stadtteil Lierenfeld. Betrieben wird sie von einer Gesellschaft der Einstein-Gruppe. Der Boulderbereich im offenen **Industrie-Loft-Stil** umfasst 1.725 Quadratmeter Kletterfläche und richtet sich an Einsteiger ebenso wie an sehr erfahrene Kletterer.

Zum Haus gehören außerdem ein rund 1.000 Quadratmeter großer **CrossFit**-Bereich, ein Cycling-Raum, ein Yogastudio und eine Sauna im Zwischengeschoss. Für **Kinder** ab drei Jahren gibt es ein eigenes Kursprogramm, dazu Kindergeburtstage, Ferienprogramme und Angebote für Schulklassen. Die nächsten Haltestellen sind Lierenfeld Betriebshof (Straßenbahn 709) und Ronsdorfer Straße (Bus 725).$txt$, webseite = COALESCE(webseite, 'https://einstein-boulder-duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://einstein-boulder-duesseldorf.de/infos/anfahrt", "https://einstein-boulder-duesseldorf.de/", "https://einstein-boulder-duesseldorf.de/infos/ubersicht-unseres-angebotes", "https://einstein-boulder-duesseldorf.de/infos/ubersicht-unseres-angebotes", "https://einstein-boulder-duesseldorf.de/", "https://einstein-boulder-duesseldorf.de/infos/anfahrt"]}}'::jsonb)
WHERE slug = 'einstein-boulderhalle' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das EKŌ-Haus der Japanischen Kultur liegt am Brüggener Weg im Düsseldorfer Stadtteil **Niederkassel**. Ziel des Hauses ist es, die buddhistische Lehre und die darauf beruhende **japanische Kultur** zu vermitteln und den interreligiösen Dialog zu fördern. Es geht auf Numata Yehan zurück, den Gründer des japanischen Unternehmens Mitutoyo, und ist eine Auslandsniederlassung der in Tokio gegründeten Bukkyō Dendō Kyōkai. Der Grundstein wurde 1988 gelegt, der Tempel 1992 geweiht und das Haus 1993 eröffnet.

Zum Gelände gehören ein **buddhistischer Tempel**, ein traditionelles **Japanisches Haus**, Gartenanlagen und eine Bibliothek mit Schwerpunkt Buddhismusforschung. Der Tempelgarten ist als Trockengarten angelegt, in dem Wasserfall, Flusslauf und Teich durch Steine dargestellt sind. Das Angebot umfasst Kurse etwa in Kalligraphie, Koto-Musik und japanischer Sprache sowie Teezeremonien, Führungen, Ausstellungen und Vorträge.$txt$, webseite = COALESCE(webseite, 'https://eko-haus.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Ek%C5%8D-ji", "https://eko-haus.de/ueber-uns/ziel-geschichte/", "https://eko-haus.de/ueber-uns/ziel-geschichte/", "https://eko-haus.de/ueber-uns/ziel-geschichte/", "https://eko-haus.de/ueber-uns/gebaeude-gaerten/", "https://eko-haus.de/ueber-uns/gebaeude-gaerten/", "https://eko-haus.de/"]}}'::jsonb)
WHERE slug = 'eko-haus-der-japanischen-kultur' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Em Pöötzke** in der Mertensgasse in der Düsseldorfer Altstadt ist eine Kneipe mit **Livemusik**, die als Jazzkneipe bekannt ist. Das Repertoire reicht von Dixieland und Blues über Soul, Funk und lateinamerikanische Musik bis zu **Modern Jazz**, traditionell sammeln die Musiker bei den Gästen eine Spende ein.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://dusseldorf.amazingcapitals.com/em-pootzke", "https://dusseldorf.amazingcapitals.com/em-pootzke"]}}'::jsonb)
WHERE slug = 'em-poeoetzke' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Event-Theater Schwanenhöfe** ist eine Eventlocation in Flingern für Veranstaltungen mit 50 bis 180 Gästen. Es liegt auf dem früheren **Henkel-Gelände**, wo ein Stadtquartier mit Industriearchitektur entsteht. Genutzt wird es für Firmenveranstaltungen, Tagungen, Hochzeiten und Feiern sowie für Film- und Fernsehproduktionen. Daneben finden auch öffentliche Veranstaltungen statt.$txt$, webseite = COALESCE(webseite, 'https://www.event-theater-schwanenhoefe.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.event-theater-schwanenhoefe.de/", "https://www.event-theater-schwanenhoefe.de/", "https://www.event-theater-schwanenhoefe.de/", "https://www.event-theater-schwanenhoefe.de/"]}}'::jsonb)
WHERE slug = 'event-theater-schwanenhoefe' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**everybodyoga** ist ein Yogastudio in einem ruhigen Hinterhof an der Merowingerstraße in Düsseldorf-**Bilk**. Auf dem Kursplan stehen unter anderem Vinyasa, Yin und **Kundalini Yoga**, dazu Kurse für Schwangere und nach der Geburt, Kinderyoga und Yoga für Eltern und Kind. Außerdem gibt es Einzelstunden und Angebote für Firmen. Der **S-Bahnhof Bilk** ist etwa zwei Gehminuten entfernt.$txt$, webseite = COALESCE(webseite, 'https://everybodyoga.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://everybodyoga.de/kontakt-anfahrt/", "https://everybodyoga.de/kontakt-anfahrt/", "https://everybodyoga.de/kontakt-anfahrt/", "https://everybodyoga.de/kontakt-anfahrt/"]}}'::jsonb)
WHERE slug = 'everybodyoga' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Fatty's Irish Pub** liegt an der Hunsrückenstraße mitten in der Düsseldorfer **Altstadt**. Die Kneipe wurde 1978 gegründet und war ursprünglich ein deutsches Lokal.

Bekannt ist der Pub für **Sportübertragungen** von Fußball, Eishockey, Rugby und American Football. Nach Angaben des Inhabers gehörte er zu den ersten Kneipen in Düsseldorf, die American Football zeigten. Zum Publikum zählen neben Fans von Fortuna Düsseldorf und der DEG viele britische Fußballfans.$txt$, webseite = COALESCE(webseite, 'https://www.fattys.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/storys/2024/06/11/fattys-irish-pub-duesseldorf/", "https://www.visitduesseldorf.de/storys/2024/06/11/fattys-irish-pub-duesseldorf/", "https://www.visitduesseldorf.de/storys/2024/06/11/fattys-irish-pub-duesseldorf/", "https://www.visitduesseldorf.de/storys/2024/06/11/fattys-irish-pub-duesseldorf/", "https://www.visitduesseldorf.de/storys/2024/06/11/fattys-irish-pub-duesseldorf/"]}}'::jsonb)
WHERE slug = 'fatty-s-irish-pub' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das FFT (Forum Freies Theater) ist ein internationales **Produktionshaus für freie darstellende Künste** in Düsseldorf. Es wurde 1999 gegründet und ging aus den Kammerspielen Düsseldorf und dem Jungen Theater in der Altstadt hervor. Ohne festes Ensemble zeigt das Haus Arbeiten an der Schnittstelle von **Theater, Performance, Tanz**, bildender Kunst und Musik.

Seit 2021 hat das FFT seine Spielstätte im **KAP1** am Hauptbahnhof, zuvor nutzte es das FFT Juta in der Altstadt und die FFT Kammerspiele an der Jahnstraße. Im KAP1 stehen unter anderem zwei Bühnen, ein Foyer mit Blick auf den Bahnhofsvorplatz und eine Bar zur Verfügung. Programme für junges Publikum und die künstlerische Arbeit mit Jugendlichen gehören unter dem Namen **Junges FFT** seit Beginn zum Profil. 2015 wurde das FFT mit dem Theaterpreis des Bundes ausgezeichnet.$txt$, webseite = COALESCE(webseite, 'https://www.fft-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.fft-duesseldorf.de/ueber-uns/", "https://de.wikipedia.org/wiki/Forum_Freies_Theater", "https://de.wikipedia.org/wiki/Forum_Freies_Theater", "https://de.wikipedia.org/wiki/Forum_Freies_Theater", "https://www.fft-duesseldorf.de/ueber-uns/", "https://www.fft-duesseldorf.de/ueber-uns/", "https://de.wikipedia.org/wiki/Forum_Freies_Theater"]}}'::jsonb)
WHERE slug = 'fft-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Filmmuseum Düsseldorf** ist ein städtisches Museum in der **Altstadt** am Alten Hafen. Bereits 1979 gründete die Stadt ein Filminstitut, das Museumsgebäude an der Schulstraße wurde am **21. August 1993** eröffnet. Die Dauerausstellung zeigt auf rund 2.200 Quadratmetern die Geschichte des Films von den Anfängen bis in die Gegenwart.

Zur Sammlung gehören unter anderem rund 500.000 Fotos, mehr als 25.000 Plakate und Nachlässe etwa von **Lotte Reiniger** und Helmut Käutner. Als einziges Museum dieser Art in Nordrhein-Westfalen beherbergt das Haus die **Filmsammlung des Landes**, das Archiv umfasst über 30.000 Filmkopien.

Im Haus liegt das Kino **Black Box** mit 135 Plätzen, das seit 2009 als kommunales Kino betrieben wird. Gezeigt werden Klassiker, Retrospektiven und Neuerscheinungen, viele Vorführungen laufen von analogen Kopien. Im Kino steht außerdem eine **Welte-Kinoorgel** aus dem Jahr 1928.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/filmmuseum'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://www.duesseldorf.de/filmmuseum", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://www.duesseldorf.de/filmmuseum", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf", "https://de.wikipedia.org/wiki/Filmmuseum_Düsseldorf"]}}'::jsonb)
WHERE slug = 'filmmuseum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Filmwerkstatt Düsseldorf ist ein gemeinnütziger, selbstverwalteter Verein von **Filmschaffenden**. Sie wurde 1976 gegründet und 1980 dem damals neu gegründeten Filminstitut der Stadt angegliedert. Seit 1992 ist sie ein eingetragener Verein, dessen Zweck laut Satzung die **Förderung des filmischen Nachwuchses** ist.

Zum Angebot gehören die Begleitung von Filmprojekten, der Verleih von Kamera-, Licht- und Tontechnik sowie die Vermietung von Schnittplätzen und Tonstudios. Mit der **Jungen Filmwerkstatt** gibt es einen außerschulischen Treffpunkt für junge Filmbegeisterte ab 16 Jahren. In ihren Räumen im Hof der Birkenstraße 47 zeigt die Filmwerkstatt außerdem Filme und veranstaltet Konzertabende.$txt$, webseite = COALESCE(webseite, 'https://www.filmwerkstatt-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.filmwerkstatt-duesseldorf.de/ueber-uns/", "https://www.filmwerkstatt-duesseldorf.de/ueber-uns/", "https://www.filmwerkstatt-duesseldorf.de/ueber-uns/", "https://de.wikipedia.org/wiki/Filmwerkstatt_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Filmwerkstatt_D%C3%BCsseldorf", "https://www.filmwerkstatt-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'filmwerkstatt-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$An der Franklinstraße 5 in **Pempelfort** liegt die Kinder- und Jugendfreizeiteinrichtung **Franklin 5**, zu der eine **Sporthalle** gehört. Die Einrichtung richtet sich an Düsseldorferinnen und Düsseldorfer im Alter von 8 bis 27 Jahren. In der Sporthalle findet unter anderem regelmäßig Nachtfußball statt.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/kiju/freizeiteinrichtungen/pempelfort-franklinstrasse-5", "https://www.duesseldorf.de/kiju/freizeiteinrichtungen/pempelfort-franklinstrasse-5", "https://www.duesseldorf.de/kiju/freizeiteinrichtungen/pempelfort-franklinstrasse-5"]}}'::jsonb)
WHERE slug = 'franklinstrasse-turnhalle' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Fünfzehnwochen** in Gerresheim ist ein Ausstellungs- und Projektraum des gleichnamigen gemeinnützigen Vereins, der Kunst in Düsseldorf fördert. Der Raum liegt am **Apostelplatz**, einem kleinen Park mit Spielplatz. Die nächste Haltestelle ist Von-Gahlen-Straße der U73, etwa 100 Meter entfernt.

Der Verein will Arbeiten von Meisterschülerinnen und Meisterschülern der **Kunstakademie Düsseldorf** sowie anderer Kunst- und Kulturschaffender im Alltag zugänglich machen. Bei den Ausstellungen sprechen die Künstlerinnen und Künstler vor Ort mit dem Publikum, dazu gibt es Vernissagen, **Kunstgespräche** und Finissagen, teils mit Musik oder Tanz. Einen zweiten Raum betreibt der Verein in Golzheim.$txt$, webseite = COALESCE(webseite, 'https://www.fuenfzehnwochen.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/kontakt/", "https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/kontakt/"]}}'::jsonb)
WHERE slug = 'fuenfzehnwochen-gerresheim' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Fünfzehnwochen** in Golzheim ist ein Ausstellungs- und Projektraum des gleichnamigen gemeinnützigen Vereins, der Kunst in Düsseldorf fördert. Der Raum liegt an der Kaiserswerther Straße, die nächste Haltestelle ist **Theodor-Heuss-Brücke** mit den Linien U78 und U79.

Der Verein will Arbeiten von Meisterschülerinnen und Meisterschülern der **Kunstakademie Düsseldorf** sowie anderer Kunst- und Kulturschaffender im Alltag zugänglich machen. Bei den Ausstellungen sprechen die Künstlerinnen und Künstler vor Ort mit dem Publikum, dazu gibt es Vernissagen, **Kunstgespräche** und Finissagen, teils mit Musik oder Tanz. Einen zweiten Raum betreibt der Verein in Gerresheim.$txt$, webseite = COALESCE(webseite, 'https://www.fuenfzehnwochen.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/kontakt/", "https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/%C3%BCber/", "https://www.fuenfzehnwochen.de/kontakt/"]}}'::jsonb)
