UPDATE public.orte SET beschreibung = $txt$Die **Galerie Art Room** ist ein Ausstellungsraum im Düsseldorfer Stadtteil **Gerresheim**. Im Februar 2022 zeigte dort etwa die Neusser Künstlerin Jutta Jung Malerei mit Frauenmotiven.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://textination.de/en/node/24870", "https://textination.de/en/node/24870"]}}'::jsonb)
WHERE slug = 'galerie-artroom' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Gare du Neuss** ist eine Eventlocation in einem früheren **Bahnhofsgebäude** an der Karl-Arnold-Straße in Neuss. Je nach Raumkonzept finden dort Feiern und Tagungen mit 80 bis 450 Gästen statt, Sommerfeste mit überdachtem Außenbereich sind für bis zu 750 Gäste möglich. Genutzt wird das Haus für **Firmenfeiern**, Hochzeiten, Geburtstage, Ausstellungen und Pop-up-Veranstaltungen.

Neben der großen Halle gehört das Café Stückgut zum Ort. Unter dem Namen Gare du Neuss finden dort außerdem **Flohmärkte** statt. Vom **Neusser Hauptbahnhof** sind es über den Ausgang Zufuhrstraße etwa sechs Minuten zu Fuß.$txt$, webseite = COALESCE(webseite, 'https://www.gare-du-neuss.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://eventlocation.gareduneuss.de/location/", "https://eventlocation.gareduneuss.de/location/", "https://eventlocation.gareduneuss.de/location/", "https://eventlocation.gareduneuss.de/location/", "https://flohmarkt.gareduneuss.de/", "https://eventlocation.gareduneuss.de/anfahrt/"]}}'::jsonb)
WHERE slug = 'gare-du-neuss' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Gerhart-Hauptmann-Haus** an der Bismarckstraße ist ein deutsch-osteuropäisches Forum, getragen von der gleichnamigen Stiftung. Eröffnet wurde es im Juni 1963 als „Haus des Deutschen Ostens“ und Begegnungsstätte für Heimatvertriebene, den heutigen Namen trägt es seit 1992.

Der fünfgeschossige **Betonbau** mit verglasten unteren Geschossen entstand 1960 bis 1962 nach Plänen von Walter Kroner und Bruno Lambart. An der Fassade hängt ein 1985 eingeweihtes **Glockenspiel** mit 20 Glocken, umgeben von Wappen früherer deutscher Kulturregionen im Osten. Im Haus liegt der Eichendorff-Saal.

Inhaltlich befasst sich das Haus mit europäischer und deutscher **Zeitgeschichte**. Dazu gehört eine Spezialbibliothek zur Geschichte Ostmittel- und Osteuropas. Das Haus liegt nahe dem Hauptbahnhof.$txt$, webseite = COALESCE(webseite, 'https://www.g-h-h.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Gerhart-Hauptmann-Haus_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'gerhart-hauptmann-haus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Ghorban Delikatessen Manufaktur** an der Heinrich-Heine-Allee ist ein Geschäft für **mediterrane Feinkost** mit angeschlossenem Bistro. Das inhabergeführte Unternehmen stellt seine Produkte nach eigenen Rezepten in einer eigenen Manufaktur und in wenigen traditionellen Handwerksbetrieben her. Weitere Läden gibt es unter anderem in Aachen.

Zum Sortiment gehören **Bio-Olivenöle** aus eigenen Hainen in Murcia, Kalabrien und auf Kreta. Im **Bistro** lassen sich viele Produkte aus eigener Herstellung und von meist ökologisch arbeitenden Erzeugern probieren.$txt$, webseite = COALESCE(webseite, 'https://www.ghorban.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/storys/2022/12/01/sechs-feinkostprodukte-die-gluecklich-machen/", "https://www.ghorban.de/", "https://www.ghorban.de/", "https://www.visitduesseldorf.de/storys/2022/12/01/sechs-feinkostprodukte-die-gluecklich-machen/", "https://www.visitduesseldorf.de/storys/2022/12/01/sechs-feinkostprodukte-die-gluecklich-machen/"]}}'::jsonb)
WHERE slug = 'ghorban-delikatessen-manufaktur' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Ghorban** an der Heinrich-Heine-Allee ist die Düsseldorfer Filiale einer Feinkostmarke für **mediterrane Spezialitäten**. Die Produkte entstehen nach eigenen Rezepten in einer eigenen **Manufaktur** und bei einigen traditionellen Handwerksbetrieben. Weitere Standorte gibt es in Aachen sowie in Märkten in Dortmund, Heiligenhaus und Wuppertal.$txt$, webseite = COALESCE(webseite, 'https://www.ghorban.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ghorban.de/", "https://www.ghorban.de/", "https://www.ghorban.de/"]}}'::jsonb)
WHERE slug = 'ghorban-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Globetrotter** ist ein Fachgeschäft für Outdoor-Ausrüstung, das seine Düsseldorfer Filiale im November 2021 an der Flinger Straße in der **Altstadt** eröffnet hat. Zuvor befand sich das Geschäft an der Königsallee. Die Filiale an der Flinger Straße hat rund 1.500 Quadratmeter Verkaufsfläche.

In der **Clubhütte** finden Vorträge und Workshops statt. Eine hauseigene Werkstatt übernimmt kleinere Reparaturen, außerdem gibt es einen Bereich mit gebrauchter, aufbereiteter **Second-Hand-Ausrüstung**. Zum Haus gehört zudem eine reisemedizinische Praxis, in der Impfungen angeboten werden.$txt$, webseite = COALESCE(webseite, 'https://www.globetrotter.de/filialen/duesseldorf/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://lokalbuero.com/2021/10/18/globetrotter-duesseldorf-zieht-in-die-flinger-strasse/", "https://lokalbuero.com/2021/10/18/globetrotter-duesseldorf-zieht-in-die-flinger-strasse/", "https://lokalbuero.com/2021/10/18/globetrotter-duesseldorf-zieht-in-die-flinger-strasse/", "https://www.globetrotter.de/filialen/duesseldorf/", "https://www.globetrotter.de/filialen/duesseldorf/", "https://www.globetrotter.de/filialen/duesseldorf/"]}}'::jsonb)
WHERE slug = 'globetrotter-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Glow & Patterns** ist ein Düsseldorfer Atelier für handgefertigte **Mosaik**- und Terrazzo-Kunst. Angeboten werden vor allem angeleitete **Mosaik-Workshops**, in denen Teilnehmende eigene Arbeiten gestalten, darunter Kurse für Erwachsene, Eltern-Kind- und Kinder-Workshops sowie ein Intensivkurs. Zusätzlich gibt es Mosaik-Bausätze für zu Hause.$txt$, webseite = COALESCE(webseite, 'https://sites.google.com/view/glow-patterns/home'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://sites.google.com/view/glow-patterns/home", "https://sites.google.com/view/glow-patterns/home", "https://sites.google.com/view/glow-patterns/home"]}}'::jsonb)
WHERE slug = 'glow-patterns-art-studio' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Goethe-Museum** ist in **Schloss Jägerhof** an der Jacobistraße in Pempelfort untergebracht, am Ende der Jägerhofallee im Hofgarten. Getragen wird es von der Anton-und-Katharina-Kippenberg-Stiftung, die 1953 von zwei Erbinnen des früheren Insel-Verlegers Anton Kippenberg gegründet wurde. Das Museum öffnete im Juni 1956. Seit 1987 ist es im Schloss Jägerhof untergebracht.

Nach Angaben des Hauses umfasst die Sammlung rund 50.000 Objekte und ist die größte private **Goethe-Sammlung**. Dazu gehören Handschriften, Bücher, Gemälde, Zeichnungen, Büsten und Kunsthandwerk. Zum Haus gehören außerdem eine Forschungsbibliothek und ein Ort für Kulturveranstaltungen.

Das **Rokoko**-Schloss ließ Kurfürst Karl Theodor von 1752 bis 1763 als Lustschloss errichten, nach Plänen von Johann Joseph Couven, die Nicolas de Pigage nur teilweise ausführte. Nach schweren Schäden im Juni 1943 wurde es ab 1950 von Helmut Hentrich wiederaufgebaut.$txt$, webseite = COALESCE(webseite, 'https://www.goethe-museum.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Schloss_J%C3%A4gerhof", "https://www.goethe-museum.de/en/about-us/the-goethe-museum-duesseldorf", "https://www.goethe-museum.de/en/about-us/the-goethe-museum-duesseldorf", "https://de.wikipedia.org/wiki/Schloss_J%C3%A4gerhof", "https://www.goethe-museum.de/en/about-us/the-goethe-museum-duesseldorf", "https://www.goethe-museum.de/en/about-us/the-goethe-museum-duesseldorf", "https://www.goethe-museum.de/en/about-us/the-goethe-museum-duesseldorf", "https://de.wikipedia.org/wiki/Schloss_J%C3%A4gerhof", "https://de.wikipedia.org/wiki/Schloss_J%C3%A4gerhof"]}}'::jsonb)
WHERE slug = 'goethe-museum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Hamtorkrug** ist eine Gaststätte an der Büttger Straße in der Neusser Innenstadt, die seit Ende der 1960er-Jahre als Musikkneipe bekannt ist. In den 1970er-Jahren trug sie lange nach ihrem damaligen Wirt den Spitznamen „Ossi“.

Das Haus wurde um 1850 als erstes Gebäude unmittelbar vor dem **Hamtor** außerhalb der mittelalterlichen Stadtbefestigung errichtet. Der Kohlenhändler Johann Schmitz hatte den Neubau 1847 beantragt und betrieb dort neben Kohlenhandel und Landwirtschaft eine Gastwirtschaft. Seit 1993 steht das Gebäude auf der **Denkmalliste** der Stadt Neuss. Zum Angebot der Kneipe zählen auch Billard, Dart und Kicker.$txt$, webseite = COALESCE(webseite, 'https://hamtorkrug.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://e-pflicht.ulb.hhu.de/download/pdf/376441", "https://e-pflicht.ulb.hhu.de/download/pdf/376441", "https://e-pflicht.ulb.hhu.de/download/pdf/376441", "https://e-pflicht.ulb.hhu.de/download/pdf/376441", "https://e-pflicht.ulb.hhu.de/download/pdf/376441", "https://freizeitinsider.de/angebot/musikkneipe-hamtorkrug/"]}}'::jsonb)
WHERE slug = 'hamtorkrug' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Hanaro Markt** an der Immermannstraße ist ein **asiatischer Supermarkt** nur wenige Schritte vom Düsseldorfer **Hauptbahnhof** entfernt. Das Sortiment konzentriert sich auf japanische und koreanische Lebensmittel, darunter frische Zutaten, Gewürze und Süßigkeiten. Vor Ort wird zudem frisch zubereitetes Essen zum Mitnehmen angeboten. Das Geschäft wird in zweiter Generation als Familienunternehmen geführt.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/attraktionen/hanaro-markt-56ea5bd93a", "https://www.visitduesseldorf.de/attraktionen/hanaro-markt-56ea5bd93a", "https://www.visitduesseldorf.de/attraktionen/hanaro-markt-56ea5bd93a", "https://www.visitduesseldorf.de/attraktionen/hanaro-markt-56ea5bd93a"]}}'::jsonb)
WHERE slug = 'hanaro-markt' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das Haus der Universität am **Schadowplatz** ist ein Veranstaltungs- und Tagungsort der **Heinrich-Heine-Universität** Düsseldorf in der Innenstadt. Seit 2013 dient es als Forum für den Dialog zwischen Wissenschaft und Stadtgesellschaft. Hier finden die öffentlichen Veranstaltungen der **Bürgeruniversität** sowie weitere Vorträge und Veranstaltungen aus Wissenschaft, Gesellschaft und Kultur statt. Zu den Räumen gehören ein Saal im Untergeschoss, ein Foyer im Erdgeschoss und Besprechungsräume in den oberen Etagen.

Das Gebäude entstand 1896/97 nach Plänen des Büros Kayser & von Großheim zusammen mit dem Düsseldorfer Architekten Max Wöhler als Sitz der **Niederrheinischen Bank**. Später nutzten es unter anderem das Bankhaus Schliep & Co. und ab 2001 die Garantibank International. Die **Sandsteinfassade** im Stil des Historismus mit Elementen der Renaissance steht seit 1982 unter Denkmalschutz. Im Jahr 2011 erwarb die van Meeteren-Stiftung das Haus und ließ es zum Informations- und Veranstaltungszentrum umbauen.$txt$, webseite = COALESCE(webseite, 'https://www.hdu.hhu.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://hdu.hhu.de/en/about-us", "https://hdu.hhu.de/en/about-us", "https://hdu.hhu.de/en/about-us", "https://hdu.hhu.de/en/about-us", "https://www.hdu.hhu.de/en/about-us/history-of-the-building", "https://www.hdu.hhu.de/en/about-us/history-of-the-building", "https://www.hdu.hhu.de/en/about-us/history-of-the-building", "https://www.hdu.hhu.de/en/about-us/history-of-the-building"]}}'::jsonb)
WHERE slug = 'haus-der-universitaet' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Haus Spilles** an der Benrather Schloßallee ist ein selbstverwaltetes Jugendzentrum in Düsseldorf-**Benrath**. Träger ist der Initiativkreis „Jugend in Benrath“ e.V., der in den 1970er-Jahren ein selbstverwaltetes Jugendzentrum für den Stadtteil gefordert hatte. Das Hauptgebäude ist die ehemalige **Posthalterei**, nach einem Umbau ab 1981 nahm das Jugendzentrum 1983 den Betrieb auf.

Zur Anlage gehört außerdem ein neu errichtetes Café-Gebäude mit drei Ebenen, das durch einen Durchgang mit dem Hauptgebäude verbunden ist. Nachmittags richtet sich der **Teens Club** an 10- bis 16-Jährige, im Abendbereich gibt es Cafés unter der Woche sowie Konzerte und Partys am Wochenende. Daneben bietet eine Radiowerkstatt die Möglichkeit, eigene Sendungen im Bürgerfunk zu gestalten.$txt$, webseite = COALESCE(webseite, 'https://spilles.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://spilles.de/hausspilles/haus-spilles/", "https://de.wikipedia.org/wiki/Haus_Spilles", "https://de.wikipedia.org/wiki/Haus_Spilles", "https://de.wikipedia.org/wiki/Haus_Spilles", "https://spilles.de/hausspilles/haus-spilles/", "https://spilles.de/hausspilles/haus-spilles/"]}}'::jsonb)
WHERE slug = 'haus-spilles' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Heine Haus** ist ein Literaturhaus an der Bolkerstraße in der Düsseldorfer **Altstadt**. An dieser Stelle stand das Haus, in dessen Hinterhaus Heinrich Heine 1797 geboren wurde, es wurde im frühen 19. Jahrhundert durch einen Neubau ersetzt. Im Zweiten Weltkrieg wurde das Gebäude 1943 bis auf die Fassade zerstört und ab 1947 wieder aufgebaut.

Seit 2006 dient es als Zentrum für Literatur, seit 2017 unter dem Namen **Heine Haus Literaturhaus Düsseldorf**. Getragen wird es gemeinsam von der Stadt Düsseldorf, einem Förderverein und der Literaturhandlung Müller & Böhm, die den vorderen Teil des Hauses nutzt. Im hinteren Bereich liegen ein Veranstaltungsraum und ein Literaturcafé.

Auf dem Programm stehen vor allem **Autorenlesungen** mit Schwerpunkt auf neuer deutschsprachiger Literatur, dazu Reihen mit internationaler Literatur und Diskussionsabende. Seit 2011 widmet sich das Haus jährlich mit dem Festival „Poesie – Ein Fest im Heine Haus“ der Lyrik, in dessen Rahmen der **PoesieDebütPreis Düsseldorf** vergeben wird.$txt$, webseite = COALESCE(webseite, 'https://www.heinehaus.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Heine_Haus_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'heine-haus-literaturhaus-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Henkel-Saal** gehört zum **Schlösser Quartier** an der Ratinger Straße im Herzen der Düsseldorfer Altstadt. Der Saal bietet rund 550 Quadratmeter Fläche für Veranstaltungen. Eigentümerin der Immobilie ist die städtische Projektgesellschaft IDR AG.

Im Zuge eines neuen Konzepts wurde der Saal modernisiert und zu einer multifunktionalen Eventlocation umgebaut. Seit April 2025 ist er mit dem damals eröffneten **Schlager Café** verbunden. Weiterhin finden im Henkel-Saal auch **Brauchtumsveranstaltungen** statt, etwa der Düsseldorfer Jonges.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/poi/detail/schloesser-quartier-e474325f79", "https://www.ddorf-aktuell.de/?p=119913", "https://www.ddorf-aktuell.de/?p=119913", "https://www.tageskarte.io/gastronomie/detail/concept-family-oeffnet-schlager-cafe-in-duesseldorf.html", "https://www.tageskarte.io/gastronomie/detail/concept-family-oeffnet-schlager-cafe-in-duesseldorf.html", "https://www.tageskarte.io/gastronomie/detail/concept-family-oeffnet-schlager-cafe-in-duesseldorf.html"]}}'::jsonb)
WHERE slug = 'henkel-saal' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Hetjens – Deutsches Keramikmuseum** ist ein Spezialmuseum für Keramik und zeigt Stücke aus rund 8000 Jahren und aus aller Welt. Es liegt im **Palais Nesselrode** an der Schulstraße, wenige Gehminuten von Rheinufer und Burgplatz entfernt.

Das Museum wurde im Mai 1909 eröffnet und geht auf den Nachlass des Sammlers **Laurenz Heinrich Hetjens** zurück, der der Stadt Geld für ein Museum unter seinem Namen vermachte. Das erste Gebäude stand am Hofgartenufer in Pempelfort, 1969 zog das Museum in das Palais Nesselrode um. 1994 kam ein Erweiterungsbau hinzu, in dem auch das Filmmuseum Düsseldorf untergebracht ist.

Grundstock der Sammlung war rheinisches Steinzeug, das im Lauf der Zeit um Keramik aus allen Kontinenten und Epochen ergänzt wurde. Zu den Schwerpunkten der **Dauerausstellung** gehören antike und präkolumbische Keramik, islamische Keramik, Fayence und Majolika, Porzellan sowie zeitgenössische Studiokeramik. Zu sehen ist außerdem eine rekonstruierte **islamische Keramikkuppel** aus Pakistan.$txt$, webseite = COALESCE(webseite, 'https://www.hetjensmuseum.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/hetjens", "https://www.duesseldorf.de/hetjens", "https://de.wikipedia.org/wiki/Hetjens-Museum", "https://de.wikipedia.org/wiki/Hetjens-Museum", "https://de.wikipedia.org/wiki/Hetjens-Museum", "https://de.wikipedia.org/wiki/Hetjens-Museum", "https://de.wikipedia.org/wiki/Hetjens-Museum", "https://de.wikipedia.org/wiki/Hetjens-Museum"]}}'::jsonb)
WHERE slug = 'hetjens-deutsches-keramikmuseum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$hi sunny ist ein Laden für **Home- und Living-Produkte** und Mode in Düsseldorf-Benrath, mit Waren bekannter Marken, kleiner Labels und regionaler Künstlerinnen und Künstler. Eröffnet wurde er im März 2026.

Ergänzt wird das Sortiment durch **kreative Workshops**, die zu festen Terminen stattfinden oder von Gruppen gebucht werden können. Angeboten werden etwa Kurse zu Trockenblumenkränzen, Kerzenherstellung und lufttrocknendem Ton. Der Laden liegt an der Görresstraße am Anfang der Fußgängerzone, nahe Schloss Benrath, in einem denkmalgeschützten **Eckgebäude**.$txt$, webseite = COALESCE(webseite, 'https://hi-sunny.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://hi-sunny.de/about", "https://hi-sunny.de/", "https://hi-sunny.de/about", "https://hi-sunny.de/", "https://hi-sunny.de/about"]}}'::jsonb)
WHERE slug = 'hi-sunny' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Holocafé** an der Immermannstraße bietet **Virtual-Reality-Spiele** für Gruppen. Im Programm sind unter anderem Free-Roam-Spiele wie „Arizona Sunshine“ und „Escape the Lost Pyramid“. Außerdem gibt es **Brettspiele** und Trading Card Games wie Magic: The Gathering. Die Marke startete mit einem Pop-up in den Bilker Arkaden, im Dezember 2018 eröffnete der Düsseldorfer Hauptstandort, damals Am Wehrhahn.$txt$, webseite = COALESCE(webseite, 'https://holocafe.de/de/duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://holocafe.de/de/duesseldorf", "https://holocafe.de/de/duesseldorf/vr-free-roam-games", "https://holocafe.de/de/duesseldorf/brettspiele-trading-card-games", "https://www.ddorf-aktuell.de/?p=7921"]}}'::jsonb)
WHERE slug = 'holocafe' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Industrie- und Handelskammer zu Düsseldorf ist eine **Körperschaft des öffentlichen Rechts** für rund 100.000 Mitgliedsunternehmen aus Düsseldorf und dem Kreis Mettmann. Gegründet wurde sie im Mai 1831 als Königliche Handelskammer zu Düsseldorf. Ihren Sitz hat sie am **Ernst-Schneider-Platz** an der Berliner Allee in der Stadtmitte, wo sie 1957 ihr Gebäude bezog. Der Platz ist nach Ernst Schneider benannt, der die Kammer von 1949 bis 1968 als Präsident leitete, vor dem Gebäude steht eine Raumsäule des Bildhauers Erich Hauser.$txt$, webseite = COALESCE(webseite, 'https://www.ihk.de/duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Industrie-_und_Handelskammer_zu_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Industrie-_und_Handelskammer_zu_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Industrie-_und_Handelskammer_zu_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Industrie-_und_Handelskammer_zu_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'ihk-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **IIK Düsseldorf** bietet an der Eulerstraße **Deutschkurse** für Studium, Beruf und Alltag an, dazu Integrationskurse, Sommerkurse und Englischkurse. Außerdem werden dort **Sprachprüfungen** wie DSH, telc und TestDaF angeboten. Das Institut nutzt die gesamte erste Etage des Gebäudes mit zwölf Kursräumen für bis zu 25 Personen und einem Raum für Kleingruppen. Die Kursräume sind mit Smartboards ausgestattet.$txt$, webseite = COALESCE(webseite, 'https://iik-duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://iik-duesseldorf.de/en/german/around-the-courses/rooms-and-equipment", "https://iik-duesseldorf.de/en/german/around-the-courses/rooms-and-equipment", "https://iik-duesseldorf.de/en/german/around-the-courses/rooms-and-equipment", "https://iik-duesseldorf.de/en/german/around-the-courses/rooms-and-equipment"]}}'::jsonb)
WHERE slug = 'iik-duesseldorf-trainingszentrum-raum-f4' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die International English Library (IEL) ist eine öffentliche **englischsprachige Bibliothek** in Düsseldorf und nach eigenen Angaben die einzige ihrer Art in Nordrhein-Westfalen. Gegründet wurde sie 1946 von der **britischen Besatzung**. Seit 1999 betreibt sie ein internationales Team von **Ehrenamtlichen**; im selben Jahr entstand der Förderverein Friends of International Library e.V., um die Bibliothek vor der Schließung zu bewahren.

Der Bestand umfasst mehr als 21.000 Publikationen, von **klassischer bis zeitgenössischer Literatur**. Regelmäßig gibt es Veranstaltungen, darunter einen Buchclub, Lyrik-Termine und Angebote für Kinder.$txt$, webseite = COALESCE(webseite, 'https://www.international-library.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.international-library.de/", "https://www.international-library.de/about-us", "https://www.international-library.de/", "https://www.international-library.de/", "https://www.international-library.de/"]}}'::jsonb)
WHERE slug = 'international-english-library' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Isla de Cuba ist eine **Latino-Bar** an der Bolkerstraße in der Düsseldorfer **Altstadt**. Serviert werden handgemixte kubanische Cocktails wie der Mojito. Musikalisch dominieren Salsa, Bachata und Reggaeton. Regelmäßig gibt es **Salsa-Abende**, Tanzkurse und Partys mit DJs.$txt$, webseite = COALESCE(webseite, 'https://isladecuba.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/poi/detail/bar-isla-de-cuba-2d028e40d2", "https://www.visitduesseldorf.de/en/poi/detail/bar-isla-de-cuba-2d028e40d2", "https://isladecuba.de/", "https://www.visitduesseldorf.de/en/poi/detail/bar-isla-de-cuba-2d028e40d2"]}}'::jsonb)
WHERE slug = 'isla-de-cuba-latino-bar-en-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**IT'S ART, BABY!**, auch IAB Gallery genannt, ist eine Galerie für zeitgenössische Kunst in einem Innenhof an der Hohen Straße in der **Carlstadt**. Gezeigt werden Arbeiten aufstrebender Künstlerinnen und Künstler aus unterschiedlichen Medien. Die Räume dienen zugleich als Showroom für die **Kunstberatung** des Hauses, die unter anderem Büros, Kanzleien, Praxen und Architekturbüros mit Kunst ausstattet. Außerdem wird die Galerie als Eventlocation angeboten.$txt$, webseite = COALESCE(webseite, 'https://www.itsartbaby.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.itsartbaby.de/", "https://www.itsartbaby.de/", "https://www.itsartbaby.de/", "https://www.itsartbaby.de/"]}}'::jsonb)
WHERE slug = 'it-s-art-baby' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Jazz-Schmiede ist ein Konzertort für **Jazz und Weltmusik** im Düsseldorfer Stadtteil **Bilk**, unweit des Universitätsklinikums. Das Gebäude gehört zum denkmalgeschützten Ensemble **Salzmannbau**, einem ehemaligen Industriegelände aus der Gründerzeit, und diente früher als Schmiede. 1994 wurde es nach Plänen des Architekten Heiner Siefert zu einem kleinen Konzertsaal für bis zu 200 Gäste umgebaut, mit eigenem Flügel und einer Theke im Saal.

Den Konzertbetrieb verantwortet seit September 1995 der Verein **Jazz in Düsseldorf**, der 1994 eigens dafür gegründet wurde. Jedes Jahr finden mindestens 50 Konzerte statt, von kleinen Besetzungen bis zu Big Bands, dazu kommt außerhalb der Sommerpause eine wöchentliche **Jam-Session**. Seit 1996 werden hier regelmäßig Konzerte für WDR und Deutschlandfunk aufgezeichnet. Das Programm erhielt mehrfach den Spielstättenpreis des Landes NRW und viermal den Bundesspielstättenpreis „Applaus“.$txt$, webseite = COALESCE(webseite, 'https://www.jazz-schmiede.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede", "https://de.wikipedia.org/wiki/Jazz-Schmiede"]}}'::jsonb)
WHERE slug = 'jazz-schmiede' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Jivamukti Yoga Düsseldorf** ist ein Yogastudio in der Düsseldorfer **Friedrichstadt**, dessen Eingang an der Oberbilker Allee liegt. Das Studio umfasst rund 220 Quadratmeter, davon etwa 120 für den **Yogaraum**, dazu einen Vorraum mit Gemeinschaftstisch, eine Garderobe und eine Küche. Unterrichtet wird **Jivamukti Yoga**. Daneben gibt es Ausbildungen für Lehrende, Workshops und Kurse für Firmen, außerdem können die Räume für Veranstaltungen gemietet werden.$txt$, webseite = COALESCE(webseite, 'https://jivamuktiyogaduesseldorf.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://jivamuktiyogaduesseldorf.com/studio", "https://jivamuktiyogaduesseldorf.com/studio", "https://jivamuktiyogaduesseldorf.com/studio", "https://jivamuktiyogaduesseldorf.com/studio"]}}'::jsonb)
WHERE slug = 'jivamukti-yoga-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Evangelische Jugendkirche Düsseldorf** ist ein Angebot der Evangelischen Kirche in Düsseldorf, bei dem junge Menschen Kirche mitgestalten. Sie nutzt mit der **Christuskirche** am Campus Jugend in Düsseldorf-**Oberbilk** einen echten Kirchraum. Zu den Angeboten gehören eine Tischgemeinschaft mit gemeinsamem Einkaufen, Kochen und Essen sowie ehrenamtlich organisierte Spiele- und Rollenspielabende. Daneben gibt es Veranstaltungen wie Feriengottesdienste, die Jugendsynode und Rollerdisko.$txt$, webseite = COALESCE(webseite, 'https://www.evdus.de/leben-und-lernen/kinder-und-jugend/jugendkirche'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.evdus.de/leben-und-lernen/kinder-und-jugend/jugendkirche", "https://www.evdus.de/leben-und-lernen/kinder-und-jugend/jugendkirche", "https://www.evdus.de/leben-und-lernen/kinder-und-jugend/jugendkirche", "https://www.evdus.de/leben-und-lernen/kinder-und-jugend/jugendkirche"]}}'::jsonb)
WHERE slug = 'jugendkirche' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Jugendkulturcafé Franzmann** an der Ratinger Straße wird von der **Katholischen Jugendagentur Düsseldorf** getragen und besteht seit 2015. Es bietet jungen Düsseldorferinnen und Düsseldorfern einen geschützten Raum, um sich zu entfalten, sich sozial zu engagieren oder eigene Kunst auf die Bühne zu bringen. Das Café versteht sich als „No-Hate-Area“, in der Vielfalt gelebt wird.

Neben dem Café gibt es kostenlose Workshops, Veranstaltungen und weitere kulturelle Angebote. Beim **Franzmann Stickerfest** zeigte das Haus Sticker- und Paste-up-Arbeiten, die junge Besucherinnen und Besucher gemeinsam mit Streetart-Künstlern der Düsseldorfer Szene erarbeitet hatten.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ddorf-aktuell.de/?p=123228", "https://www.ddorf-aktuell.de/?p=123228", "https://www.ddorf-aktuell.de/?p=123228", "https://www.ddorf-aktuell.de/?p=123228", "https://www.ddorf-aktuell.de/?p=123228"]}}'::jsonb)
WHERE slug = 'jugendkulturcafe-franzmann' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **KaBARett FLiN** ist eine kleine Kabarettbühne an der Ludenberger Straße in Grafenberg, nahe dem Staufenplatz. Gegründet wurde es 1999 als Zimmertheater „Theater FLINgern“ in einem Hinterhof an der Ackerstraße in Flingern. 2014 musste es dort einem Wohnungsbauprojekt weichen.

Im März 2015 eröffnete die Bühne neu im früheren **Haus Marx**, einem Gebäude von 1904. Sie hat rund 80 Plätze. Auf dem Programm stehen **Kabarett** und Comedy sowie eigene Theaterproduktionen, dazu kommt ein gastronomisches Angebot.$txt$, webseite = COALESCE(webseite, 'https://www.kabarett-flin.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/KaBARett_FLiN", "https://de.wikipedia.org/wiki/KaBARett_FLiN", "https://de.wikipedia.org/wiki/KaBARett_FLiN", "https://de.wikipedia.org/wiki/KaBARett_FLiN", "https://de.wikipedia.org/wiki/KaBARett_FLiN", "https://de.wikipedia.org/wiki/KaBARett_FLiN"]}}'::jsonb)
WHERE slug = 'kabarett-flin' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **KIT – Kunst im Tunnel** ist ein unterirdisches Ausstellungshaus für zeitgenössische Kunst in Düsseldorf. Es liegt in einem Restraum, der beim Bau des **Rheinufertunnels** entstand, rund zwei Meter unter der Rheinuferpromenade nahe Landtag und Rheinkniebrücke. Eröffnet wurde es im Februar 2007, betrieben wird es von der **Kunsthalle Düsseldorf**.

Der **Eingangspavillon** auf der Promenade wurde vom Düsseldorfer Büro Fritschi Architekten entworfen, ist zum Rhein hin verglast und beherbergt ein kleines Bistro. Von dort führen Treppe und Aufzug in den rund 888 Quadratmeter großen Ausstellungsbereich zwischen den beiden Tunnelröhren. Der leicht geschwungene Raum ist 140 Meter lang und verjüngt sich von acht Metern auf einen Meter Breite.

Gezeigt werden vor allem Arbeiten junger Künstlerinnen und Künstler, darunter Absolventinnen und Absolventen der **Kunstakademie Düsseldorf**.$txt$, webseite = COALESCE(webseite, 'https://www.kunst-im-tunnel.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel", "https://de.wikipedia.org/wiki/Kunst_im_Tunnel"]}}'::jsonb)
WHERE slug = 'kit' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Klanghaus** ist ein Kulturzentrum in Düsseldorf-Oberbilk unter dem Leitgedanken „Musik, Raum, Bewegung“. Angeboten werden **Instrumental- und Gesangsunterricht**, Tanz, Theater, Kampfkunst, Chöre und Stimmbildung sowie musikalische Früherziehung. Die Räume lassen sich außerdem für Kurse wie Yoga und Pilates, für Workshops, Schulungen, Chorproben und Veranstaltungen **mieten**.$txt$, webseite = COALESCE(webseite, 'https://www.klanghaus-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.klanghaus-duesseldorf.de/", "https://www.klanghaus-duesseldorf.de/", "https://www.klanghaus-duesseldorf.de/vermietung"]}}'::jsonb)
WHERE slug = 'klanghaus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$KLONKK ist eine **Indoor-Eventlocation** in einer früheren Fabrikhalle auf dem **Factory Campus** an der Erkrather Straße. Der StadtStrand Düsseldorf führt sie als neuen eigenen Standort. Auf rund 900 Quadratmetern finden bis zu 200 Personen Platz.

Es gibt eine **Bühne für Live-Acts**, eine Bar, Chill-out-Bereiche sowie Billard und Kicker. Genutzt wird die Halle für Partys, Konzerte, Firmen- und Privatfeiern, aber auch für Workshops und Nachtflohmärkte.$txt$, webseite = COALESCE(webseite, 'https://www.klonkk.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.klonkk.de/", "https://www.stadtstrand-duesseldorf.de/", "https://www.klonkk.de/", "https://www.klonkk.de/", "https://www.klonkk.de/"]}}'::jsonb)
WHERE slug = 'klonkk-stadtstrand-indoor-location' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Kloster Flingern** ist das frühere **Kloster Christi Hilf** an der Flurstraße in Flingern-Nord. Errichtet wurde es 1890 nach Plänen des Architekten Heinrich Florak, ab 1894 zogen die Töchter vom Heiligen Kreuz ein. Die Klosterkirche mit Apsis wurde im Zweiten Weltkrieg weitgehend zerstört und danach wieder aufgebaut. Seit 1988 steht das Gebäude unter **Denkmalschutz**. Im Jahr 2003 verließ der Orden das Kloster.

Heute vereint das Haus Wohnungen, Büros, Ausstellungs- und **Veranstaltungsräume**. Die frühere Kirche wird als Raum für Events vermietet, etwa für Dinner, Vorträge oder Lesungen. Außerdem gibt es ein Yoga-Studio, Ateliers und eine Schmuckwerkstatt.$txt$, webseite = COALESCE(webseite, 'https://www.kloster-flingern.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kuladig.de/Objektansicht/KLD-344101", "https://www.kloster-flingern.de/", "https://www.kloster-flingern.de/"]}}'::jsonb)
WHERE slug = 'kloster-flingern' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Atelierhaus KöX** an der Kölner Straße ist ein selbstorganisierter Ort für Kunst, Soziokultur und Begegnung im Zentrum Düsseldorfs. Getragen wird es von einem **gemeinnützigen Verein**, der das Gebäude selbst verwaltet und dessen Mieterinnen und Mieter zugleich Mitglieder sind. Das Haus ist ein Nachkriegsbau mit fünf Etagen, von denen die oberen vier vorrangig als **Ateliers** für Künstlerinnen und Künstler vorgesehen sind.

Im Erdgeschoss liegen auf rund 100 Quadratmetern die gemeinsam genutzten **Ausstellungs- und Veranstaltungsräume** samt Vereins-Café. Dort finden wechselnde Ausstellungen, Konzerte, Lesungen, Filmabende und **Workshops** statt. Der Ausstellungsraum soll etablierten wie weniger bekannten künstlerischen Positionen Platz bieten, und das kuratorische Team wird jährlich neu besetzt.$txt$, webseite = COALESCE(webseite, 'https://koex-ateliers.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://koex-ateliers.de/", "https://koex-ateliers.de/verein-2/", "https://koex-ateliers.de/verein/", "https://koex-ateliers.de/verein/", "https://koex-ateliers.de/verein/", "https://koex-ateliers.de/verein-2/"]}}'::jsonb)
WHERE slug = 'koex' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Kom(m)ödchen** ist eine Kabarettbühne in der Düsseldorfer Altstadt, gegründet als politisch-literarisches Kabarett. Kay und Lore Lorentz riefen es **1947** im Hinterzimmer einer Kneipe ins Leben, das erste Programm „positiv dagegen“ hatte im März 1947 Premiere.

Weil es im alten Haus an der Hunsrückenstraße zu eng wurde, bot die Stadt Räume in der damals neu gebauten **Kunsthalle** an, in die das Kabarett im April **1967** umzog. Nach dem Tod von Kay Lorentz übernahm Lore Lorentz 1993 die künstlerische Leitung, sie starb im Februar 1994. Der Eingang liegt am **Kay-und-Lore-Lorentz-Platz**, der Saal hat 200 Plätze.

Neben dem **eigenen Ensemble** treten Gäste aus der deutschsprachigen Kabarettszene auf, auch Newcomer. Aus den Ensembles des Hauses gingen unter anderem Hugo Egon Balder, Volker Pispers und Harald Schmidt hervor. Von der Stadtbahn-Haltestelle **Heinrich-Heine-Allee** sind es rund zwei Minuten zu Fuß.$txt$, webseite = COALESCE(webseite, 'https://www.kommoedchen.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Kom(m)%C3%B6dchen", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/theater/", "https://www.kommoedchen.de/kontakt/"]}}'::jsonb)
WHERE slug = 'kom-m-oedchen-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Kräutelle** bietet in Düsseldorf Workshops an, in denen **Naturkosmetik** selbst hergestellt wird, die Kurse finden in den Räumen von Alternavita an der Kühlwetterstraße statt. In kleinen Gruppen rühren die Teilnehmenden Pflegeprodukte wie Hyalurongel, Gesichtswasser, Serum, Creme, Deo und Salbe an und nehmen sie mit nach Hause. Vermittelt wird dabei auch Wissen über **Heilpflanzen**, Öle und Wirkstoffe, Vorkenntnisse sind nicht nötig.

Der Name verbindet die Wörter Kräuter und **Immortelle**, eine Pflanze, die auch getrocknet Form, Farbe und Duft behält. Neben den Kursen gibt es auch Angebote für Gruppen-Events.$txt$, webseite = COALESCE(webseite, 'https://kraeutelle.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://kraeutelle.de/", "https://kraeutelle.de/", "https://kraeutelle.de/", "https://kraeutelle.de/", "https://kraeutelle.de/"]}}'::jsonb)
WHERE slug = 'kraeutelle-naturkosmetik-workshops' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Kulturhaus Süd** an der Fritz-Erler-Straße in Düsseldorf-**Garath** ist ein Kultur- und Bürgerzentrum, das bis zu seiner Modernisierung Freizeitstätte Garath hieß. Die Stadt bezeichnet es als größtes Bürgerhaus Düsseldorfs. Erbaut wurde es von 1972 bis 1974 nach Plänen des Architekten Olaf Jacobsen, eröffnet im April 1975.

Das Gebäude besteht aus elf **Betonkuben**, die um halbe Geschosse versetzt schneckenförmig um einen Innenhof angeordnet sind. Bei der Modernisierung blieb die Bausubstanz erhalten, die Technik wurde erneuert.

Im großen **Saal** finden Vorstellungen des Kino Süd, Kleinkunst und andere Veranstaltungen statt. Im Haus befinden sich außerdem die Stadtteilbücherei, das Zentrum plus der Diakonie, Kurs- und Seminarräume sowie ein Café. Mit der S-Bahn ist das Haus über die Linien S6 und S68 erreichbar.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/jugendamt/familie/buergerhaeuser/fg'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Freizeitst%C3%A4tte_Garath", "https://www.duesseldorf.de/jugendamt/familie/buergerhaeuser/fg", "https://de.wikipedia.org/wiki/Freizeitst%C3%A4tte_Garath", "https://de.wikipedia.org/wiki/Freizeitst%C3%A4tte_Garath", "https://de.wikipedia.org/wiki/Freizeitst%C3%A4tte_Garath", "https://de.wikipedia.org/wiki/Freizeitst%C3%A4tte_Garath", "https://www.duesseldorf.de/jugendamt/familie/buergerhaeuser/fg", "https://www.duesseldorf.de/jugendamt/familie/buergerhaeuser/fg"]}}'::jsonb)
WHERE slug = 'kulturhaus-sued-freizeitstaette-garath' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Kunsthalle Düsseldorf ist ein Ausstellungshaus für **zeitgenössische Kunst** ohne eigene Sammlung. Sie liegt am **Grabbeplatz** gegenüber der Kunstsammlung Nordrhein-Westfalen. Ihre Geschichte reicht auf eine erste Kunsthalle zurück, die im Juli 1881 eröffnet, im Zweiten Weltkrieg stark beschädigt und 1967 abgerissen wurde.

Der heutige Bau von 1967 mit seiner Fassade aus Sichtbeton gilt als Beispiel des **Brutalismus**. Innen bietet er auf drei Etagen drei große Säle und zwei Foyers mit zusammen rund 1.000 Quadratmetern Ausstellungsfläche. Nachdem Ende der 1990er-Jahre ein Abriss verhindert worden war, öffnete das Haus nach einem Umbau im Juli 2002 wieder.

Im selben Gebäude haben auch der **Kunstverein für die Rheinlande und Westfalen**, das Kabarett Kom(m)ödchen, eine Buchhandlung und der Salon des Amateurs ihren Sitz. Einen weiteren Ausstellungsraum betreibt die Kunsthalle mit **KIT – Kunst im Tunnel** unter der Rheinuferpromenade.$txt$, webseite = COALESCE(webseite, 'https://www.kunsthalle-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.kunsthalle-duesseldorf.de/ueber-uns/", "https://de.wikipedia.org/wiki/Kunsthalle_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Kunsthalle_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Kunsthalle_D%C3%BCsseldorf", "https://www.kunsthalle-duesseldorf.de/ueber-uns/", "https://www.kunsthalle-duesseldorf.de/ueber-uns/", "https://www.kunsthalle-duesseldorf.de/ueber-uns/", "https://de.wikipedia.org/wiki/Kunsthalle_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'kunsthalle-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Kunstpalast** ist das städtische Kunstmuseum Düsseldorfs und liegt zwischen Rhein und **Hofgarten** nördlich der Altstadt. Seine Geschichte beginnt **1846** mit einem Verein zur Errichtung einer Gemäldegalerie, der vor allem Werke der Düsseldorfer Malerschule ankaufte. Ein eigenes Kunstmuseum der Stadt öffnete erst 1928.

Das Gebäude gehört zum **Ehrenhof**, den Wilhelm Kreis 1925/26 für die Großausstellung **GeSoLei** plante und der den älteren Ausstellungsbau Kunstpalast von 1902 einbezog. Das Ensemble umschließt mit Kunstpalast und NRW-Forum einen Innenhof und zieht sich über ein Gartenparterre bis zur Tonhalle. Von 1999 bis 2000 entstand hinter der denkmalgeschützten Fassade ein Neubau nach Entwurf von **Oswald Mathias Ungers**. Seit 2020 gehört das benachbarte NRW-Forum zum Kunstpalast.

Die Sammlung umfasst über 100.000 Objekte, darunter Gemälde und Skulpturen vom Mittelalter bis zur Gegenwart sowie Kunstgewerbe, Design, Grafik und Fotografie. Zum Haus gehört auch das **Glasmuseum Hentrich** mit einer bedeutenden Glassammlung. Die **Graphische Sammlung** bewahrt über 90.000 Zeichnungen, Aquarelle und Druckgrafiken aus acht Jahrhunderten.$txt$, webseite = COALESCE(webseite, 'https://www.kunstpalast.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Ehrenhof_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast", "https://de.wikipedia.org/wiki/Museum_Kunstpalast"]}}'::jsonb)
WHERE slug = 'kunstpalast-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Kunstsammlung Nordrhein-Westfalen ist das Kunstmuseum des Landes und zeigt Kunst des 20. und 21. Jahrhunderts an zwei Standorten in Düsseldorf: im **K20** am Grabbeplatz und im **K21** im Ständehaus. Gegründet wurde sie 1961 von der Landesregierung als Stiftung. Zur Sammlung gehören Werke der Klassischen Moderne, etwa von Pablo Picasso, Henri Matisse und Piet Mondrian, sowie rund 130 Zeichnungen und Gemälde von **Paul Klee**.

Das K21 liegt im **Ständehaus** am Kaiserteich, das 1876 bis 1880 nach Plänen von Julius Raschdorff für den Provinziallandtag der preußischen Rheinprovinz gebaut wurde. Von 1949 bis 1988 tagte dort der Landtag von Nordrhein-Westfalen. Nach einem Umbau, bei dem eine Kuppel aus Glas und Stahl das Dach der Nachkriegszeit ersetzte, öffnete das Haus im April 2002 als Museum. Im K21 steht **Gegenwartskunst** ab etwa 1980 im Mittelpunkt.$txt$, webseite = COALESCE(webseite, 'https://www.kunstsammlung.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Kunstsammlung_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Kunstsammlung_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Kunstsammlung_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/St%C3%A4ndehaus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/St%C3%A4ndehaus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/St%C3%A4ndehaus_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/St%C3%A4ndehaus_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'kunstsammlung-nrw' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Landtag Nordrhein-Westfalen** ist das Parlament des Landes, zu seinen zentralen Aufgaben gehören Gesetzgebung, die Wahl des Ministerpräsidenten und die Kontrolle der Regierung. Sein Gebäude steht im Regierungsviertel direkt am **Rhein**, in der Nähe des Medienhafens.

Der Neubau wurde 1988 fertiggestellt und stammt vom Architekturbüro Eller, Moser, Walter + Partner. Sechs halbkreisförmige Bauteile gruppieren sich um den runden **Plenarsaal** in der Mitte. Zuvor tagte das Parlament von 1949 bis 1988 im **Ständehaus**, das für nur rund 70 Abgeordnete ausgelegt war.

Für Einzelpersonen und Gruppen gibt es einen eigenen **Besuchereingang** und einen Besucherdienst. Die nächste Haltestelle ist Landtag/Kniebrücke an den Straßenbahnlinien 706, 708 und 709.$txt$, webseite = COALESCE(webseite, 'https://www.landtag.nrw.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Landtag_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Landtag_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Landtag_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Landtag_Nordrhein-Westfalen", "https://de.wikipedia.org/wiki/Landtag_Nordrhein-Westfalen", "https://www.landtag.nrw.de/home/ubersichtsseite/ihr-besuch-im-landtag.html", "https://www.landtag.nrw.de/home/service/anfahrt.html"]}}'::jsonb)
WHERE slug = 'landtag-nrw' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**LaserTag Evolution** ist eine Lasertag-Halle im Stadtteil **Bilk**. Gespielt wird mit Sensorwesten und Phasern in einem Labyrinth im **Science-Fiction-Stil** mit Portalen, Podesten, Basen und mehr als 60 interaktiven Zielen. Bis zu 33 Spielerinnen und Spieler in bis zu acht Teams können gleichzeitig antreten.

Zum Haus gehören eine **Lounge**, ein Eventraum, eine Bar am Eingang und eine rund 250 Quadratmeter große Außenterrasse. Gefeiert werden dort unter anderem **Kindergeburtstage**, Junggesellenabschiede und Firmenfeiern mit bis zu 200 Gästen.$txt$, webseite = COALESCE(webseite, 'https://www.lasertag-evolution.com'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.lasertag-evolution.com/", "https://www.lasertag-evolution.com/", "https://www.lasertag-evolution.com/", "https://www.lasertag-evolution.com/", "https://www.lasertag-evolution.com/"]}}'::jsonb)
WHERE slug = 'lasertag-evolution-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Leica Galerie Düsseldorf zeigt wechselnde **Fotografie-Ausstellungen** national und international bekannter Fotografinnen und Fotografen. Sie gehört zum Netz der **Leica Galerien**, das vor rund 50 Jahren mit einer ersten Galerie in Wetzlar begann und inzwischen 27 Häuser weltweit umfasst.$txt$, webseite = COALESCE(webseite, 'https://leica-camera.com/de-AT/leica-galerien/leica-galerie-duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.leica-oskar-barnack-award.com/en/information/leica-galleries/dusseldorf.html", "https://www.duesseldorf.de/fotografie"]}}'::jsonb)
WHERE slug = 'leica-galerie-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Light Space Movement** ist ein Studio für Bewegung und Yoga in einem Hinterhof an der Gerresheimer Straße in Düsseldorf. Das Angebot umfasst **Privatstunden** nach einer Methode, die Elemente aus Yoga, Tai Chi, Qigong, funktionellem Training und Achtsamkeit verbindet. Außerdem gibt es **Workshops**, etwa zu Handstand, Armbalancen und Mobilität, sowie Bewegungscoachings für Unternehmen. Das Studio veranstaltet zudem Retreats und kann gemietet werden.$txt$, webseite = COALESCE(webseite, 'https://lightspacemovement.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://lightspacemovement.de/", "https://lightspacemovement.de/", "https://lightspacemovement.de/", "https://lightspacemovement.de/"]}}'::jsonb)
WHERE slug = 'light-space-movement' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Lima's RestoBar** an der Münsterstraße in Düsseldorf ist ein Restaurant mit Schwerpunkt auf **peruanischer Küche**. Nach eigenen Angaben besteht es seit 2017 und war das erste Restaurant in Düsseldorf, das sich auf gehobene peruanische Küche konzentriert. Der Name ist eine Anspielung auf die peruanische Hauptstadt **Lima**, deren Küche Einflüsse aus vier Kontinenten vereint. Neben dem Restaurantbetrieb gehört auch ein Catering zum Angebot.$txt$, webseite = COALESCE(webseite, 'https://www.limasrestobar.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.limasrestobar.de/kontakt/", "https://www.limasrestobar.de/uber-uns/", "https://www.limasrestobar.de/uber-uns/", "https://www.limasrestobar.de/uber-uns/"]}}'::jsonb)
WHERE slug = 'limas-restobar' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Machen & Lachen** ist ein Yogastudio in Düsseldorf, das Yoga, Meditation und persönliche Begleitung anbietet, vor Ort und online. Das Studio liegt in einem ruhigen **Hinterhof** an der Schirmerstraße in Pempelfort. Auf dem Kursplan stehen Vinyasa, Yin, Hatha und Kundalini Yoga sowie Rückenyoga, dazu Fitnesskurse, Meditation und Atemarbeit. Außerdem bietet das Studio eine **Yogalehrer-Ausbildung**, Einzelbegleitung und ein Online-Studio an.$txt$, webseite = COALESCE(webseite, 'https://www.machenundlachen.com'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.machenundlachen.com/", "https://urbansportsclub.com/de/venues/machenlachen-yogastudio", "https://urbansportsclub.com/de/venues/machenlachen-yogastudio", "https://www.machenundlachen.com/"]}}'::jsonb)
WHERE slug = 'machen-lachen-yoga-studio' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Maison Zen** ist ein Studio für **mentale Gesundheit** an der Hammer Dorfstraße in Düsseldorf. Es bietet Kurse, Workshops und Einzeltrainings rund um **Achtsamkeit** und Stressbewältigung an.

Zum regelmäßigen Programm gehören unter anderem Anti-Stress-Yoga, Kurse mit **Atem und Meditation**, Yoga Nidra sowie Klang- und Entspannungsyoga. Daneben gibt es Workshops, etwa zur Einführung in die Meditation oder zum Thema Selbstmitgefühl, sowie ein achtwöchiges Präventionsprogramm zur Achtsamkeit. Die Kursräume können auch gemietet werden.$txt$, webseite = COALESCE(webseite, 'https://www.maisonzen.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.maisonzen.de/", "https://www.maisonzen.de/", "https://www.maisonzen.de/", "https://www.maisonzen.de/", "https://www.maisonzen.de/"]}}'::jsonb)
WHERE slug = 'maison-zen-studio-fuer-mentale-gesundheit' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Maschinendorf** im Hinterhof der Birkenstraße in Düsseldorf-Flingern ist ein Coworking-Space für Handwerk, Kunst und Kreative. Untergebracht ist es in den weitläufigen Räumen der ehemaligen **Schreinerei Otto Kunze**. Auf rund 2500 Quadratmetern und drei Etagen gibt es unter anderem Werkstätten für Metall, Holz, Siebdruck und Textil.

Entstanden ist das Projekt, als der Coworking-Space Super7000 und der Verein **GarageLab** nach der Schließung der Schreinerei neue Räume suchten. Betrieben wird das Maschinendorf von einer gemeinnützigen GmbH. Neben der offenen Werkstatt gibt es **Workshops**, etwa zum Aufarbeiten von Möbeln oder zum Polstern, sowie Veranstaltungen wie Konzerte, einen Tag der offenen Tür und ein Sommerfest. Erhalten geblieben ist außerdem eine Kantine aus den 1970er-Jahren.$txt$, webseite = COALESCE(webseite, 'https://www.maschinendorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/storys/2026/01/13/coworkingspace-maschinendorf-flingern/", "https://www.visitduesseldorf.de/storys/2026/01/13/coworkingspace-maschinendorf-flingern/", "https://www.maschinendorf.de/", "https://www.visitduesseldorf.de/storys/2026/01/13/coworkingspace-maschinendorf-flingern/", "https://www.maschinendorf.de/", "https://www.maschinendorf.de/", "https://www.maschinendorf.de/"]}}'::jsonb)
WHERE slug = 'maschinendorf-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Maxhaus** an der Schulstraße in der Carlstadt ist das katholische Stadthaus in Düsseldorf und bildet mit der benachbarten Maxkirche einen Gebäudekomplex. Der barocke Backsteinbau wurde 1661 als **Franziskanerkloster** fertiggestellt. Nach der Säkularisation 1803 zog ein Lyzeum ein, das auch Heinrich Heine besuchte.

Nach rund sechs Jahren Umbau wurde das Haus im September 2006 wiedereröffnet, dabei erhielt der Innenhof innerhalb des Kreuzgangs ein Dach aus **Glas und Stahl**. Der Umbau wurde 2010 unter anderem als „Vorbildlicher Bau“ des Landes NRW ausgezeichnet. Zu den Räumen gehören der Klosterhof, der Antoniussaal, mehrere Seminarräume und ein Raum der Stille. Im Keller zeigt die Dauerausstellung „Das verborgene Kloster“ die Baugeschichte.

Das Programm umfasst Kunst, Musik, Wort, Glaube und Führungen, im Klosterhof gibt es ein **Bistro**. Zu den festen Reihen gehören die Düsseldorfer Mittwochgespräche, die es seit 1961 gibt.$txt$, webseite = COALESCE(webseite, 'https://www.maxhaus.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Maxhaus", "https://de.wikipedia.org/wiki/Maxhaus", "https://de.wikipedia.org/wiki/Maxhaus", "https://de.wikipedia.org/wiki/Maxhaus", "https://de.wikipedia.org/wiki/Maxhaus", "https://www.maxhaus.de/", "https://de.wikipedia.org/wiki/Maxhaus", "https://www.maxhaus.de/", "https://de.wikipedia.org/wiki/Maxhaus"]}}'::jsonb)
WHERE slug = 'maxhaus' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Merkur Spiel-Arena ist ein **Fußballstadion** mit schließbarem Dach im Düsseldorfer Stadtteil **Stockum**, neben dem Messegelände. Sie wurde von 2002 bis 2004 als Ersatz für das Rheinstadion gebaut und im Januar 2005 offiziell eingeweiht. Bis 2009 hieß sie LTU Arena, danach bis 2018 Esprit Arena, seit August 2018 trägt sie ihren heutigen Namen.

Seit 2004 trägt **Fortuna Düsseldorf** hier ihre Heimspiele aus. Das Stadion bietet 54.600 Plätze, bei Konzerten bis zu 66.000. Zu den großen Veranstaltungen gehörten der **Eurovision Song Contest 2011** und Spiele der Fußball-Europameisterschaft 2024. Direkt am Stadion liegt der U-Bahnhof „Merkur Spiel-Arena/Messe Nord“ mit Verbindung in die Innenstadt.$txt$, webseite = COALESCE(webseite, 'https://www.merkur-spiel-arena.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena", "https://de.wikipedia.org/wiki/Merkur_Spiel-Arena"]}}'::jsonb)
WHERE slug = 'merkur-spiel-arena' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Messe Düsseldorf** betreibt ihr Messegelände in Stockum am Rhein, wenige Kilometer vom Flughafen entfernt. Das Gelände umfasst 18 Hallen mit rund 262.700 Quadratmetern Hallenfläche sowie etwa 43.000 Quadratmeter Freigelände. An Halle 6 schließt die Merkur Spiel-Arena an.

Die Messegesellschaft wurde 1947 als NOWEA gegründet, 1971 zog die Messe nach Stockum. Die Düsseldorfer Messetradition reicht bis zur Bergischen Gewerbeausstellung von 1811 zurück, die Ausstellung **GeSoLei** zog 1926 rund 7,5 Millionen Besucher an. Zu den bekannten Messen gehören **boot**, drupa, Medica, interpack und die Kunststoffmesse „K“. Gesellschafter sind unter anderem die Stadt Düsseldorf und das Land Nordrhein-Westfalen.

Erreichbar ist das Gelände mit den **Stadtbahnlinien** U78 und U79, Haltestellen sind Messe Ost/Stockumer Kirchstraße und Messe Nord/Merkur Spiel-Arena.$txt$, webseite = COALESCE(webseite, 'https://www.messe-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Messe_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'messe-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Metropol** an der Brunnenstraße in Düsseldorf-Bilk gehört zu den Düsseldorfer Filmkunstkinos. Eröffnet wurde es im Juni 1940; der ursprüngliche Saal mit über 800 Plätzen wurde im Krieg zerstört und 1949 wieder aufgebaut. 1965 wurde das Haus abgerissen und neu errichtet, 1972 öffnete es als **Repertoirekino** wieder.

Seit 1979 wird das Metropol als **Programmkino** geführt, 1992 kamen der zweite Saal Phantom und das Kinocafé Playtime hinzu. Im Mai 2013 wurde die Technik vollständig auf digitale Projektion umgestellt, nach einem siebenmonatigen Umbau öffnete das Kino im November 2023 wieder. Heute verteilen sich rund 158 Plätze auf die drei Säle **Cinerama**, Phantom und Souterrain.

Gezeigt werden vor allem **Erstaufführungen** aus dem Bereich Filmkunst, oft in Originalfassung mit Untertiteln, dazu Filmreihen, Kinderkino und Lesungen. Für sein Programm wird das Haus regelmäßig vom Kulturstaatsminister und der **Filmstiftung NRW** ausgezeichnet.$txt$, webseite = COALESCE(webseite, 'https://filmkunstkinos.de/kinos/metropol/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://filmkunstkinos.de/kinos/metropol/", "https://www.visitduesseldorf.de/attraktionen/metropol-63d7acd8bb"]}}'::jsonb)
WHERE slug = 'metropol-kino' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Mitsubishi Electric Halle** ist eine Mehrzweckhalle in **Oberbilk**, in der Konzerte, Shows und Sportveranstaltungen stattfinden. Eröffnet wurde sie **1971** unter dem Namen **Philipshalle**, seit 2011 trägt sie den Namen ihres heutigen Sponsors. Die Halle gehört der Stadt Düsseldorf und wird von der **D.LIVE** betrieben.

Der Innenraum umfasst rund **3.300 Quadratmeter** und fasst bis zu **7.500** Menschen. Ausfahrbare Tribünen und ein Vorhangsystem erlauben unterschiedliche Aufteilungen des Saals. Dazu kommen zwei **Foyers** mit jeweils rund 900 Quadratmetern und eine Außenterrasse.

Die Halle liegt an der Siegburger Straße direkt neben dem **Volksgarten**. Die nächste Haltestelle ist **Oberbilk S U**, die von Stadtbahn und S-Bahn angefahren wird und nur wenige Gehminuten entfernt liegt.$txt$, webseite = COALESCE(webseite, 'https://www.mitsubishi-electric-halle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://www.mitsubishi-electric-halle.de/veranstalter/raumuebersicht", "https://de.wikipedia.org/wiki/Mitsubishi_Electric_Halle", "https://www.mitsubishi-electric-halle.de/besucherinfos/anfahrt"]}}'::jsonb)
WHERE slug = 'mitsubishi-electric-halle' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Monkeyspot** an der Schiessstraße ist eine Boulderhalle im Gewerbegebiet von Düsseldorf-**Heerdt**. Sie wurde im Mai 2013 als erster Standort der Kette eröffnet, später kamen Hallen in Duisburg und Mönchengladbach hinzu. In der Halle gibt es rund 250 Boulder, die wöchentlich neu geschraubt werden.

Neben dem Hauptbereich gibt es einen separaten **Trainingsbereich** und einen Kinderbereich. Für Einsteiger werden Anfängerkurse zu Sicherheit und Grundtechniken angeboten. Ein **Bistro** mit Außenbereich und ein Shop für Kletterschuhe und Zubehör ergänzen das Angebot.$txt$, webseite = COALESCE(webseite, 'https://monkeyspot.de/startseite-duesseldorf/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://monkeyspot.de/startseite-duesseldorf/", "https://monkeyspot.de/startseite-duesseldorf/", "https://monkeyspot.de/startseite-duesseldorf/", "https://monkeyspot.de/startseite-duesseldorf/", "https://monkeyspot.de/startseite-duesseldorf/", "https://monkeyspot.de/startseite-duesseldorf/"]}}'::jsonb)
WHERE slug = 'monkeyspot-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **MS RheinFantasie** ist ein Eventschiff der Reederei Köln-Düsseldorfer (KD), das für Partyfahrten, Firmenveranstaltungen und private Feiern genutzt wird. Das 2011 vom Stapel gelaufene Schiff ist gut 85 Meter lang und 14 Meter breit und bietet Platz für bis zu 1.000 Gäste. Eingesetzt wird es nach Angaben der Reederei vor allem ab Köln und Bonn.

An Bord gibt es einen **Galeriesalon** mit rund 35 Quadratmeter großer Bühne, zwei Aussichtssalons im Bug und ein etwa 900 Quadratmeter großes **Freideck**. Im Juni 2021 erhielt die MS RheinFantasie den **Green Award** als besonders nachhaltiges Schiff.$txt$, webseite = COALESCE(webseite, 'https://www.k-d.com/flotte/ms-rheinfantasie/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.k-d.com/flotte/ms-rheinfantasie/", "https://www.k-d.com/flotte/ms-rheinfantasie/", "https://www.k-d.com/flotte/ms-rheinfantasie/", "https://www.k-d.com/flotte/ms-rheinfantasie/", "https://www.k-d.com/flotte/ms-rheinfantasie/"]}}'::jsonb)
WHERE slug = 'ms-rheinfantasie' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **NEBN Gallery & Rooms** an der Eisenstraße in Düsseldorf-**Oberbilk** ist eine Galerie mit angeschlossenem Mehrzweckraum. Sie befindet sich in einer ehemaligen **Metzgerei** von rund 140 Quadratmetern, die jahrzehntelang leer stand und vor der Nutzung rund acht Monate lang saniert wurde. Die Eröffnung fand im April 2023 statt.

Im vorderen Teil liegen Galerie und Showroom für **zeitgenössische Kunst**. Der hintere Raum dient als Ort für Co-Working, Präsentationen und Treffen. Neben Vernissagen finden dort auch Veranstaltungen wie Strick-Treffen statt.$txt$, webseite = COALESCE(webseite, 'https://www.nebn.info/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.nebn.info/about", "https://www.nebn.info/about", "https://www.theycallitkleinparis.de/2023/04/25/martin-heck-und-johanna-jacob-im-interview-wir-haben-viel-vor/", "https://www.nebn.info/about", "https://www.nebn.info/about", "https://www.nebn.info/about"]}}'::jsonb)
WHERE slug = 'nebn-gallery' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Niemandsland e.V.** ist ein sozial-ökologischer Nachbarschaftsverein an der Heerstraße in Düsseldorf. Der Verein setzt sich für Ökologie, Kultur und **soziale Gerechtigkeit** ein. Ideen zu Umwelt- und Sozialthemen werden dort gemeinsam umgesetzt, das Angebot ist offen für alle.

Zu den Projekten gehört ein **Umsonstladen**, in dem Kleidung und nicht mehr benötigte Dinge kostenlos getauscht, mitgenommen und abgegeben werden können. Außerdem gibt es eine Holz-, eine Fahrrad- und eine Töpferwerkstatt. Auf dem Gelände liegt ein gemeinschaftlich bewirtschafteter **Garten**, dazu kommen ein gemeinsamer Mittagstisch, Veranstaltungen und Feste.$txt$, webseite = COALESCE(webseite, 'https://niemandsland.org'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/attraktionen/niemandsland-e.v.-9b5ed1493d", "https://niemandsland.org/gegenwart-und-zukunft/", "https://www.visitduesseldorf.de/attraktionen/niemandsland-e.v.-9b5ed1493d", "https://www.visitduesseldorf.de/attraktionen/niemandsland-e.v.-9b5ed1493d", "https://niemandsland.org/", "https://www.visitduesseldorf.de/attraktionen/niemandsland-e.v.-9b5ed1493d"]}}'::jsonb)
WHERE slug = 'niemandsland-e-v' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Nordrhein-Westfälische Akademie der Wissenschaften und der Künste** ist eine Wissenschaftsakademie mit Sitz in Düsseldorf. Ihr Ursprung ist die Arbeitsgemeinschaft für Forschung, die Ministerpräsident Karl Arnold 1950 gründete, 1970 wurde daraus eine Akademie. Seit 2008 gehört eine Klasse der Künste dazu, damit nahm sie als erste deutsche Akademie die Künste als eigenständige Klasse auf. Daneben gibt es Klassen für Naturwissenschaften und Medizin, für Geisteswissenschaften sowie für Ingenieur- und Wirtschaftswissenschaften.

Die Akademie hat ihren Sitz im **Karl-Arnold-Haus** an der Palmenstraße in Unterbilk, direkt am Florapark. Der Bau entstand von 1958 bis 1960 nach Plänen von Hans Schwippert und Friedrich Kohlmann. Er hat zwei Säle für 400 und 80 Personen, einen rechteckigen Kongresssaal und einen runden **Diskussionssaal**. Zum Programm der Akademie gehören Vorträge, wissenschaftliche Sitzungen und öffentliche Veranstaltungen.$txt$, webseite = COALESCE(webseite, 'https://www.awk.nrw'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Nordrhein-Westf%C3%A4lische_Akademie_der_Wissenschaften_und_der_K%C3%BCnste", "https://de.wikipedia.org/wiki/Nordrhein-Westf%C3%A4lische_Akademie_der_Wissenschaften_und_der_K%C3%BCnste", "https://de.wikipedia.org/wiki/Nordrhein-Westf%C3%A4lische_Akademie_der_Wissenschaften_und_der_K%C3%BCnste", "https://de.wikipedia.org/wiki/Nordrhein-Westf%C3%A4lische_Akademie_der_Wissenschaften_und_der_K%C3%BCnste", "https://de.wikipedia.org/wiki/Karl-Arnold-Haus", "https://de.wikipedia.org/wiki/Karl-Arnold-Haus", "https://de.wikipedia.org/wiki/Karl-Arnold-Haus", "https://de.wikipedia.org/wiki/Nordrhein-Westf%C3%A4lische_Akademie_der_Wissenschaften_und_der_K%C3%BCnste"]}}'::jsonb)
WHERE slug = 'nrw-akademie-der-wissenschaften-und-der-kuenste' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das NRW-Forum ist ein **Ausstellungshaus** im **Ehrenhof** nördlich der Altstadt, zwischen Rhein und Hofgarten. Schwerpunkte des Programms sind **Fotografie, Pop und digitale Kultur**, gezeigt in Ausstellungen, Festivals und Workshops. Das Gebäude entstand 1925 bis 1926 nach Plänen von Wilhelm Kreis für die Ausstellung GeSoLei und beherbergte zunächst das Reichsmuseum für Gesellschafts- und Wirtschaftskunde.

Das Ensemble des Ehrenhofs steht unter **Denkmalschutz**. Nach einer umfassenden Sanierung wurde das Haus im Oktober 1998 als „NRW Forum Kultur und Wirtschaft“ wiedereröffnet. Seit 2016 wird es von der Stadt Düsseldorf getragen und gehört seit 2020 zur Stiftung Museum Kunstpalast.$txt$, webseite = COALESCE(webseite, 'https://www.nrw-forum.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/NRW-Forum", "https://de.wikipedia.org/wiki/NRW-Forum", "https://de.wikipedia.org/wiki/NRW-Forum", "https://de.wikipedia.org/wiki/NRW-Forum", "https://de.wikipedia.org/wiki/NRW-Forum", "https://de.wikipedia.org/wiki/NRW-Forum"]}}'::jsonb)
WHERE slug = 'nrw-forum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**OBD ART** ist ein Kunstatelier und Kulturraum in Düsseldorf, in dem Workshops in Malerei, Töpfern und kunsttherapeutisch angelehnten Techniken sowie Gemeinschaftsveranstaltungen stattfinden. Ein Schwerpunkt liegt auf **englischsprachigen Angeboten** für Frauen und queere Menschen, offen ist das Atelier aber auch für die übrige kreative Community.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://dasauge.de/-obd-art", "https://dasauge.de/-obd-art"]}}'::jsonb)
WHERE slug = 'obd-art-studio-community-space' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Oberschlesische Landesmuseum** in Ratingen-**Hösel** widmet sich der Geschichte und Kultur Oberschlesiens. Es sammelt, bewahrt und zeigt das kulturelle Erbe der Region und versteht sich auch als außerschulischer Lernort. Eröffnet wurde das Museum 1983, getragen wird es von der Stiftung Haus Oberschlesien.

Das heutige **Museumsgebäude** aus drei aneinandergefügten Kuben wurde 1998 eröffnet und stammt vom Kölner Büro Walter von Lom & Partner. Es bietet rund 2.000 Quadratmeter Fläche auf drei Etagen.

Die **Dauerausstellung** behandelt Oberschlesien vor der Industrialisierung, die Zeit von Industrie und Bergbau sowie die Politik des 20. Jahrhunderts. Gefördert wird das Museum vom Land Nordrhein-Westfalen.$txt$, webseite = COALESCE(webseite, 'https://oberschlesisches-landesmuseum.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Oberschlesisches_Landesmuseum", "https://oberschlesisches-landesmuseum.de/", "https://de.wikipedia.org/wiki/Oberschlesisches_Landesmuseum", "https://de.wikipedia.org/wiki/Oberschlesisches_Landesmuseum", "https://de.wikipedia.org/wiki/Oberschlesisches_Landesmuseum", "https://oberschlesisches-landesmuseum.de/", "https://de.wikipedia.org/wiki/Oberschlesisches_Landesmuseum"]}}'::jsonb)
WHERE slug = 'oberschlesisches-landesmuseum' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Ohrensessel** an der Tonhallenstraße ist ein Café mit angeschlossener **Galerie**, eingerichtet mit bunten Ohrensesseln aus aller Welt. Eröffnet wurde es im April 2022.

An den Wänden hängen moderne Kunstwerke, die auch gekauft werden können. Neben dem Café mit Frühstück, Snacks und hausgemachten Kuchen gibt es einen kleinen **Workspace** für etwa zehn Personen. Für Veranstaltungen lässt sich das Café mit bis zu 30 Gästen buchen.$txt$, webseite = COALESCE(webseite, 'https://www.ohrensessel-cafe.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ohrensessel-cafe.de/", "https://www.ohrensessel-cafe.de/", "https://www.ohrensessel-cafe.de/", "https://www.ohrensessel-cafe.de/", "https://www.ohrensessel-cafe.de/"]}}'::jsonb)
WHERE slug = 'ohrensessel-cafe-galerie' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Opernhaus Düsseldorf** an der Heinrich-Heine-Allee ist Spielstätte und Verwaltungssitz der **Deutschen Oper am Rhein**. Es liegt am Rand der Altstadt zwischen **Hofgarten** und Königsallee. Die Deutsche Oper am Rhein ist eine Theatergemeinschaft der Städte Düsseldorf und Duisburg, wurde 1956 gegründet und umfasst neben der Oper auch die Compagnie Ballett am Rhein.

Das Gebäude wurde **1875** als Stadttheater nach Plänen von Ernst Giese im Stil der italienischen Renaissance eröffnet. Bei Luftangriffen 1943 wurde es stark beschädigt. Von 1954 bis 1956 bauten Paul Bonatz, Julius Schulte-Frohlinde und Ernst Huhn das Haus grundlegend um und gaben ihm sein heutiges Erscheinungsbild. Seit **1994** steht es unter Denkmalschutz.

Bei einer Sanierung 2006/2007 kam ein Orchester- und Ballettprobensaal mit zehn Meter breiter Glasfassade zum Hofgarten hinzu. Im Keller lagert der **Fundus** mit rund 50.000 Kostümen. Nächste Haltestelle ist **Heinrich-Heine-Allee**, vom Hauptbahnhof sind es drei U-Bahn-Stationen.$txt$, webseite = COALESCE(webseite, 'https://www.operamrhein.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ueber-uns/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://de.wikipedia.org/wiki/Opernhaus_D%C3%BCsseldorf_(1943)", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/", "https://www.operamrhein.de/ihr-besuch/opernhaus-duesseldorf/"]}}'::jsonb)
WHERE slug = 'opernhaus-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das Palais Wittgenstein an der Bilker Straße in der **Carlstadt** ist ein städtisches **Kulturzentrum**. Das Gebäude entstand nach 1790 für den Weinhändler Heinrich Huyssen, zu den späteren Eigentümern gehörte von 1874 bis 1876 Prinz Alexander zu Sayn-Wittgenstein. 1953 kaufte die Stadt Düsseldorf den Komplex. Nach schweren Schäden im Zweiten Weltkrieg wurde er 1974 bis 1976 außen historisch rekonstruiert und innen modernisiert, 1976 eröffnete das Kulturzentrum.

Zum Haus gehören ein **Kammermusiksaal** mit 234 Plätzen für Konzerte und Lesungen sowie das **Düsseldorfer Marionetten-Theater** im Innenhof. Seit 1977 ist außerdem das Institut français Düsseldorf im Palais untergebracht. Das Gebäude ist in der Denkmalliste der Stadt als Baudenkmal eingetragen.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Palais_Wittgenstein_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'palais-wittgenstein' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **pialana Manufaktur** ist eine kleine Düsseldorfer Werkstatt für handgestrickte Einzelstücke und Kleinserien. Daneben entstehen dort Sonderanfertigungen für Film und Bühne.

Angeboten werden außerdem **Workshops** zum Stricken, Häkeln und Upcycling, darunter Anfängerkurse, eine wöchentliche Strick-Werkstatt und Kurse für Kinder. Beim Upcycling geht es auch um Reparaturtechniken wie die japanische Flicktechnik **Sashiko**. Die Kurse finden in kleinen Runden von drei bis fünf Personen in Düsseldorf-**Golzheim** statt.$txt$, webseite = COALESCE(webseite, 'https://pialana.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://pialana.de/", "https://pialana.de/", "https://pialana.de/", "https://pialana.de/", "https://pialana.de/faq/"]}}'::jsonb)
WHERE slug = 'pialana-manufaktur' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Plange Mühle FUENF**, kurz PM5, ist ein Bistro mit Catering- und Eventbetrieb an der Straße Plange Mühle in Düsseldorf. Werktags gibt es Frühstück, hausgemachten Mittagstisch mit **mediterranen Einflüssen** sowie Kaffee und selbst gebackene Kuchen. Außerhalb der Öffnungszeiten wird das Haus zur **Eventlocation**, etwa für Firmenfeiern, Grillabende, Hochzeiten und private Feste. Namensgeber der Straße ist die 1906 errichtete Plange Mühle im Hafen, deren denkmalgeschützte Gebäude nach dem Ende des Mahlbetriebs 1998 für Büros, Ausstellungen, Freizeit und Gastronomie umgebaut wurden.$txt$, webseite = COALESCE(webseite, 'https://www.pm5-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.pm5-duesseldorf.de/", "https://www.pm5-duesseldorf.de/", "https://www.pm5-duesseldorf.de/", "https://de.wikipedia.org/wiki/Georg_Plange_Weizenm%C3%BChlen"]}}'::jsonb)
WHERE slug = 'plange-muehle-fuenf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der PSD Bank Dome ist eine **Multifunktionshalle** im Düsseldorfer Stadtteil **Rath**. Die Halle wurde nach Entwürfen des Büros RKW Architektur + Städtebau gebaut und im September 2006 eröffnet. Bis Juni 2021 hieß sie ISS Dome, seit Juli 2021 trägt sie den Namen der PSD Bank.

Seit der Saison 2006/07 trägt die **Düsseldorfer EG** hier ihre Eishockey-Heimspiele aus. Bei Konzerten und anderen Veranstaltungen fasst die Halle bis zu 15.151 Menschen. Innerhalb von etwa acht Stunden lässt sie sich von einer Eishalle in eine **Konzerthalle** umbauen. Nach der Merkur Spiel-Arena ist sie die zweitgrößte Veranstaltungsstätte der Stadt.$txt$, webseite = COALESCE(webseite, 'https://www.psd-bank-dome.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/PSD_Bank_Dome", "https://de.wikipedia.org/wiki/PSD_Bank_Dome", "https://de.wikipedia.org/wiki/PSD_Bank_Dome", "https://de.wikipedia.org/wiki/PSD_Bank_Dome", "https://de.wikipedia.org/wiki/PSD_Bank_Dome", "https://www.visitduesseldorf.de/en/attractions/psd-bank-dome-c7539ebb18", "https://de.wikipedia.org/wiki/PSD_Bank_Dome"]}}'::jsonb)
WHERE slug = 'psd-bank-dome' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Raketenstation Hombroich** ist ein Kunst- und Kulturgelände bei Holzheim im Neusser Stadtgebiet, das der **Stiftung Insel Hombroich** gehört. Bis 1990 befand sich hier eine NATO-Raketenstellung, die ab 1967 von belgischen Luftstreitkräften betrieben wurde und an der auch US-Soldaten stationiert waren. Die Raketen wurden 1988 im Zuge des INF-Vertrags abgebaut und abtransportiert.

1994 erwarb **Karl-Heinrich Müller** das Areal und ließ die vorhandenen Gebäude umbauen, an der Gestaltung wirkten unter anderem Erwin Heerich, Katsuhito Nishikawa und Oliver Kruse mit. Heute leben und arbeiten auf dem Gelände Künstler, Komponisten, Schriftsteller und Wissenschaftler.

Zu den Bauten zählen **begehbare Skulpturen** von Erwin Heerich, umgenutzte ehemalige NATO-Gebäude mit Ateliers, das Haus für Musiker von Raimund Abraham, ein Pavillon von Álvaro Siza und das Teehaus „Ein Stein“ von Terunobu Fujimori. 2004 wurde auf dem Areal das von **Tadao Ando** entworfene Ausstellungshaus der Langen Foundation fertiggestellt.$txt$, webseite = COALESCE(webseite, 'https://www.inselhombroich.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Raketenstation_Hombroich", "https://de.wikipedia.org/wiki/Raketenstation_Hombroich", "https://de.wikipedia.org/wiki/Raketenstation_Hombroich", "https://de.wikipedia.org/wiki/Raketenstation_Hombroich", "https://de.wikipedia.org/wiki/Raketenstation_Hombroich", "https://www.inselhombroich.de/de/bauten/raketenstation/", "https://de.wikipedia.org/wiki/Raketenstation_Hombroich"]}}'::jsonb)
WHERE slug = 'raketenstation-hombroich' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Düsseldorfer Rathaus** steht am Marktplatz in der Altstadt nahe dem Rhein, in der Mitte des Platzes erhebt sich das Reiterstandbild des Kurfürsten Jan Wellem. Seit den 1570er-Jahren ist es ohne Unterbrechung Sitz von Stadtrat und Stadtverwaltung. Der Plenarsaal des Rates liegt im Gebäudeteil Marktplatz 2.

Das **Alte Rathaus** errichtete der Baumeister Heinrich Tussmann. Seine ältesten Teile stammen aus den Jahren 1570 bis 1573, bis 1806 tagten dort auch die Landstände von Jülich-Berg. Das benachbarte **Grupello-Haus** wurde von Matteo Alberti erbaut. 1888 kam das Neue Rathaus nach Plänen von Eberhard Westhofen hinzu, nach Schäden im Zweiten Weltkrieg wurde es in den 1960er-Jahren umgestaltet.

Das Rathaus steht unter **Denkmalschutz**. In der Adventszeit bildet der Platz rund um das Jan-Wellem-Denkmal die Kulisse für den Düsseldorfer Weihnachtsmarkt.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://www.visitduesseldorf.de/en/attractions/rathaus-town-hall-dc663bd47c", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Rathaus_D%C3%BCsseldorf", "https://www.visitduesseldorf.de/en/attractions/rathaus-town-hall-dc663bd47c"]}}'::jsonb)
WHERE slug = 'rathaus-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **reinraum** ist ein Kunst- und Kulturraum in einer ehemaligen **unterirdischen Toilettenanlage** unterhalb des Jahnplatzes in der Düsseldorfer Innenstadt. Betrieben wird er vom Verein reinraum e.V., der von der Initiative seiner Mitglieder lebt. Der Name ist den Reinräumen der Mikroelektronik entlehnt, in denen unter besonders sauberen Bedingungen gearbeitet wird.

Der Raum ist rund 60 Quadratmeter groß. Gezeigt werden **Ausstellungen**, etwa zu Streetart und Urban Art, daneben gibt es Konzerte und **Partys**.$txt$, webseite = COALESCE(webseite, 'https://reinraum-ev.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://reinraum-ev.de/verein/", "https://reinraum-ev.de/verein/", "https://reinraum-ev.de/verein/", "https://reinraum-ev.de/verein/", "https://reinraum-ev.de/"]}}'::jsonb)
WHERE slug = 'reinraum-e-v' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **RheinRiff** an der Hansaallee in Düsseldorf ist eine Freizeit- und Eventlocation rund um eine **Indoor-Surfwelle**. Auf rund 9.000 Quadratmetern gibt es dort außerdem einen **Beachclub**, Sportangebote und ein modulares Conference Center. Die stehende Welle vom Typ Citywave ist neun Meter breit und lässt sich unabhängig von Wetter und Jahreszeit surfen.

Das Surfangebot reicht von Kursen für Einsteiger ohne Vorerfahrung bis zu Sessions für erfahrene Surferinnen und Surfer. Daneben finden Partys, Afterwork-Abende und **Firmenevents** statt. Die nächste Haltestelle ist **D-Lörick**, von dort sind es wenige Gehminuten bis zum Eingang.$txt$, webseite = COALESCE(webseite, 'https://www.rheinriff.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.rheinriff.com/", "https://www.rheinriff.com/", "https://www.rheinriff.com/de/surf", "https://www.rheinriff.com/de/surf", "https://www.rheinriff.com/", "https://www.rheinriff.com/de/anfahrt"]}}'::jsonb)
WHERE slug = 'rheinriff' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der Rheinturm ist ein 240,5 Meter hoher **Fernmeldeturm** und das höchste Bauwerk Düsseldorfs. Er steht am östlichen Ende des **Medienhafens**, neben dem Landtag und der Rheinkniebrücke. Entworfen hat ihn Harald Deilmann im Auftrag der Deutschen Bundespost. Der öffentliche Aussichtsbereich wurde im März 1982 eröffnet.

Antennen auf dem Turm dienen dem Richtfunk sowie der Ausstrahlung von DVB-T-Fernsehen und UKW-Hörfunk. In 170 Metern Höhe liegt eine verglaste **Aussichtsebene** mit Panoramafenstern, in 174,5 Metern ein Restaurant, dessen Sitzbereich sich in etwa einer Stunde einmal um die eigene Achse dreht.

Am Schaft ist seit November 1981 der **Lichtzeitpegel** des Künstlers Horst H. Baumann angebracht, eine Lichtskulptur, die die Uhrzeit anzeigt. Das Guinness-Buch führt sie als größte dezimale Zeitskala der Welt.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm", "https://de.wikipedia.org/wiki/Rheinturm"]}}'::jsonb)
WHERE slug = 'rheinturm-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Rigpa Zentrum Düsseldorf** an der Kronprinzenstraße ist ein Zentrum der buddhistischen Gemeinschaft Rigpa. Sie steht in der Tradition des **tibetischen Buddhismus** und bietet einen strukturierten Weg zum Studium und zur Praxis der traditionellen Lehren. Die Gruppe in Düsseldorf besteht seit den 1980er-Jahren. Angeboten werden offene **Meditationsabende** sowie Kurse, die mehr Ruhe und Gelassenheit im Alltag fördern sollen.$txt$, webseite = COALESCE(webseite, 'https://www.rigpa.de/zentren/duesseldorf/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.rigpa.de/zentren/duesseldorf/", "https://www.rigpa.de/zentren/duesseldorf/", "https://www.rigpa.de/zentren/duesseldorf/", "https://www.rigpa.de/zentren/duesseldorf/"]}}'::jsonb)
WHERE slug = 'rigpa-zentrum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Robert Schumann Hochschule** ist eine Musikhochschule mit Sitz an der Fischerstraße im Stadtteil Golzheim. Ihre Wurzeln reichen bis zum 1902 gegründeten Buths-Neitzel-Konservatorium zurück. Seit 1987 ist sie eine eigenständige Kunsthochschule, seit 1989 hat sie das Promotionsrecht.

Das Gebäude an der Fischerstraße wurde 1975 eingeweiht. Zentraler Veranstaltungsort ist der 1993 eröffnete **Partika-Saal** mit rund 200 Plätzen. Zur Hochschule gehören Institute für Musikwissenschaft, für Komposition und Musiktheorie, für Musik und Medien sowie für **Kirchenmusik**. Die Opernschule tritt mindestens einmal im Jahr gemeinsam mit der Deutschen Oper am Rhein auf, Konzerte finden auch in der Tonhalle statt.$txt$, webseite = COALESCE(webseite, 'https://www.rsh-duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Robert_Schumann_Hochschule_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'robert-schumann-hochschule-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der Robert-Schumann-Saal ist der **Konzertsaal** im Museum Kunstpalast am **Ehrenhof**. Er wurde 2001 eröffnet und ist nach dem Komponisten Robert Schumann (1810–1856) benannt. Im selben Jahr wurde auch das Museum nach einem umfassenden Umbau durch den Architekten **Oswald Mathias Ungers** wiedereröffnet. Die 1998 gegründete Stiftung Museum Kunstpalast führte Kunstmuseum, Kunstpalast und Robert-Schumann-Saal unter einem Dach zusammen.

Der Saal hat eine Fläche von rund 600 Quadratmetern und bietet bis zu 796 Personen Platz. Zusammen mit dem angrenzenden **Foyer** wird er auch für Empfänge, Galas und Präsentationen vermietet. Das Gebäude geht auf einen ersten **Kunstpalast** von 1902 zurück, den Wilhelm Kreis 1926 zusammen mit Tonhalle, Rheinterrassen und dem heutigen NRW-Forum neu gestaltete.$txt$, webseite = COALESCE(webseite, 'https://www.kunstpalast.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.kunstpalast.de/en/corporate-events/", "https://sammlung.kunstpalast.de/objects/details/1068498", "https://www.kunstpalast.de/en/kunstpalast/", "https://www.kunstpalast.de/en/kunstpalast/", "https://www.kunstpalast.de/en/corporate-events/", "https://www.kunstpalast.de/en/corporate-events/", "https://www.kunstpalast.de/en/kunstpalast/"]}}'::jsonb)
WHERE slug = 'robert-schumann-saal' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Roncalli's Apollo Varieté** ist ein Varieté-Theater am Düsseldorfer Rheinufer, gegründet von Roncalli-Chef Bernhard Paul. Seit 1997 werden dort Abende mit Artistik, Akrobatik, Musik, Gesang, Tanz und Comedy gezeigt. Das Haus steht in einem **Glaskubus** unter der Rheinkniebrücke, entworfen von den Architekten Niklaus Fritschi, Benedikt Stahl und Günter Baum, die auch die angrenzende Rheinuferpromenade gestalteten.

Der **Saal** ist halbrund angelegt, die Tischreihen folgen dieser Form, sodass die Bühne von allen Plätzen frei zu sehen ist. Das Programm wechselt viermal im Jahr, dazu kommen Gastspiele und Sonderveranstaltungen. Zum Angebot gehört **Show & Dine**, bei dem ein Drei-Gänge-Menü über den Abend verteilt serviert wird.

Das Varieté liegt an der Rheinuferpromenade in der Nähe von Altstadt und Medienhafen. Die nächste Haltestelle ist **Landtag/Kniebrücke**, angefahren von Straßenbahn- und Buslinien der Rheinbahn.$txt$, webseite = COALESCE(webseite, 'https://www.apollo-variete.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/attractions/roncallis-apollo-variete-cb57ae8685", "https://www.visitduesseldorf.de/attraktionen/roncallis-apollo-variete-6b1db42646", "https://www.visitduesseldorf.de/attraktionen/roncallis-apollo-variete-6b1db42646", "https://www.apollo-variete.com/uber-uns/", "https://www.apollo-variete.com/uber-uns/", "https://www.apollo-variete.com/uber-uns/", "https://www.apollo-variete.com/uber-uns/", "https://www.apollo-variete.com/anfahrt-und-theaterkasse/"]}}'::jsonb)
WHERE slug = 'roncalli-s-apollo-variete' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Ruby Leni** ist ein Hotel mit Bar an der Jahnstraße, rund 200 Meter von der Königsallee entfernt. Es eröffnete im Mai 2019 mit 166 Zimmern, einem Café und einer Dachterrasse.

Das Gebäude entstand 1904 als Hotel, wurde 1910 zum **Düsseldorfer Operettenhaus** und diente von 1951 bis 1970 dem Düsseldorfer Schauspielhaus. Der Name erinnert an die Helena aus Gustaf Gründgens’ **Faust**-Inszenierung, die in den 1950er-Jahren in diesem Haus zu sehen war. Antike Requisiten, Kostüme und Vintage-Stücke in der Einrichtung greifen die Theatergeschichte auf.

In der **Lenis Bar** gibt es Cocktails und Live-Musik, Gäste können sich dort auch eine E-Gitarre leihen. Im Erdgeschoss liegt außerdem eine Terrasse.$txt$, webseite = COALESCE(webseite, 'https://www.ruby-hotels.com'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.tageskarte.io/hotellerie/detail/ruby-leni-hotel-eroeffnet-im-mai-in-duesseldorf.html", "https://www.tageskarte.io/hotellerie/detail/ruby-leni-hotel-eroeffnet-im-mai-in-duesseldorf.html", "https://www.tageskarte.io/hotellerie/detail/ruby-leni-hotel-eroeffnet-im-mai-in-duesseldorf.html", "https://www.visitduesseldorf.de/en/poi/detail/ruby-leni-hotel-duesseldorf-dfb739b9a5", "https://www.visitduesseldorf.de/en/poi/detail/ruby-leni-hotel-duesseldorf-dfb739b9a5", "https://www.visitduesseldorf.de/en/poi/detail/ruby-leni-hotel-duesseldorf-dfb739b9a5", "https://www.visitduesseldorf.de/en/poi/detail/ruby-leni-hotel-duesseldorf-dfb739b9a5"]}}'::jsonb)
WHERE slug = 'ruby-leni-hotel-bar' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Rundum Yoga ist ein **Yogastudio** in Düsseldorf mit Standorten in Unterbilk und Pempelfort. Das Studio in **Unterbilk** an der Kronenstraße eröffneten Susanne und Marc Wenke 2005 in einer ehemaligen Druckerei, zunächst unter dem Namen „Power Yoga & mehr“. Mit dem zweiten Studio in Pempelfort kam 2009 der heutige Name Rundum Yoga.

Das Kursangebot reicht von **Hatha**, Vinyasa und Yin Yoga bis zu Formaten wie Yoga Nidra, Rückenyoga sowie Kursen für Einsteiger und Schwangere. Außerdem bildet das Studio als bei der Yoga Alliance registrierte Schule **Yogalehrerinnen und Yogalehrer** aus, unter anderem in einer 200-Stunden-Multistyle-Ausbildung.$txt$, webseite = COALESCE(webseite, 'https://rundumyoga.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://rundumyoga.com/", "https://rundumyoga.com/the-story-behind/", "https://rundumyoga.com/the-story-behind/", "https://rundumyoga.com/", "https://rundumyoga.com/"]}}'::jsonb)
WHERE slug = 'rundum-yoga' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Saffrans** an der Collenbachstraße in Düsseldorf ist ein Kneipenrestaurant mit lokalen und internationalen Gerichten. Zum Angebot gehören außerdem **Brunch** sowie Feiern und Catering. Ausgeschenkt wird eine Auswahl an Weinen aus aller Welt. Für Feiern steht ein **Gesellschaftsraum** für bis zu 50 Personen zur Verfügung, der nach Angaben des Hauses aus dem Jahr 1900 stammt.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["http://www.saffrans.de/", "http://www.saffrans.de/", "http://www.saffrans.de/", "http://www.saffrans.de/"]}}'::jsonb)
WHERE slug = 'saffran-s' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Sammlung Philara ist ein öffentliches Ausstellungshaus für internationale **Gegenwartskunst** im Düsseldorfer Stadtteil **Flingern**. Gezeigt werden Werke aus der Sammlung des Düsseldorfer Kunstsammlers **Gil Bronner**, ergänzt durch Einzel- und Gruppenausstellungen. Seine ersten Ausstellungen organisierte Bronner ab 2008 in der ehemaligen Leitz-Fabrik in Düsseldorf-Reisholz.

Seit 2016 ist die Sammlung in der ehemaligen **Glaserei Lennarz** untergebracht. Den Umbau übernahm das Büro Sieber Architekten. Die Ausstellungsfläche umfasst rund 1.700 Quadratmeter, die Decken sind bis zu neun Meter hoch. Auf dem Dach liegt ein 550 Quadratmeter großer **Skulpturengarten** mit Café.$txt$, webseite = COALESCE(webseite, 'https://philara.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://philara.de/de/ueber-uns", "https://philara.de/de/ueber-uns", "https://philara.de/de/ueber-uns", "https://philara.de/de/ueber-uns", "https://philara.de/de/ueber-uns", "https://www.visitduesseldorf.de/attraktionen/sammlung-philara-8c07eaa082", "https://philara.de/de/ueber-uns"]}}'::jsonb)
WHERE slug = 'sammlung-philara' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Savoy Theater** liegt im Haus der Handelskammer an der Graf-Adolf-Straße. Es eröffnete im April 1958 als **Kino** „Savoy“ mit großer Breitwand und 70-Millimeter-Projektion. Im Untergeschoss kam im Mai 1958 das kleinere Atelier hinzu, das als Programmkino gedacht war. Später entstanden im Haus weitere kleine Säle wie Apollo 69, Die Lupe und Linse 2.

Nachdem in der Stadt mehrere Multiplex-Kinos eröffnet hatten, schloss der Kinokomplex im April 2000. Seit September 2000 wird das Savoy als **Kleinkunstbühne** genutzt. Im Untergeschoss läuft seit 2006 wieder das **Atelier** als Programmkino der Düsseldorfer Filmkunstkinos.$txt$, webseite = COALESCE(webseite, 'https://savoy-theater.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)", "https://de.wikipedia.org/wiki/Savoy_Theater_(D%C3%BCsseldorf)"]}}'::jsonb)
WHERE slug = 'savoy-theater' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Schloss Benrath** im Düsseldorfer Süden ist eine barocke Schlossanlage, die Kurfürst Karl Theodor von der Pfalz von 1755 bis 1771 errichten ließ. Die Pläne stammen von **Nicolas de Pigage**, die Innenräume zeigen den Übergang vom späten französischen Rokoko zum Klassizismus. Die dreiflügelige Anlage besteht aus dem zentralen Corps de Logis, zwei Kavaliershäusern und zwei Torhäusern.

Unter dem Dach der Stiftung Schloss und Park Benrath gibt es **drei Museen**: das Museum Corps de Logis, das Museum für Gartenkunst und das Naturkundemuseum. Das Museum für Europäische Gartenkunst im Ostflügel eröffnete 2002, das Naturkundemuseum ist seit 1929 im Westflügel untergebracht. Die Stiftung wurde im März 2000 gegründet und verwaltet Schloss und Park im Auftrag der Stadt Düsseldorf.

Der **Schlosspark** umfasst rund 61 Hektar, der westliche Jagdpark ist Naturschutzgebiet. Vor dem Schloss liegt der ovale Schlossweiher, die Hauptachse des Parks bildet der rund 470 Meter lange Spiegelweiher. Schloss und Park stehen seit 1984 unter Denkmalschutz.$txt$, webseite = COALESCE(webseite, 'https://www.schloss-benrath.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://www.schloss-benrath.de/", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath"]}}'::jsonb)
WHERE slug = 'schloss-benrath' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**SCHVARZ** ist eine Düsseldorfer **Kaffeerösterei**, die Specialty Coffee in kleinen Chargen röstet. Ihr Hauptsitz mit Rösterei, Werksverkauf und **Café** liegt im Gewerbegebiet Segro Park am Höherweg. Daneben bietet SCHVARZ Barista- und Filterkaffee-Kurse sowie Tastings an.$txt$, webseite = COALESCE(webseite, 'https://schvarz.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://schvarz.com/pages/roastery", "https://schvarz.com/pages/roastery", "https://schvarz.com/pages/roastery"]}}'::jsonb)
WHERE slug = 'schvarz-kaffee-hq' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Shidokan Dojo** liegt im Hof der Rethelstraße 28 und ist ein Trainingsort für traditionelles **Karate aus Okinawa**. Es wurde 2007 als **Europäisches Zentrum für Okinawa Shorinryu Shidokan Karatedo** eröffnet.

Der Stil Shorinryu wird als geschmeidig, aber explosiv beschrieben und setzt auf schnelle, kraftvolle Techniken, Körperspannung und Beweglichkeit. Neben Karate wird im Dojo auch **Kobudo** unterrichtet, die Waffenkunst mit Bo, Sai und Tonfa. Für Einsteiger gibt es Anfängerkurse.$txt$, webseite = COALESCE(webseite, 'https://www.shorinryu.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.shorinryu.de/", "https://www.shorinryu.de/", "https://www.shorinryu.de/eng/dojo-duesseldorf-eng.html", "https://www.shorinryu.de/eng/dojo-duesseldorf-eng.html", "https://www.shorinryu.de/eng/dojo-duesseldorf-eng.html"]}}'::jsonb)
WHERE slug = 'shidokan-dojo' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Smoney Hub** ist ein Treffpunkt der **Stadtsparkasse Düsseldorf** für junge Kundinnen und Kunden in der Sparkassen-Zentrale an der Berliner Allee. Eröffnet wurde er im Oktober 2022 auf rund 500 Quadratmetern, die zuvor ein Café belegte. Die Idee stammt aus einem Innovationswettbewerb der Sparkasse aus dem Jahr 2020, an dem Studierende, Auszubildende und Schüler teilnahmen.

Statt Schaltern und Geldautomaten gibt es Lounge-Sitzbereiche, schallgeschützte Besprechungskabinen und eine **Eventbühne**. In Gesprächen und Veranstaltungen geht es vor allem um Themen wie Karriere, Gründung und **Geldanlage**.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.it-finanzmagazin.de/smoney-hub-augenhoehe-junge-leute-stadtsparkasse-duesseldorf-146085/", "https://www.it-finanzmagazin.de/smoney-hub-augenhoehe-junge-leute-stadtsparkasse-duesseldorf-146085/", "https://www.it-finanzmagazin.de/smoney-hub-augenhoehe-junge-leute-stadtsparkasse-duesseldorf-146085/", "https://www.it-finanzmagazin.de/smoney-hub-augenhoehe-junge-leute-stadtsparkasse-duesseldorf-146085/", "https://www.it-finanzmagazin.de/smoney-hub-augenhoehe-junge-leute-stadtsparkasse-duesseldorf-146085/"]}}'::jsonb)
WHERE slug = 'smoney-hub' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Sponk Keramik** ist ein Keramikstudio an der Bilker Allee, in dem Keramik bemalt und getöpfert wird. Angeboten werden Malabende ebenso wie **Töpferkurse** an der Drehscheibe, außerdem ein Brennservice für Keramik. Für Gruppen bis 40 Personen gibt es Teamevents, Junggesellinnenabschiede und **Kindergeburtstage**. Zum Angebot gehört auch die Arbeit mit Ton für Menschen mit körperlichen Einschränkungen, mit psychologischer Begleitung.$txt$, webseite = COALESCE(webseite, 'https://www.sponkkeramik.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.sponkkeramik.de/", "https://www.sponkkeramik.de/", "https://www.sponkkeramik.de/", "https://www.sponkkeramik.de/"]}}'::jsonb)
WHERE slug = 'sponk-keramik-workshop' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **SPONTAN THEATER Studio** in Düsseldorf-Unterbilk ist der Düsseldorfer Standort einer Impro- und Theaterschule, die ein zweites Studio in der Kölner Neustadt-Süd betreibt. Im Studio an der Volmerswerther Straße gibt es eine eigene Bühnenfläche, auf der Kurse, Proben und Shows stattfinden. Die Schule ist aus der deutschsprachigen Sparte von **Expat Improv** hervorgegangen, unter dessen Namen in denselben Studios ein vergleichbares Kursprogramm auf Englisch läuft.

Das Angebot richtet sich an Erwachsene und reicht von **Schnupper- und Anfängerkursen** im Improvisationstheater über Fortgeschrittenenkurse bis zu thematischen Workshops. Daneben gibt es Kurse speziell für Menschen ab 60 sowie Workshops für Teams und Unternehmen. Das Studio liegt rund drei Gehminuten von der Haltestelle **Völklinger Straße** entfernt, die von S-Bahn und Straßenbahn angefahren wird.$txt$, webseite = COALESCE(webseite, 'https://spontantheater.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://spontantheater.de/improschule/", "https://spontantheater.de/kontakt/", "https://spontantheater.de/improschule/", "https://spontantheater.de/improschule/", "https://spontantheater.de/", "https://spontantheater.de/improschule/"]}}'::jsonb)
WHERE slug = 'spontan-theater-studio' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Benrath befindet sich in der **Orangerie** an der Urdenbacher Allee, ihr Lesecafé bietet einen Blick in den Schlosspark. Die Orangerie gilt zusammen mit dem Torgebäude an der Urdenbacher Allee als letzter Rest des älteren **Jagdschlosses Benrath**.

Auf 525 Quadratmetern Publikumsfläche bietet die Bücherei Medien für Kinder und Erwachsene, einen Kinder- und Jugendbereich und eine „Bibliothek der Dinge“. Neben Lesungen und Kindertheater finden Kunstausstellungen, Kabarett und Konzerte statt, in Zusammenarbeit mit dem Benrather Kulturkreis außerdem die Reihe **Montagsprosa**. In der Adventszeit veranstaltet die Bücherei einen großen Büchertrödel.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/benrath'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/stadtbuechereien/standorte/benrath", "https://de.wikipedia.org/wiki/Schloss_Benrath", "https://www.duesseldorf.de/stadtbuechereien/standorte/benrath", "https://www.duesseldorf.de/stadtbuechereien/standorte/benrath", "https://www.duesseldorf.de/stadtbuechereien/standorte/benrath"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-benrath' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Stadtteilbücherei Bilk** ist eine Filiale der Stadtbüchereien Düsseldorf an der **Friedrichstraße 127**. Sie befindet sich in den **Düsseldorf Arkaden**. Auf rund 440 Quadratmetern verteilt sich das Angebot über zwei Etagen.

Neben Büchern, Hörbüchern, DVDs und Spielen gibt es eine **Kinder- und Jugendbibliothek**, ein Lesecafé und Arbeitsplätze. Eine Besonderheit ist die **Bibliothek der Dinge**, in der Gegenstände statt Medien ausgeliehen werden. Regelmäßig finden Lesungen, Workshops und **Kamishibai**-Erzählstunden für Kinder statt.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/bilk'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.ddorf-aktuell.de/?p=99758", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk", "https://www.duesseldorf.de/stadtbuechereien/standorte/bilk"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-bilk' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Derendorf an der Blücherstraße wurde 1911 gegründet. Sie bietet 476 Quadratmeter Publikumsfläche auf zwei Ebenen, darunter eine Kinder- und eine **Familienbibliothek**, eine Saatgutbibliothek und ein Lesecafé. Neben Angeboten für Kinder wie Kindertheater und Bilderbuchkino gibt es **Ausstellungen**, einen Bücherflohmarkt sowie literarisch-musikalische Veranstaltungen und Konzerte für Erwachsene.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/derendorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://www.duesseldorf.de/stadtbuechereien/standorte/derendorf", "https://www.duesseldorf.de/stadtbuechereien/standorte/derendorf"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-derendorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Eller am **Gertrudisplatz** wurde 1923 eröffnet. Sie hat 350 Quadratmeter Publikumsfläche auf zwei Ebenen und ein **Lesecafé** mit großer Außenterrasse. Zum Bestand gehören Romane, Sachbücher, Hörbücher, DVDs und Spiele, zur Ausstattung eine Kinderbibliothek und ein Schülercenter. Auf dem Programm stehen unter anderem Bilderbuchkino, Lesungen, Konzerte, Kindertheater und Spieletage.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/eller'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://www.duesseldorf.de/stadtbuechereien/standorte/eller", "https://www.duesseldorf.de/stadtbuechereien/standorte/eller", "https://www.duesseldorf.de/stadtbuechereien/standorte/eller"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-eller' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Flingern an der Hoffeldstraße gehört zu den **Stadtbüchereien Düsseldorf** und wurde 1907 gegründet. Auf rund 500 Quadratmetern Publikumsfläche in zwei Ebenen bietet sie Medien für Kinder und Erwachsene, darunter Bücher, Hörbücher, DVDs, Spiele, Mangas und Comics. Zur Ausstattung gehören ein **Kinder- und Jugendbereich**, ein Schülercenter, ein Lesecafé und eine „Bibliothek der Dinge“. Das Veranstaltungsprogramm reicht von Bilderbuchkino und Kindertheater über Lesungen und Vorträge bis zu Kunstausstellungen.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/flingern'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://www.duesseldorf.de/stadtbuechereien/standorte/flingern", "https://www.duesseldorf.de/stadtbuechereien/standorte/flingern", "https://www.duesseldorf.de/stadtbuechereien/standorte/flingern"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-flingern' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Stadtteilbücherei Garath** liegt im **Kulturhaus Süd** an der Fritz-Erler-Straße. Sie umfasst 340 Quadratmeter auf vier Ebenen mit Lesecafé, Kinderbereich und eigener Jugendbücherei. Neben Büchern, Zeitschriften, Hörbüchern, Spielen, DVDs und Tonies gibt es eine Bibliothek der Dinge mit ausleihbaren Gegenständen für handwerklich-kreative Projekte.

Zum Programm gehören digitale Angebote wie Programmieren mit Lego Education, Bee-Bots und **3D-Druck**. Außerdem gibt es einen Gamingtreff, Workshops, Theater, Konzerte, Lesungen und ein Sprachcafé. Die Bücherei beteiligt sich zudem am Garather **Sonnenradfest**.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/garath'),
