WHERE slug = 'stadtbuecherei-garath' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Gerresheim an der Heyestraße wurde 1913 eröffnet. Sie versteht sich als **Literatur- und Kulturort** mitten in Gerresheim und erstreckt sich über zwei Etagen. Neben einer Kinder- und einer **Jugendbibliothek** gibt es ein Schülercenter und ein Lesecafé mit Tageszeitungen. Das Programm umfasst Kindertheater, Autorenlesungen und Bilderbuchkino sowie abendliche Lesungen, Vorträge und Vernissagen für Erwachsene.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/gerresheim'),
