WHERE slug = 'stadtbuecherei-gerresheim' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Kaiserswerth liegt am **Kaiserswerther Markt** und versteht sich als kultureller Treffpunkt in historischer Umgebung. Sie gehört seit der Eingemeindung Kaiserswerths im Jahr 1929 zu den Düsseldorfer Stadtbüchereien. Auf 268 Quadratmetern bietet sie Medien für alle Altersgruppen, außerdem einen kleinen Bestand an historischen Titeln und **Stadtteilinformationen** wie Jahrbücher und Stadtteilzeitungen. Zum Programm gehören neben Lesungen, Bilderbuchkino und Kindertheater auch Vorträge zu Kaiserswerth.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/kaiserswerth'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/stadtbuechereien/standorte/kaiserswerth", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://www.duesseldorf.de/stadtbuechereien/standorte/kaiserswerth", "https://www.duesseldorf.de/stadtbuechereien/standorte/kaiserswerth"]}}'::jsonb)
WHERE slug = 'stadtbuecherei-kaiserswerth' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Stadtbücherei Oberkassel an der **Luegallee** gehört seit der Eingemeindung Oberkassels 1920 zu den Düsseldorfer Stadtbüchereien und öffnete nach dem Zweiten Weltkrieg bereits 1947 wieder. Sie hat 400 Quadratmeter Publikumsfläche auf zwei Ebenen, mit Kinderbibliothek, Lesecafé und einer großen Krimi- und Thrillerabteilung. Für Kitas und Grundschulen bietet sie Leseförderung und **digitale Medienbildung** an, außerdem gibt es Kindertheater, Spielenachmittage, Lesungen und Vorträge.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien/standorte/oberkassel'),
