UPDATE public.orte SET beschreibung = $txt$Das **Storage Museum** ist ein Kunstraum mit eigener Sammlung an der Himmelgeister Straße in Düsseldorf. Im Frühjahr 2026 entwickelte es gemeinsam mit der **Stiftung IMAI** und dem benachbarten Stadtverband der Gehörlosen eine Ausstellung aus den Sammlungen beider Kunstinstitutionen.$txt$, webseite = COALESCE(webseite, 'https://storagemuseum.org'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://stiftung-imai.de/en/events/exhibitions/ich-sage-die-zeige-mit-den-zeichen-im-zeigen-der-sage", "https://stiftung-imai.de/en/events/exhibitions/ich-sage-die-zeige-mit-den-zeichen-im-zeigen-der-sage"]}}'::jsonb)
