UPDATE public.orte SET beschreibung = $txt$**StudioBrick** an der Worringer Straße ist ein Kreativstudio in **Loft-Atmosphäre**, das Workshops, Kurse und Gruppenevents anbietet. Im Mittelpunkt steht das **Keramikbemalen**, dazu kommen unter anderem Gießkeramik, Schmuckgestaltung, Häkeln, Sticken und Punch Needle, Linoldruck und Aquarell. Das Studio richtet außerdem Teamevents und Junggesellenabschiede aus und lässt sich auch mieten.$txt$, webseite = COALESCE(webseite, 'https://studio-brick.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://studio-brick.de/", "https://studio-brick.de/", "https://studio-brick.de/"]}}'::jsonb)
WHERE slug = 'studio-brick-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Studio Calma** ist ein Kreativ-Studio an der Münsterstraße in Düsseldorf, das zum Keramik- und Kunst-Onlineshop **Artibloom** gehört. Im **Open Studio** kann getöpfert und gemalt werden, die gebrannte Keramik wird einige Wochen später abgeholt. Hinzu kommen Kreativ-Workshops, etwa zu Punch Needling, Tufting, Häkeln oder dem Töpfern von Matcha-Schalen. Das Studio lässt sich außerdem für private Feiern wie Junggesellenabschiede, Teamevents, Geburtstage oder Weihnachtsfeiern buchen.$txt$, webseite = COALESCE(webseite, 'https://artibloom.de/pages/studio-calma'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://artibloom.de/pages/studio-calma", "https://artibloom.de/pages/studio-calma", "https://artibloom.de/pages/studio-calma", "https://artibloom.de/pages/studio-calma"]}}'::jsonb)
WHERE slug = 'studio-calma-by-artibloom-kreativ-studio-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Superblock Boulderhalle** an der Fichtenstraße bietet rund 1.000 Quadratmeter Fläche zum Bouldern. Etwa 200 **Boulder** in sechs Schwierigkeitsgraden werden wöchentlich neu gesetzt und richten sich an Einsteiger wie an Profis. Neben den Boulderwänden gibt es einen **Trainingsbereich**, ein Bistro und in den warmen Monaten einen Außenbereich mit Slackline. Angeboten werden außerdem Technikkurse, Kindergeburtstage, Angebote für Schulen und Firmen sowie Trainingsgruppen.$txt$, webseite = COALESCE(webseite, 'https://www.superblock.nrw/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.superblock.nrw/", "https://www.superblock.nrw/", "https://www.superblock.nrw/", "https://www.superblock.nrw/"]}}'::jsonb)
WHERE slug = 'superblock-boulderhalle' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Superfly Düsseldorf** ist ein **Trampolinpark** an der Kappeler Straße im Stadtteil **Reisholz**. Die Halle entstand auf einem ehemaligen Fabrikgelände und wurde im Oktober 2018 als achter und größter deutscher Standort von Superfly Air Sports eröffnet. Auf rund 5.000 Quadratmetern gibt es neben einer großen Trampolinfläche Hindernis- und Trampolin-Parcours.

Die Parcours erinnern an die Fernsehshow **Ninja Warrior**. Zum Angebot gehören außerdem Kindergeburtstage und Kurse, in denen Tricks auf dem Trampolin geübt werden.$txt$, webseite = COALESCE(webseite, 'https://www.superfly.de/duesseldorf'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ddorf-aktuell.de/?p=910", "https://www.ddorf-aktuell.de/?p=910", "https://www.ddorf-aktuell.de/?p=910", "https://www.ddorf-aktuell.de/?p=910", "https://www.superfly.de/duesseldorf"]}}'::jsonb)
WHERE slug = 'superfly-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Sportanlage an der Ernst-Poensgen-Allee in **Grafenberg** ist die vereinseigene Anlage des **Polizei-Sport-Vereins Düsseldorf**. Der Verein ist in elf Abteilungen von Boxen über Judo bis Volleyball organisiert und steht nicht nur Polizistinnen und Polizisten offen.

Auf der Anlage gibt es einen großen **Kunstrasenplatz**, einen Halbfeldplatz ebenfalls mit Kunstrasen und einen Hundesportplatz. Hier sind vor allem die Fußballmannschaften und die Abteilung Hundesport zu Hause. Sportplatz und Seminarraum können auch für Feiern gemietet werden. Der Verein richtet außerdem jährlich den **Düsseldorfer Brückenlauf** aus.$txt$, webseite = COALESCE(webseite, 'https://polizei-sv-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://polizei-sv-duesseldorf.de/verein/", "https://polizei-sv-duesseldorf.de/", "https://polizei-sv-duesseldorf.de/verein/", "https://polizei-sv-duesseldorf.de/verein/", "https://polizei-sv-duesseldorf.de/verein/", "https://polizei-sv-duesseldorf.de/"]}}'::jsonb)
WHERE slug = 'sv-polizei' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Tanzhaus NRW** ist ein Zentrum für zeitgenössischen Tanz und zugleich Spielort, Produktionsort und Akademie. Seine Anfänge reichen bis **1973** zurück, als eine Gruppe Düsseldorfer Künstlerinnen und Künstler den Grundstein legte, und 1978 entstand die „Werkstatt“, aus der das Haus hervorging. Seit **1998** ist es in einem alten Straßenbahndepot an der Erkrather Straße 30 untergebracht.

Auf rund 4.000 Quadratmetern gibt es zwei Bühnen sowie acht Tanz- und Probenstudios. Der **Große Saal** hat 318 Sitzplätze, der Kleine Saal 89. Als Produktionshaus für freischaffende Choreografinnen und Choreografen nimmt das Haus jedes Jahr Künstlerinnen, Künstler und Ensembles für Residenzen, Labs und Workshops auf. Das **Junge Tanzhaus** widmet sich dem Tanz für und mit jungem Publikum.

Die Akademie richtet sich an alle Generationen, rund 80 Dozentinnen und Dozenten unterrichten Stile von Urban Dance über zeitgenössischen Tanz bis Tap. Jeden Morgen findet ein **Professional Training** für Tanzschaffende statt. Die Haltestelle **Worringer Platz** liegt etwa fünf Gehminuten entfernt, der Hauptbahnhof rund zehn.$txt$, webseite = COALESCE(webseite, 'https://tanzhaus-nrw.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://de.wikipedia.org/wiki/Tanzhaus_NRW", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/haus/profil", "https://tanzhaus-nrw.de/de/dein-besuch"]}}'::jsonb)
WHERE slug = 'tanzhaus-nrw' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **TanzStudio HopSpot** ist ein Tanzstudio an der Adersstraße in Düsseldorf. Hier finden unter anderem die Düsseldorfer Kurse der **Kizomba**-Tanzschule KizMe statt.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://kizme.de/kursangebot", "https://kizme.de/kursangebot"]}}'::jsonb)
