UPDATE public.orte SET beschreibung = $txt$The Clay Company ist eine **Keramikwerkstatt** in Düsseldorf, die 2022 von Tanja Branisavljevic und Lea Starke gegründet wurde. Sie ist als **gemeinsamer Arbeitsraum** angelegt, in dem Mitglieder eigene Keramikprojekte umsetzen.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.cube-magazin.de/en/artikel/gradlinig-und-elegant/", "https://www.cube-magazin.de/en/artikel/gradlinig-und-elegant/"]}}'::jsonb)
WHERE slug = 'the-clay-company' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**The Craft Studio** ist ein Studio für **Kreativ-Workshops** in Düsseldorf. Zum Angebot gehören Kurse etwa zu Acrylmalerei, Kerzengießen, Linoldruck und Terrazzo-Gießkeramik. Der Eingang liegt am Stresemannplatz 4 über ein Café, die Anschrift lautet Mintropstraße 8.$txt$, webseite = COALESCE(webseite, 'https://www.the-craftstudio.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.the-craftstudio.de/", "https://www.the-craftstudio.de/", "https://www.the-craftstudio.de/"]}}'::jsonb)
WHERE slug = 'the-craft-studio-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**The Old Irish Pub** ist ein Pub im irischen Stil an der Bolkerstraße in der Düsseldorfer **Altstadt**. Er gehört zur Pub-Kette The Old Irish Pub. Auf dem Programm stehen **Livemusik** an mehreren Abenden der Woche und Karaoke, außerdem werden internationale Sportübertragungen auf großen Bildschirmen gezeigt.

Ausgeschenkt werden unter anderem Bier, Cider und Whiskey, darunter **Guinness** vom Fass. Neben dem regulären Betrieb finden dort auch Konzerte und private Feiern wie Firmenfeiern und Geburtstage statt.$txt$, webseite = COALESCE(webseite, 'https://oldirishpub.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/en/poi/detail/the-old-irish-pub-11b30a9f23", "https://oldirishpub.de/de/page/titelseite", "https://www.visitduesseldorf.de/en/poi/detail/the-old-irish-pub-11b30a9f23", "https://www.visitduesseldorf.de/en/poi/detail/the-old-irish-pub-11b30a9f23", "https://oldirishpub.de/de/page/titelseite"]}}'::jsonb)
WHERE slug = 'the-old-irish-pub' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **The Paris Club Bar** liegt im 25hours Hotel Das Tour am Louis-Pasteur-Platz, direkt über dem gleichnamigen Restaurant im 16. Stock. Von dort bietet sich ein **Panoramablick** über die Düsseldorfer Skyline. Ausgeschenkt werden ausschließlich **französische Spirituosen**, auch Klassiker wie Manhattan oder Negroni werden französisch interpretiert. Das Restaurant darunter serviert französische Küche, etwa Austern und am Tisch zubereitetes Tatar.$txt$, webseite = COALESCE(webseite, 'https://www.25hours-hotels.com/en/restaurants-bars/duesseldorf/the-paris-club'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.25hours-hotels.com/en/restaurants-bars/duesseldorf/the-paris-club", "https://www.25hours-hotels.com/en/restaurants-bars/duesseldorf/the-paris-club", "https://www.25hours-hotels.com/en/restaurants-bars/duesseldorf/the-paris-club", "https://www.25hours-hotels.com/en/restaurants-bars/duesseldorf/the-paris-club"]}}'::jsonb)
WHERE slug = 'the-paris-club-bar' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**The Vinyl Room** an der Ludenberger Straße in Düsseldorf-Gerresheim ist ein Plattenladen, der vor allem **Erstpressungen** verkauft. Hervorgegangen ist der Laden aus dem gleichnamigen deutschsprachigen YouTube-Kanal.

Schwerpunkte sind US-Erstpressungen aus Funk, Soul, Rock, Progressive Rock und Disco sowie deutsche und europäische Pressungen, Musik der 1980er-Jahre, **Krautrock** und Psychedelic Rock. Neben den Plattenkisten gibt es im Laden eine Sitzecke mit Bauhaus-Stühlen. Außerdem kauft der Laden Sammlungen und einzelne Platten an und betreibt einen **Onlineshop**.$txt$, webseite = COALESCE(webseite, 'https://www.the-vinyl-room.com/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.the-vinyl-room.com/", "https://www.the-vinyl-room.com/", "https://www.the-vinyl-room.com/", "https://www.the-vinyl-room.com/", "https://www.the-vinyl-room.com/"]}}'::jsonb)
WHERE slug = 'the-vinyl-room' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Theater an der Kö** ist ein Boulevardtheater in der Düsseldorfer Stadtmitte. Es befindet sich in den **Schadow-Arkaden** an der Schadowstraße, einem 1994 fertiggestellten Einkaufszentrum. Der Name verweist auf die nahe gelegene Königsallee, die in Düsseldorf kurz Kö genannt wird.

Eröffnet wurde das Haus im September 1994 mit der Komödie „Ausgerechnet Hamlet“ von Paul Rudnick. Der Saal bietet rund **400 Sitzplätze**. Ursprünglich war der Name „Theater in den Schadow Arkaden“ vorgesehen, der heutige Name soll auf eine Anregung des Schauspielers Peter Ustinov zurückgehen.

Das Programm besteht vor allem aus **Komödien**, die jeweils über mehrere Wochen laufen, sowie aus **Gastspielen** aus Kabarett und Comedy.$txt$, webseite = COALESCE(webseite, 'https://www.theateranderkoe.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://de.wikipedia.org/wiki/Theater_an_der_K%C3%B6", "https://www.theateranderkoe.de/"]}}'::jsonb)
WHERE slug = 'theater-an-der-koe' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Theater an der Luegallee** ist ein Privattheater im Stadtteil Oberkassel. Gegründet wurde es 1980 von Isolde Rasem in einem früheren **Möbellager**. Anfangs hatte es knapp 100 Plätze, seit 1999 sind es 75. Auf dem Spielplan stehen vor allem **Krimis**, Thriller, Komödien und Lesungen.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Theater_an_der_Luegallee", "https://de.wikipedia.org/wiki/Theater_an_der_Luegallee", "https://de.wikipedia.org/wiki/Theater_an_der_Luegallee", "https://de.wikipedia.org/wiki/Theater_an_der_Luegallee"]}}'::jsonb)
WHERE slug = 'theater-an-der-luegallee' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die Probenbühne an der Winkelsfelder Straße ist das Proben- und Produktionsstudio des **Theater der Klänge**. Das Theater der Klänge wurde 1987 in Düsseldorf gegründet und arbeitet als **freies Künstlerkollektiv**, das Text, Schauspiel, Tanz, Video und Livemusik verbindet. Betriebsbüro, Werkstätten und Probenstudio des Ensembles befinden sich seit 1991 in **Pempelfort**.

Der Hauptraum ist rund 135 Quadratmeter groß, hat **Tageslicht** durch eine Lichtkuppel und Fenster und ist mit einem Schwingboden ausgestattet. Über das Kulturamt der Stadt können auch geförderte Düsseldorfer **Tanz- und Theatergruppen** sowie Solokünstler den Raum für Proben anmieten.$txt$, webseite = COALESCE(webseite, 'https://www.theater-der-klaenge.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/kulturamt/foerderung/tanz-theater/winkelsfelderstrasse", "https://www.visitduesseldorf.de/attraktionen/theater-der-klaenge-58dea1f4e0", "https://www.visitduesseldorf.de/attraktionen/theater-der-klaenge-58dea1f4e0", "https://www.duesseldorf.de/kulturamt/foerderung/tanz-theater/winkelsfelderstrasse", "https://www.duesseldorf.de/kulturamt/foerderung/tanz-theater/winkelsfelderstrasse"]}}'::jsonb)
WHERE slug = 'theater-der-klaenge-probenbuehne' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Theaterfabrik** ist eine Spielstätte an der Luisenstraße in der Düsseldorfer **Friedrichstadt**, getragen vom Verein Theaterfabrik Düsseldorf. Das Publikum sitzt dort in Sesseln, und nach den Vorstellungen gibt es Gelegenheit zum Austausch mit den Künstlerinnen und Künstlern.

Gespielt werden zeitgenössische **Eigenproduktionen**, moderne und klassische Stücke, Musikabende, Performances und **Improvisationstheater**. Hinzu kommen Gastspiele anderer Ensembles und freier Theatergruppen. Außerdem bietet die Theaterfabrik Theaterkurse und Workshops an, etwa im Improvisationstheater.

Die nächste Straßenbahnhaltestelle ist **Mintropplatz**, vom Hauptbahnhof aus ist das Theater auch zu Fuß in wenigen Minuten erreichbar.$txt$, webseite = COALESCE(webseite, 'https://www.theaterfabrik.org/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.theaterfabrik.org/anfahrt/", "https://www.theaterfabrik.org/herzlich-willkommen-in-der-theaterfabrik/", "https://www.theaterfabrik.org/herzlich-willkommen-in-der-theaterfabrik/", "https://www.theaterfabrik.org/herzlich-willkommen-in-der-theaterfabrik/", "https://www.theaterfabrik.org/", "https://www.theaterfabrik.org/anfahrt/"]}}'::jsonb)
WHERE slug = 'theaterfabrik' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **TheaterLabor TraumGesicht** ist ein freier, gemeinnütziger Theaterverein mit eigener Bühne auf dem **Campus Golzheim** in Düsseldorf. Der Verein wurde 1985 in München gegründet und ist seit 2018 in Düsseldorf ansässig. Getragen wird das Haus von Mitgliedern sowie einem ehrenamtlichen Team und Vorstand.

Im Mittelpunkt stehen eigene Bühnenprojekte nach der Methode **Slow Acting**, die mit extremer Langsamkeit, Stille und atemrhythmischen Bewegungsformen arbeitet. Die Kostüme dafür entstehen in einer eigenen Kostümwerkstatt. Daneben gibt es **Workshops**, die als berufliche Weiterbildung anerkannt sind, sowie Gastspiele anderer Theatergruppen, Lesungen und Konzerte. Die Bühne wird auch von Studierenden der Robert Schumann Hochschule, der Heinrich-Heine-Universität und der Folkwang Universität der Künste genutzt.$txt$, webseite = COALESCE(webseite, 'https://www.theaterlabor-traumgesicht-ev.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/", "https://www.theaterlabor-traumgesicht-ev.de/ueber-uns-theaterlabor-traumgesicht-e-v-aus-duesseldorf/"]}}'::jsonb)
WHERE slug = 'theaterlabor-traumgesicht-e-v' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Theatermuseum Düsseldorf** ist ein städtisches Museum im **Hofgärtnerhaus** im Hofgarten, in der Nähe von Schauspielhaus und Deutscher Oper am Rhein. Den Grundstock bilden Materialien des Schauspielhauses Düsseldorf, die Louise Dumont und Gustav Lindemann von 1904 bis 1933 sammelten. Lindemann schenkte das „Dumont-Lindemann-Archiv“ 1947 der Stadt Düsseldorf. Seit 1981 trägt das Haus den Namen Theatermuseum, 1988 zog es ins Hofgärtnerhaus.

Die **Sammlung** umfasst unter anderem Fotos, Plakate, Programmhefte, Bühnenmodelle, Kostümentwürfe, Marionetten und Papiertheaterbögen sowie eine Fachbibliothek. Dazu gehört seit 2010 auch das Produktionsarchiv des Kom(m)ödchens. Zum Haus gehören die **Studiobühne Dumont** und das Café Louise. Auf der Studiobühne gibt es Gastspiele wie Puppentheater für Kinder, Erzählabende und Improtheater.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/theatermuseum'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Theatermuseum_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'theatermuseum-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Tonhalle** ist ein Konzerthaus am Rheinufer in Pempelfort und bildet den südlichen Abschluss des Kulturforums **Ehrenhof**. Der Rundbau entstand 1925/26 nach Plänen von **Wilhelm Kreis** als Mehrzweckhalle für die Ausstellung GeSoLei und hieß zunächst Rheinhalle. Das Gebäude war von Anfang an so angelegt, dass es auch als **Planetarium** dienen konnte.

Nach Kriegsschäden baute das Architekturbüro **HPP** um Helmut Hentrich von 1976 bis **1978** unter der rekonstruierten Kuppel einen fast halbkugelförmigen Konzertsaal ein. Im Jahr 2005 wurde das Haus erneut modernisiert. Der große Saal heißt seit 2014 **Mendelssohn-Saal** und hat 1.854 Plätze, dazu kommen ein Kammermusiksaal mit 300 Plätzen und die Rotunde im Foyer.

Die Tonhalle ist die Heimat der **Düsseldorfer Symphoniker**. Neben Klassik stehen auch Jazz und Kabarett auf dem Programm. In der Nähe liegt der U-Bahnhof **Tonhalle/Ehrenhof**.$txt$, webseite = COALESCE(webseite, 'https://www.tonhalle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://www.visitduesseldorf.de/attraktionen/tonhalle-duesseldorf-concert-hall-9b4f1d13f7", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf", "https://www.visitduesseldorf.de/attraktionen/tonhalle-duesseldorf-concert-hall-9b4f1d13f7", "https://de.wikipedia.org/wiki/Tonhalle_Düsseldorf"]}}'::jsonb)
WHERE slug = 'tonhalle-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **TRIBE Düsseldorf** ist ein Designhotel an der Graf-Adolf-Straße in unmittelbarer Nähe des **Hauptbahnhofs**. Es gehört zur Hotelmarke TRIBE der Accor-Gruppe. Untergebracht ist es in einem historischen Gebäude, dessen Fassade erhalten blieb und dessen Inneres modern gestaltet wurde.

Zum Haus gehören das Restaurant **TRIBE Table Cali** mit kalifornisch inspirierter Küche und die **TRIBE Bar**, die tagsüber Kaffee und abends Cocktails anbietet. Ein Social Hub mit Coworking-Bereich, ein Fitnessstudio und vier Tagungsräume ergänzen das Angebot.$txt$, webseite = COALESCE(webseite, 'https://all.accor.com/hotel/C1T5/index.de.shtml'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://all.accor.com/hotel/C1T5/index.de.shtml", "https://all.accor.com/hotel/C1T5/index.de.shtml", "https://all.accor.com/hotel/C1T5/index.de.shtml", "https://all.accor.com/hotel/C1T5/index.de.shtml", "https://all.accor.com/hotel/C1T5/index.de.shtml"]}}'::jsonb)
WHERE slug = 'tribe-hotel-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **UFA-Palast** an der Worringer Straße ist ein Kino direkt neben dem Düsseldorfer Hauptbahnhof. Er hat **13 Kinosäle** mit zusammen rund 2.850 Plätzen. Der größte Saal, Stage 8, bietet 504 Plätze, der kleinste Saal hat 122 Plätze. Neben dem regulären Programm gibt es Reihen wie das **Traumkino**, Anime-Vorstellungen und Übertragungen aus der Metropolitan Opera.$txt$, webseite = COALESCE(webseite, 'https://www.ufa-duesseldorf.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.ufa-duesseldorf.de/info/ueber-uns/", "https://www.ufa-duesseldorf.de/info/kinosaeale/", "https://www.ufa-duesseldorf.de/info/kinosaeale/", "https://www.ufa-duesseldorf.de/info/ueber-uns/"]}}'::jsonb)
WHERE slug = 'ufa-palast' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **VEN** ist das Restaurant mit Bar im Hotel **INNSiDE Düsseldorf Derendorf** an der Derendorfer Allee. Das Hotel liegt im Geschäftsviertel von Derendorf. Im Restaurant sorgen wandelbare Lichtsysteme für eine besondere Atmosphäre.$txt$, webseite = COALESCE(webseite, 'https://www.melia.com/de/hotels/deutschland/dusseldorf/innside-dusseldorf-derendorf/restaurants/ven-restaurant-and-bar'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/poi/detail/ven-restaurant-bar-im-melia-innside-duesseldorf-derendorf-f1d81ac3aa", "https://www.visitduesseldorf.de/poi/detail/ven-restaurant-bar-im-melia-innside-duesseldorf-derendorf-f1d81ac3aa", "https://www.visitduesseldorf.de/poi/detail/ven-restaurant-bar-im-melia-innside-duesseldorf-derendorf-f1d81ac3aa"]}}'::jsonb)
WHERE slug = 'ven-im-innside-duesseldorf-derendorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **Viertelladen** an der Neusser Straße in Düsseldorf-**Unterbilk** ist ein Ladenlokal, das vom Verein Viertelladen Freundeskreis e.V. betrieben wird. Er versteht sich als Treffpunkt für Kreative, Engagierte und Nachbarschaft und zeigt lokale, nachhaltige Produkte und Unikate. Das Ladenlokal dient dabei nicht nur dem Verkauf, sondern als offener **Mitmach-Ort** im Stadtteil.

Statt finden dort Konzerte, **Pop-up-Stores**, Ausstellungen und Workshops. Hinzu kommen Formate wie Lese- und Strickrunden, Gesprächsabende und Netzwerktreffen. Das Ladenlokal kann auch für eigene Veranstaltungen gemietet werden.$txt$, webseite = COALESCE(webseite, 'https://www.viertelladen.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.viertelladen.de/", "https://www.viertelladen.de/", "https://www.engagement-macht-stark.de/aktuelles/detail/viertelladen-freiraum-gemeinsam-gestalten/", "https://www.viertelladen.de/", "https://www.engagement-macht-stark.de/aktuelles/detail/viertelladen-freiraum-gemeinsam-gestalten/", "https://www.viertelladen.de/"]}}'::jsonb)
WHERE slug = 'viertelladen' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Vino Tinto & Friends** ist eine Weinhandlung an der Bagelstraße im Düsseldorfer Stadtteil **Pempelfort**. Gegründet wurde der Laden von Peter Heymanns, der sich dabei vom **spanischen Rotwein** inspirieren ließ.

Spanische Weine bilden weiterhin einen Schwerpunkt, das Sortiment umfasst aber Weine aus aller Welt sowie Craft Beer kleiner Brauereien und Spirituosen regionaler Hersteller. Verkosten lassen sich die Weine bei **Weinproben**, außerdem gibt es eine kleine Weinbar mit Terrasse. Für private Feiern kann ein Raum gemietet werden.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/storys/2022/05/13/sechs-weinlaeden-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2022/05/13/sechs-weinlaeden-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2022/05/13/sechs-weinlaeden-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2022/05/13/sechs-weinlaeden-in-duesseldorf/", "https://www.visitduesseldorf.de/storys/2022/05/13/sechs-weinlaeden-in-duesseldorf/"]}}'::jsonb)
WHERE slug = 'vino-tinto' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Volkshochschule Düsseldorf** ist ein Ort der Erwachsenenbildung, der Bildungsangebote für alle Menschen in der Stadt macht, jedes Jahr mit mehr als 4.000 Kursen, Seminaren, Workshops und Exkursionen. Das Programm reicht von Politik und Gesellschaft über IT, Sprachen, Musik und Kultur bis zu Gesundheit, Grundbildung und **beruflicher Bildung**.

Ihr zentraler Standort ist der **Yorcks Campus** an der Yorckstraße in Derendorf, ein umgebauter Bürokomplex. Mit dem Umzug sollten die drei bisherigen VHS-Standorte in Derendorf an einem Ort zusammengeführt werden. Geplant wurden 63 Unterrichtsräume, 24 Fachräume und eine Lehrküche, im Erdgeschoss Veranstaltungssäle, eine Cafeteria und eine Kinderbetreuung. Zwei **Dachgärten** dienen als Pausen- und Aufenthaltsflächen. Ende 2025 war der Umbau des Gebäudekomplexes abgeschlossen.$txt$, webseite = COALESCE(webseite, 'https://vhs.duesseldorf.de'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.visitduesseldorf.de/attraktionen/volkshochschule-duesseldorf-vhs-a1f2af02f8", "https://www.visitduesseldorf.de/attraktionen/volkshochschule-duesseldorf-vhs-a1f2af02f8", "https://www.ddorf-aktuell.de/?p=108830", "https://www.ddorf-aktuell.de/?p=108830", "https://www.ddorf-aktuell.de/?p=108830", "https://www.ddorf-aktuell.de/?p=108830", "https://www.konii.de/?p=190721"]}}'::jsonb)
WHERE slug = 'volkshochschule-duesseldorf' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Wetthalle** ist eine Veranstaltungshalle am Kulturanger auf dem Gelände der früheren Neusser **Galopprennbahn**. Die 1875 angelegte Rennbahn liegt östlich der Neusser Innenstadt, Rennen finden dort seit Ende 2019 nicht mehr statt. Im Auftrag der Neuss Marketing GmbH wurde die Halle zusammen mit Tribünengebäude, Totalisator und Globe im Vorfeld der **Landesgartenschau 2026** saniert. Dabei erhielt sie eine große Terrasse, moderne Licht- und Tontechnik, eine Lüftungsanlage und eine eigene Gastronomie.$txt$, webseite = COALESCE(webseite, 'https://www.eventlocation-wetthalle.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.neuss.de/fileadmin/Pressedienst/pdf/20250815-0_05.pdf", "https://de.wikipedia.org/wiki/Neusser_Rennbahn", "https://www.neuss.de/fileadmin/Pressedienst/pdf/20250815-0_05.pdf", "https://www.neuss.de/fileadmin/Pressedienst/pdf/20250815-0_05.pdf"]}}'::jsonb)
WHERE slug = 'wetthalle-neuss' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Der **WP8 Künstlerverein** gehört zu den Häusern der Kooperation **WPKultur** (Worringer Platz Kultur), in der sich benachbarte Kultureinrichtungen rund um den **Worringer Platz** zusammengeschlossen haben. Zu diesem Verbund zählen unter anderem auch das FFT Düsseldorf, das tanzhaus nrw, das Literaturbüro NRW und die Zentralbibliothek im KAP1.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.fft-duesseldorf.de/series-festivals/wpkultur-eng", "https://www.fft-duesseldorf.de/series-festivals/wpkultur-eng"]}}'::jsonb)
WHERE slug = 'wp8-kuenstlerverein' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **Xafé** ist das Bibliothekscafé der Zentralbibliothek im **KAP1** am Konrad-Adenauer-Platz, direkt am Düsseldorfer Hauptbahnhof. Das KAP1 ist ein ehemaliges Logistikgebäude der Post, in dem neben der Zentralbibliothek auch das FFT untergebracht ist.

Die Küche bietet Speisen mit arabischem, türkischem und mediterranem Einfluss, darunter auch **vegane** Gerichte, dazu Frühstück, Salate, Bowls und überwiegend selbst gebackenen Kuchen. Im Café ist Essen und Trinken erlaubt, die Stadt bezeichnet es als Herzstück der Zentralbibliothek. Gäste können das **WLAN** der Bibliothek nutzen.$txt$,
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.duesseldorf.de/stadtbuechereien/standorte/zentralbibliothek/kap1", "https://www.duesseldorf.de/stadtbuechereien/standorte/zentralbibliothek/kap1", "https://lokalbuero.com/2021/10/01/zentralbibliothek-im-kap1-mit-eigenem-bibliotheks-cafe/", "https://www.duesseldorf.de/stadtbuechereien/standorte/zentralbibliothek/kap1", "https://lokalbuero.com/2021/10/01/zentralbibliothek-im-kap1-mit-eigenem-bibliotheks-cafe/"]}}'::jsonb)
WHERE slug = 'xafe-in-kap-1-zentralbibliothek' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Yoga Kali** ist ein Yogastudio an der Corneliusstraße in Düsseldorf. Unterrichtet werden unter anderem **Vinyasa**, Yin, Rocket und Hatha Yoga für alle Niveaus. Dazu kommen Workshops und **Retreats** als Tages- und Wochenendformate. Der Studioraum lässt sich außerdem für eigene Kurse mieten und wird als Co-Working-Fläche angeboten.$txt$, webseite = COALESCE(webseite, 'https://yogakali.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://yogakali.de/", "https://yogakali.de/", "https://yogakali.de/", "https://yogakali.de/"]}}'::jsonb)
WHERE slug = 'yoga-kali' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**zehn null zwo** ist ein Kreativstudio an der Brehmstraße in Düsseldorf, das personalisierte Geschenke und **Textildruck** anbietet und Workshops zum Selbermachen veranstaltet. Gestaltet werden unter anderem Gläser, Tassen, Shirts und Karten, etwa für Hochzeiten, Geburtstage, Vereine oder Firmen. In den **Workshops** entstehen zum Beispiel Mosaike, Perlenschmuck, Wandbilder mit Strukturpaste oder bemalte Weingläser. Vor dem Umzug an die Brehmstraße war das Studio in Oberbilk ansässig.$txt$, webseite = COALESCE(webseite, 'https://zehnnullzwo.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://zehnnullzwo.de/", "https://zehnnullzwo.de/", "https://zehnnullzwo.de/", "https://zehnnullzwo.de/"]}}'::jsonb)
WHERE slug = 'zehn-null-zwo-kreativstudio' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **Zentralbibliothek** der Düsseldorfer Stadtbüchereien befindet sich im Gebäude **KAP1** am Konrad-Adenauer-Platz 1. Sie wurde im November 2021 in dem früheren Gebäude der Oberpostdirektion eröffnet, nachdem sie seit 1986 im Weiterbildungszentrum hinter dem Hauptbahnhof untergebracht war. Auf rund 8.000 Quadratmetern Publikumsfläche in zwei Etagen stehen mehr als 300.000 Medien bereit, darunter Bücher, CDs, DVDs, Spiele, digitale Medien und Noten.

Zum Angebot gehören eine **Kinder- und Jugendbibliothek** mit einem Baumhaus, rund 600 Arbeitsplätze, eine Saatgutbibliothek und eine „Bibliothek der Dinge“, in der selten gebrauchte Gegenstände entliehen werden können. Ergänzt wird das Haus durch einen 300 Quadratmeter großen **Dachgarten** und das Bibliothekscafé „Xafé“. 2023 zeichnete der Deutsche Bibliotheksverband die Zentralbibliothek als **„Bibliothek des Jahres“** aus.$txt$, webseite = COALESCE(webseite, 'https://www.duesseldorf.de/stadtbuechereien'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf", "https://de.wikipedia.org/wiki/Stadtb%C3%BCchereien_D%C3%BCsseldorf"]}}'::jsonb)
WHERE slug = 'zentralbibliothek-kap1' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Das **zentrum plus Holthausen** ist ein Treffpunkt für Menschen ab 55 Jahren mitten in Holthausen. Getragen wird es vom Arbeiter-Samariter-Bund Region Düsseldorf, gefördert vom Amt für Soziales und Jugend der Stadt. Untergebracht ist es in der früheren Gaststätte „Becker's“ an der Ecke Henkelstraße und Pfeillstraße.

Schwerpunkte sind **Beratung**, Bildung, Bewegung, Austausch und ehrenamtliches Engagement. Viele Gruppen organisieren sich selbst, etwa zum Singen, für Boccia, Kegeln oder Skat. Außerdem gibt es ein **Repair Café**, eine Sütterlin-Gruppe, einen Mundart-Treff und eine Archivgruppe zur Ortsgeschichte. Einen weiteren Schwerpunkt bilden Angebote für Menschen mit **Demenz**, darunter das inklusive KulturEck.$txt$, webseite = COALESCE(webseite, 'https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/", "https://www.asb-duesseldorf.de/unsere-angebote/aktiv-im-alter/zentrum-plus-holthausen/"]}}'::jsonb)
WHERE slug = 'zentrum-plus-holthausen' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$Die **ZERO foundation** ist eine Stiftung in Düsseldorf, die sich der Erhaltung, Erforschung und Präsentation der Kunst der ZERO-Bewegung widmet. Gegründet wurde sie 2008 von den ZERO-Künstlern **Heinz Mack, Otto Piene und Günther Uecker** gemeinsam mit dem Museum Kunstpalast. Die Künstlergruppe ZERO selbst war 1958 in Düsseldorf von Mack und Piene gegründet worden, Uecker kam 1961 hinzu.

Sitz der Stiftung ist das **ZERO-Haus** an der Hüttenstraße, das ehemalige Atelierhaus der ZERO-Künstler. Im Erdgeschoss lag das Atelier von Uecker, im ersten Obergeschoss das von Mack und im zweiten das von Piene. Die Stiftung unterhält dort ein **Archiv** mit den Vor- und Nachlässen der Stifter aus den Jahren 1957 bis 1968. Den Grundstock bildeten Werke und Dokumente wie Fotografien, Korrespondenzen und Ausstellungskritiken, die Mack, Piene und Uecker der Stiftung übergaben.$txt$, webseite = COALESCE(webseite, 'https://zerofoundation.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://zerofoundation.de/", "https://zerofoundation.de/", "https://de.wikipedia.org/wiki/ZERO", "https://zerofoundation.de/", "https://zerofoundation.de/", "https://zerofoundation.de/", "https://de.wikipedia.org/wiki/ZERO"]}}'::jsonb)
WHERE slug = 'zero-foundation' AND typ = 'spielstaette';
UPDATE public.orte SET beschreibung = $txt$**Zurheide Feine Kost** im Gebäudekomplex **Crown** an der Berliner Allee ist ein Lebensmittelmarkt mit gehobenem Sortiment in der Düsseldorfer Innenstadt. Der Markt wurde im März 2018 eröffnet und erstreckt sich über rund 10.000 Quadratmeter Gesamtfläche auf zwei Etagen. Angeboten werden mehr als 60.000 Produkte mit Schwerpunkt auf regionalen und ausgewählten Feinkost-Artikeln.

Zum Haus gehören mehrere **Gastronomie**-Bereiche, darunter ein Restaurant, eine Pâtisserie und eine Kaffee-Lounge. Zudem finden dort Genussveranstaltungen statt, etwa mit Auftritten von Spitzenköchen. Zurheide ist ein **Familienunternehmen**, das auf ein kleines Lebensmittelgeschäft in Bottrop zurückgeht.$txt$, webseite = COALESCE(webseite, 'https://www.zurheide-feine-kost.de/'),
  extras = jsonb_set(extras, '{spielstaette}', COALESCE(extras->'spielstaette', '{}'::jsonb) || '{"text_freigegeben": {"datum": "2026-11-20", "quellen": ["https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/", "https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/", "https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/", "https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/", "https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/", "https://www.zurheide-feine-kost.de/pressebeitrag/zurheide-feine-kost-neueroeffnung-crown/"]}}'::jsonb)
WHERE slug = 'zurheide-feine-kost' AND typ = 'spielstaette';

COMMIT;

-- Kontrolle: Ortsseiten mit freigegebenem Text
SELECT count(*) FILTER (WHERE extras->'spielstaette' ? 'text_freigegeben') AS mit_text,
       count(*) AS spielstaetten FROM public.orte WHERE typ = 'spielstaette';
